INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (1, 'MEU DEUS, MEU PAI', 'MEU DEUS, MEU PAI', 'MEU DEUS, MEU PAI,\nA TI CLAMO, MEU SENHOR,\nPELO SANGUE DE JESUS,\nDÁ-ME PAZ E COMUNHÃO.\n\nDÁ-ME PAZ E COMUNHÃO.', 'MEU DEUS, MEU PAI,<bis>\nA TI CLAMO, MEU SENHOR,<bis>\nPELO SANGUE DE JESUS,<bis>\nDÁ-ME PAZ E COMUNHÃO.<bis>\n\nDÁ-ME PAZ E COMUNHÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (2, 'PAI, ESTOU A TE CLAMAR', 'PAI, ESTOU A TE CLAMAR', 'PAI, ESTOU A TE CLAMAR,\nPEDINDO PERDÃO, SOCORRO,\nEU QUERO TE OUVIR.\n\nPAI, ENSINA-ME A ADORAR\nE A GLORIFICAR TEU NOME,\nEU QUERO TE AMAR.\n\nPAI, EU QUERO TE SERVIR,\nOH! DÁ-ME DA TUA GRAÇA\nE ME BASTARÁ, E ME BASTARÁ,\nE ME BASTARÁ.', 'PAI, ESTOU A TE CLAMAR,\nPEDINDO PERDÃO, SOCORRO,\nEU QUERO TE OUVIR.\n\nPAI, ENSINA-ME A ADORAR\nE A GLORIFICAR TEU NOME,\nEU QUERO TE AMAR.\n\nPAI, EU QUERO TE SERVIR,\nOH! DÁ-ME DA TUA GRAÇA\nE ME BASTARÁ, E ME BASTARÁ,\nE ME BASTARÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (3, 'CLAMO, Ó SENHOR, POR TEU SANGUE', 'CLAMO, Ó SENHOR, POR TEU SANGUE', 'CLAMO, Ó SENHOR, POR TEU SANGUE, (2X)\nSANGUE QUE POR MIM FOI VERTIDO,\nSANGUE DE UMA NOVA ALIANÇA.\n\nSENHOR, DERRAMA TEU SANGUE \nSOBRE MIM, Ó SENHOR.', 'CLAMO, Ó SENHOR, POR TEU SANGUE, <bis tipo=''2x''>\nSANGUE QUE POR MIM FOI VERTIDO,\nSANGUE DE UMA NOVA ALIANÇA.\n\nSENHOR, DERRAMA TEU SANGUE <bis>\nSOBRE MIM, Ó SENHOR.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (4, 'CLAMO, Ó SENHOR', 'CLAMO, Ó SENHOR', 'CLAMO, Ó SENHOR, \nPELO SANGUE DE JESUS,\nNA TUA PRESENÇA LIMPO QUERO ESTAR,\nE SÓ LAVADO NESTE SANGUE\nNO SANTO DOS SANTOS POSSO ENTRAR.\n\nLAVA-ME, SENHOR,\nVISITA-ME, SENHOR, \nCOM O ESPÍRITO SANTO,\nO CONSOLADOR.\nTEREI PLENA COMUNHÃO\nE A TUA PROTEÇÃO.\n\nE A TUA PROTEÇÃO.\nE A TUA PROTEÇÃO.', 'CLAMO, Ó SENHOR, \nPELO SANGUE DE JESUS,\nNA TUA PRESENÇA LIMPO QUERO ESTAR,\nE SÓ LAVADO NESTE SANGUE\nNO SANTO DOS SANTOS POSSO ENTRAR.\n\nLAVA-ME, SENHOR,<bis>\nVISITA-ME, SENHOR, <bis>\nCOM O ESPÍRITO SANTO,<bis>\nO CONSOLADOR.<bis>\nTEREI PLENA COMUNHÃO<bis>\nE A TUA PROTEÇÃO.<bis>\n\nE A TUA PROTEÇÃO.\nE A TUA PROTEÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (5, 'ESTOU AQUI PRA CONFESSAR', 'ESTOU AQUI PRA CONFESSAR', 'ESTOU AQUI PRA CONFESSAR\nA TI OS MEUS PECADOS,\nPRECISO DO TEU PERDÃO,\nDA TUA COMUNHÃO.\n\nESTOU AQUI PRA TE PEDIR:\nLIMPA MEU CORAÇÃO,\nCOMO A BRANCA LÃ\nTORNA-O, SENHOR.\n\nSUSTENTA-ME EM TUAS MÃOS, JESUS,\nPROTEGIDO EM TEUS BRAÇOS QUERO ESTAR;\nESCONDE-ME DE TODA A MALDADE\nE SEMPRE CONTIGO VOU ANDAR. (BIS)', 'ESTOU AQUI PRA CONFESSAR\nA TI OS MEUS PECADOS,\nPRECISO DO TEU PERDÃO,\nDA TUA COMUNHÃO.\n\nESTOU AQUI PRA TE PEDIR:\nLIMPA MEU CORAÇÃO,\nCOMO A BRANCA LÃ\nTORNA-O, SENHOR.\n\nSUSTENTA-ME EM TUAS MÃOS, JESUS,\nPROTEGIDO EM TEUS BRAÇOS QUERO ESTAR;\nESCONDE-ME DE TODA A MALDADE\nE SEMPRE CONTIGO VOU ANDAR. <bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (6, 'PERDOA-ME, SENHOR', 'PERDOA-ME, SENHOR', 'PERDOA-ME, SENHOR\nCLAMO PELO SANGUE DE JESUS\nQUERO RENOVAR\nA MINHA COMUNHÃO.\nPERDOA-ME, SENHOR,\nQUERO DEPOSITAR O MEU CORAÇÃO\nSEMPRE EM TEU ALTAR.\n\nVISITA-ME COM O TEU ESPÍRITO\nE FAZE-ME HABITAR\nAO TEU LADO ETERNAMENTE!', 'PERDOA-ME, SENHOR\nCLAMO PELO SANGUE DE JESUS\nQUERO RENOVAR\nA MINHA COMUNHÃO.\nPERDOA-ME, SENHOR,\nQUERO DEPOSITAR O MEU CORAÇÃO\nSEMPRE EM TEU ALTAR.\n\nVISITA-ME COM O TEU ESPÍRITO\nE FAZE-ME HABITAR\nAO TEU LADO ETERNAMENTE!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (7, 'É TEU SANGUE, MEU SENHOR JESUS', 'É TEU SANGUE, MEU SENHOR JESUS', 'É TEU SANGUE, MEU SENHOR JESUS,\nQUE GARANTE A NOSSA COMUNHÃO.\nÉ TEU SANGUE, MEU SENHOR JESUS,\nQUE NOS TRAZ LIBERTAÇÃO.\n\nPOR ISSO VOU CLAMAR E O SENHOR VAI ME \nPURIFICAR, E PRONTO \nESTAREI PRA SERVIR NA \nCASA DO MEU REI!', 'É TEU SANGUE, MEU SENHOR JESUS,\nQUE GARANTE A NOSSA COMUNHÃO.\nÉ TEU SANGUE, MEU SENHOR JESUS,\nQUE NOS TRAZ LIBERTAÇÃO.\n\nPOR ISSO VOU CLAMAR E O SENHOR VAI ME <bis>\nPURIFICAR, E PRONTO <bis>\nESTAREI PRA SERVIR NA <bis>\nCASA DO MEU REI!<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (8, 'DIANTE DO TEU ALTAR', 'DIANTE DO TEU ALTAR', 'DIANTE DO TEU ALTAR, SENHOR,\nOS MEUS JOELHOS VOU DOBRAR\nE POR TEU SANGUE VOU CLAMAR,\nPEDINDO: VEM PURIFICAR\nO MEU CORAÇÃO,QUE ESPERA \nEM TI COM GRATIDÃO!\n\nCORO\nEU CLAMO PELA VIDA,\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE \nVERTIDO NA CRUZ!\nEU CLAMO PELA VIDA\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE\nVERTIDO NA CRUZ!\n\nDIANTE DO TEU ALTAR, SENHOR,\nOS MEUS JOELHOS VOU DOBRAR\nE POR TEU SANGUE VOU CLAMAR,\nPEDINDO: VEM PURIFICAR\nO MEU CORAÇÃO,QUE ESPERA \nEM TI COM GRATIDÃO!\n\nCORO\nEU CLAMO PELA VIDA,\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE \nVERTIDO NA CRUZ!\nEU CLAMO PELA VIDA\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE\nVERTIDO NA CRUZ!', 'DIANTE DO TEU ALTAR, SENHOR,\nOS MEUS JOELHOS VOU DOBRAR\nE POR TEU SANGUE VOU CLAMAR,\nPEDINDO: VEM PURIFICAR\nO MEU CORAÇÃO,QUE ESPERA \nEM TI COM GRATIDÃO!\n\n<coro>\nEU CLAMO PELA VIDA,\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE \nVERTIDO NA CRUZ!\nEU CLAMO PELA VIDA\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE\nVERTIDO NA CRUZ!\n\nDIANTE DO TEU ALTAR, SENHOR,\nOS MEUS JOELHOS VOU DOBRAR\nE POR TEU SANGUE VOU CLAMAR,\nPEDINDO: VEM PURIFICAR\nO MEU CORAÇÃO,QUE ESPERA \nEM TI COM GRATIDÃO!\n\n<coro>\nEU CLAMO PELA VIDA,\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE \nVERTIDO NA CRUZ!\nEU CLAMO PELA VIDA\nA VIDA QUE HÁ EM TI, JESUS!\nPELO PODER DO SANGUE\nVERTIDO NA CRUZ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (9, 'DOBRO OS MEUS JOELHOS', 'DOBRO OS MEUS JOELHOS', 'DOBRO OS MEUS JOELHOS PARA A TI CLAMAR, SENHOR,\nTOCA O MEU INTERIOR, TOCA-ME, SENHOR,\nDIANTE DE TI ESTOU PARA TE ADORAR;\nGUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER\nCOM JESUS, MEU SENHOR\n\nDOBRO OS MEUS JOELHOS PARA A TI CLAMAR, SENHOR,\nTOCA O MEU INTERIOR, TOCA-ME, SENHOR,\nDIANTE DE TI ESTOU PARA TE ADORAR;\nGUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER \nCOM JESUS.\n\nFINAL:\nGUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER\nCOM JESUS, MEU SENHOR.', 'DOBRO OS MEUS JOELHOS PARA A TI CLAMAR, SENHOR,\nTOCA O MEU INTERIOR, TOCA-ME, SENHOR,\nDIANTE DE TI ESTOU PARA TE ADORAR;\nGUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER\nCOM JESUS, MEU SENHOR\n\nDOBRO OS MEUS JOELHOS PARA A TI CLAMAR, SENHOR,\nTOCA O MEU INTERIOR, TOCA-ME, SENHOR,\nDIANTE DE TI ESTOU PARA TE ADORAR;\nGUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER \nCOM JESUS.\n\n\n<final>GUIA-ME, SENHOR, PELO TEU AMOR,\nPAZ E SEGURANÇA QUERO TER\nCOM JESUS, MEU SENHOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (10, 'CLAMA, Ó IGREJA', 'CLAMA, Ó IGREJA', 'CLAMA, Ó IGREJA,\nCLAMA PELO SANGUE DE JESUS.\nNESTE SANGUE HÁ PODER,\nVIDA, PAZ, LIBERTAÇÃO,\nNESTE SANGUE PODEROSO HÁ PERDÃO.\n\nFINAL:\nNESSE SANGUE PODEROSO HÁ PERDÃO', 'CLAMA, Ó IGREJA,<bis>\nCLAMA PELO SANGUE DE JESUS.<bis>\nNESTE SANGUE HÁ PODER,<bis>\nVIDA, PAZ, LIBERTAÇÃO,<bis>\nNESTE SANGUE PODEROSO HÁ PERDÃO.\n<final>NESSE SANGUE PODEROSO HÁ PERDÃO', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (11, 'CLAMO A TI, MEU SENHOR E PAI (UMA NOVA CANÇÃO)', 'CLAMO A TI, MEU SENHOR E PAI (UMA NOVA CANÇÃO)', 'CLAMO A TI, MEU SENHOR E PAI \nE PROSTRADO AOS TEUS PÉS PEÇO\nPERDÃO. CLAMO PELO SANGUE DE\nJESUS SOBRE MIM E COM LOUVORES\nE CÂNTICOS TE ADORAREI. A TUA\nGRAÇA SEJA SOBRE MIM, MEU SENHOR, \nA TUA LUZ RESPLANDEÇA EM MIM.\n\nCOLOCA NOS MEUS LÁBIOS UMA NOVA\nCANÇÃO, UM HINO DE LOUVOR A DEUS\nPAI, A DEUS PAI. \nE PROSTRADO AOS TEUS PÉS\nEM PLENA COMUNHÃO, MEU\nSENHOR, RENOVA TEU ESPÍRITO\nSOBRE MIM. SOBRE NÓS.', 'CLAMO A TI, MEU SENHOR E PAI \nE PROSTRADO AOS TEUS PÉS PEÇO\nPERDÃO. CLAMO PELO SANGUE DE\nJESUS SOBRE MIM E COM LOUVORES\nE CÂNTICOS TE ADORAREI. A TUA\nGRAÇA SEJA SOBRE MIM, MEU SENHOR, \nA TUA LUZ RESPLANDEÇA EM MIM.\n\nCOLOCA NOS MEUS LÁBIOS UMA NOVA\nCANÇÃO, UM HINO DE LOUVOR A DEUS\nPAI, A DEUS PAI. \nE PROSTRADO AOS TEUS PÉS<bis>\nEM PLENA COMUNHÃO, MEU<bis>\nSENHOR, RENOVA TEU ESPÍRITO<bis>\nSOBRE MIM. SOBRE NÓS.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (10, 'PERDOA-ME, SENHOR SEGUNDO O SEU AMOR', 'PERDOA-ME, SENHOR SEGUNDO O SEU AMOR', 'PERDOA-ME SENHOR, SEGUNDO O\nSEU AMOR, LAVA-ME COM O SANGUE\nDE JESUS E ENVIA A TUA LUZ.\nPURIFICA-ME SENHOR, COM O SANGUE\nDE JESUS NOVA CRIATURA EM TI EU\nSOU PRONTO PARA O TEU LOUVOR.\n\nPOSSO AGORA TE ADORAR,\nPOSSO TE GLORIFICAR,\nMEU CORAÇÃO LIBERTO ESTÁ\nCHEIO DE ALEGRIA E PAZ.', 'PERDOA-ME SENHOR, SEGUNDO O\nSEU AMOR, LAVA-ME COM O SANGUE\nDE JESUS E ENVIA A TUA LUZ.\nPURIFICA-ME SENHOR, COM O SANGUE\nDE JESUS NOVA CRIATURA EM TI EU\nSOU PRONTO PARA O TEU LOUVOR.\n\nPOSSO AGORA TE ADORAR,<bis>\nPOSSO TE GLORIFICAR,<bis>\nMEU CORAÇÃO LIBERTO ESTÁ<bis>\nCHEIO DE ALEGRIA E PAZ.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (13, 'PURIFICADO COM SANGUE ESTOU', 'PURIFICADO COM SANGUE ESTOU', 'PURIFICADO COM SANGUE ESTOU,\nQUAL NEVE ME TORNOU;\nÁGUA DA VIDA EM JESUS BEBI, SATISFEITO ME SENTI. PARA JESUS, LÁ NA CRUZ, EU OLHEI,\nE O MEU FARDO AO CHÃO DEIXEI;\nCANTANDO VOU: GLÓRIA AO SENHOR! \nGLÓRIA A CRISTO, NOSSO DEUS!', 'PURIFICADO COM SANGUE ESTOU,<bis>\nQUAL NEVE ME TORNOU;<bis>\nÁGUA DA VIDA EM JESUS BEBI, SATISFEITO ME SENTI. PARA JESUS, LÁ NA CRUZ, EU OLHEI,<bis>\nE O MEU FARDO AO CHÃO DEIXEI;<bis>\nCANTANDO VOU: GLÓRIA AO SENHOR! <bis>\nGLÓRIA A CRISTO, NOSSO DEUS!<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (14, 'TE SUPLICO, Ó DEUS, EM ORAÇÃO', 'TE SUPLICO, Ó DEUS, EM ORAÇÃO', 'TE SUPLICO, Ó DEUS, EM ORAÇÃO.\nPOIS DESEJO DE TODO O CORAÇÃO\nENTENDER A TUA PALAVRA, \nTER SABEDORIA E TEMOR\nPARA PRESERVAR-ME \nNO TEU CAMINHO, SENHOR.\n\nCOMO PRATA E COMO O OURO BUSCAREI,\nCOMO UM TESOURO ESCONDIDO, PROCURAREI;\nA TUA PALAVRA ENTRARÁ EM MEU CORAÇÃO\nDANDO-ME A LEVEZA DO PERDÃO,\nOS TEUS MANDAMENTOS SUAVES \nSERÃO E UM LOUVOR DE GRATIDÃO \nENTOAREI A TI, SENHOR.', 'TE SUPLICO, Ó DEUS, EM ORAÇÃO.\nPOIS DESEJO DE TODO O CORAÇÃO\nENTENDER A TUA PALAVRA, \nTER SABEDORIA E TEMOR\nPARA PRESERVAR-ME \nNO TEU CAMINHO, SENHOR.\n\nCOMO PRATA E COMO O OURO BUSCAREI,<bis>\nCOMO UM TESOURO ESCONDIDO, PROCURAREI;<bis>\nA TUA PALAVRA ENTRARÁ EM MEU CORAÇÃO<bis>\nDANDO-ME A LEVEZA DO PERDÃO,<bis>\nOS TEUS MANDAMENTOS SUAVES <bis>\nSERÃO E UM LOUVOR DE GRATIDÃO <bis>\nENTOAREI A TI, SENHOR.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (15, 'JESUS VEM ME ABENÇOAR', 'JESUS VEM ME ABENÇOAR', 'JESUS, VEM ME ABENÇOAR,\nSENTIR A TUA FACE.\nJESUS, VEM FICAR PERTINHO,\nDAS CRIANÇAS VEM CUIDAR.\n\nJESUS É MEU, (3X)\nÉ ELE QUEM CUIDA DE MIM.', 'JESUS, VEM ME ABENÇOAR,\nSENTIR A TUA FACE.\nJESUS, VEM FICAR PERTINHO,\nDAS CRIANÇAS VEM CUIDAR.\n\nJESUS É MEU, <bis tipo=''3x''><bis>\nÉ ELE QUEM CUIDA DE MIM.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (16, 'PAI CELESTE', 'PAI CELESTE', 'PAI CELESTE, PAI CELESTE,\nVEM FICAR COMIGO,\nPAI CELESTE.\n\nJESUS CRISTO, JESUS CRISTO,\nVEM FICAR COMIGO,\nJESUS CRISTO.\n\nSANTO ESPÍRITO, SANTO ESPÍRITO,\nVEM FICAR COMIGO, SANTO ESPÍRITO.', 'PAI CELESTE, PAI CELESTE,\nVEM FICAR COMIGO,\nPAI CELESTE.\n\nJESUS CRISTO, JESUS CRISTO,\nVEM FICAR COMIGO,\nJESUS CRISTO.\n\nSANTO ESPÍRITO, SANTO ESPÍRITO,\nVEM FICAR COMIGO, SANTO ESPÍRITO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (17, 'QUANDO FALO COM DEUS', 'QUANDO FALO COM DEUS', 'QUANDO FALO COM DEUS AS LÁGRIMAS CORREM,\nA SUA PRESENÇA ME ENVOLVE TÃO FORTE,\nEM PAZ ME DEITO, PEGO NO SONO,\nPOIS EM SEUS BRAÇOS EU DESCANSO;\nBEM CEDO ACORDO E ME LEVANTO,\nPOIS SEI QUE JESUS ME SUSTENTOU.\n\nINSTRUMENTOS\n\nQUANDO FALO COM DEUS A LUZ ME ENVOLVE,\nTRANSPORTO PARA A ETERNIDADE,\nESTOU NO PLANO DE DEUS;\nPEÇO TODO DIA AO MEU SENHOR\nQUE SALVE A MINHA FAMÍLIA\nPRA JUNTOS LOUVARMOS\nAO BOM PASTOR\nQUE CUIDA DE NÓS COM AMOR. (BIS)', 'QUANDO FALO COM DEUS AS LÁGRIMAS CORREM,\nA SUA PRESENÇA ME ENVOLVE TÃO FORTE,\nEM PAZ ME DEITO, PEGO NO SONO,\nPOIS EM SEUS BRAÇOS EU DESCANSO;\nBEM CEDO ACORDO E ME LEVANTO,\nPOIS SEI QUE JESUS ME SUSTENTOU.\n<instrumentos>\n\n\nQUANDO FALO COM DEUS A LUZ ME ENVOLVE,\nTRANSPORTO PARA A ETERNIDADE,\nESTOU NO PLANO DE DEUS;\nPEÇO TODO DIA AO MEU SENHOR\nQUE SALVE A MINHA FAMÍLIA\nPRA JUNTOS LOUVARMOS\nAO BOM PASTOR\nQUE CUIDA DE NÓS COM AMOR. <bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (18, 'BUSCAI AO SENHOR', 'BUSCAI AO SENHOR', 'BUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO. \nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO.\n\nDEIXE O ÍMPIO O SEU CAMINHO,\nE O HOMEM MALIGNO OS SEUS PENSAMENTOS\nE SE CONVERTA AO SENHOR,\nQUE DELE SE COMPADECERÁ;\nTORNE PARA O NOSSO DEUS,\nPORQUE GRANDIOSO É EM PERDOAR.\n\nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO. \nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO.', 'BUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO. \nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO.\n\nDEIXE O ÍMPIO O SEU CAMINHO,\nE O HOMEM MALIGNO OS SEUS PENSAMENTOS\nE SE CONVERTA AO SENHOR,\nQUE DELE SE COMPADECERÁ;\nTORNE PARA O NOSSO DEUS,\nPORQUE GRANDIOSO É EM PERDOAR.\n\nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO. \nBUSCAI AO SENHOR \nENQUANTO SE PODE ACHAR,\nINVOCAI-O ENQUANTO ESTÁ PERTO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (19, 'QUANDO DAVI AO SENHOR ORAVA', 'QUANDO DAVI AO SENHOR ORAVA', 'QUANDO DAVI AO SENHOR ORAVA\nPRA JERUSALÉM ESTAVA O SEU OLHAR,\nPORQUE ELE SABIA QUE EM JERUSALÉM\nO NOME DO SENHOR FIRMADO ESTÁ.\n\nIGUAL DAVI, TAMBEM VOU ORAR\nOLHANDO PRA JERUSALÉM CELESTIAL,\nA CIDADE DE MEU REI E SENHOR,\nQUE DO SEU TRONO IRÁ RESPONDER\nÀ ORAÇÃO DE SEU SERVO FIEL.\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nQUANDO DAVI AO SENHOR ORAVA\nPRA JERUSALÉM ESTAVA O SEU OLHAR,\nPORQUE ELE SABIA QUE EM JERUSALÉM\nO NOME DO SENHOR FIRMADO ESTÁ.\n\nIGUAL DAVI, TAMBEM VOU ORAR\nOLHANDO PRA JERUSALÉM CELESTIAL,\nA CIDADE DE MEU REI E SENHOR,\nQUE DO SEU TRONO IRÁ RESPONDER\nÀ ORAÇÃO DE SEU SERVO FIEL.\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR', 'QUANDO DAVI AO SENHOR ORAVA\nPRA JERUSALÉM ESTAVA O SEU OLHAR,\nPORQUE ELE SABIA QUE EM JERUSALÉM\nO NOME DO SENHOR FIRMADO ESTÁ.\n\nIGUAL DAVI, TAMBEM VOU ORAR\nOLHANDO PRA JERUSALÉM CELESTIAL,\nA CIDADE DE MEU REI E SENHOR,\nQUE DO SEU TRONO IRÁ RESPONDER\nÀ ORAÇÃO DE SEU SERVO FIEL.\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nQUANDO DAVI AO SENHOR ORAVA\nPRA JERUSALÉM ESTAVA O SEU OLHAR,\nPORQUE ELE SABIA QUE EM JERUSALÉM\nO NOME DO SENHOR FIRMADO ESTÁ.\n\nIGUAL DAVI, TAMBEM VOU ORAR\nOLHANDO PRA JERUSALÉM CELESTIAL,\nA CIDADE DE MEU REI E SENHOR,\nQUE DO SEU TRONO IRÁ RESPONDER\nÀ ORAÇÃO DE SEU SERVO FIEL.\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR\n\nEU VOU ORAR, EU VOU ORAR,\nPORQUE EU SEI \nQUE MEU SENHOR VAI ME ESCUTAR', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (20, 'QUANDO ORO AO SENHOR', 'QUANDO ORO AO SENHOR', 'QUANDO ORO AO SENHOR\nSINTO PAZ EM MEU CORAÇÃO.\nSUA PRESENÇA É TÃO REAL,\nSUA GRAÇA ME SATISFAZ.\n\nPORQUE JESUS POR MIM MORREU\nE VIVO ESTÁ A INTERCEDER AO PAI POR MIM.\nPOSSO ENTÃO DESCANSAR,\nPORQUE EU SEI QUE O SENHOR\nTODO BEM FARÁ PRA MIM.\n\nFINAL: TODO BEM FARÁ PRA MIM.', 'QUANDO ORO AO SENHOR\nSINTO PAZ EM MEU CORAÇÃO.\nSUA PRESENÇA É TÃO REAL,\nSUA GRAÇA ME SATISFAZ.\n\nPORQUE JESUS POR MIM MORREU\nE VIVO ESTÁ A INTERCEDER AO PAI POR MIM.\nPOSSO ENTÃO DESCANSAR,<bis>\nPORQUE EU SEI QUE O SENHOR<bis>\nTODO BEM FARÁ PRA MIM.<bis>\n<final>TODO BEM FARÁ PRA MIM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (21, 'SANTO, JUSTO, PRÍNCIPE DA VIDA', 'SANTO, JUSTO, PRÍNCIPE DA VIDA', 'SANTO, JUSTO, PRÍNCIPE DA VIDA. \nFILHO DE DEUS, JESUS, EMANUEL. \nHOJE ESTÁ AQUI PARA LIBERTAR \nE ATRAVÉS DO SEU SANGUE\nENTRAMOS DIANTE DO PAI.', 'SANTO, JUSTO, PRÍNCIPE DA VIDA. \nFILHO DE DEUS, JESUS, EMANUEL. \nHOJE ESTÁ AQUI PARA LIBERTAR \nE ATRAVÉS DO SEU SANGUE<bis>\nENTRAMOS DIANTE DO PAI.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (22, 'FAZE ORAÇÃO', 'FAZE ORAÇÃO', 'FAZE ORAÇÃO BEM CEDINHO,\nAO MEIO DIA, SIM, TAMBÉM;\nFAZE ORAÇÃO À NOITINHA, \nQUE É DEUS QUE TE SUSTÉM. \n\nJÁ DE MANHÃ DEUS ESCUTA,\nAO MEIO DIA, SIM, TAMBÉM;\nMESMO TE VÊ A NOITINHA, \nDE TUDO TE SUSTÉM.\n\nJÁ DE MANHÃ DEUS RESPONDE,\nAO MEIO DIA, SIM, TAMBÉM;\nFAZE ORAÇÃO À NOITINHA, \nPOIS ELE LOGO VEM.', 'FAZE ORAÇÃO BEM CEDINHO,\nAO MEIO DIA, SIM, TAMBÉM;\nFAZE ORAÇÃO À NOITINHA, \nQUE É DEUS QUE TE SUSTÉM. \n\nJÁ DE MANHÃ DEUS ESCUTA,\nAO MEIO DIA, SIM, TAMBÉM;\nMESMO TE VÊ A NOITINHA, \nDE TUDO TE SUSTÉM.\n\nJÁ DE MANHÃ DEUS RESPONDE,\nAO MEIO DIA, SIM, TAMBÉM;\nFAZE ORAÇÃO À NOITINHA, \nPOIS ELE LOGO VEM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (23, 'QUANDO ISRAEL SAIU DO EGITO', 'QUANDO ISRAEL SAIU DO EGITO', 'QUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.\n\nELE ME FOI POR SALVAÇÃO,\nESTE É O MEU DEUS,\nLHE FAREI UMA HABITAÇÃO.\n\nAO SENHOR TAMBÉM LOUVAREI\nPORQUE É A MINHA SALVAÇÃO,\nMEU REFÚGIO, MINHA FORTALEZA,\nLHE FAREI UMA HABITAÇÃO\nNO MEU CORAÇÃO.\nINSTRUMENTOS\n\nQUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.\n\nELE ME FOI POR SALVAÇÃO,\nESTE É O MEU DEUS,\nLHE FAREI UMA HABITAÇÃO.\n\nAO SENHOR TAMBÉM LOUVAREI\nPORQUE É A MINHA SALVAÇÃO,\nMEU REFÚGIO, MINHA FORTALEZA,\nLHE FAREI UMA HABITAÇÃO\nNO MEU CORAÇÃO.\n\nQUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.', 'QUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.\n\nELE ME FOI POR SALVAÇÃO,\nESTE É O MEU DEUS,\nLHE FAREI UMA HABITAÇÃO.\n\nAO SENHOR TAMBÉM LOUVAREI\nPORQUE É A MINHA SALVAÇÃO,\nMEU REFÚGIO, MINHA FORTALEZA,\nLHE FAREI UMA HABITAÇÃO\nNO MEU CORAÇÃO.\n<instrumentos>\n\n\nQUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.\n\nELE ME FOI POR SALVAÇÃO,\nESTE É O MEU DEUS,\nLHE FAREI UMA HABITAÇÃO.\n\nAO SENHOR TAMBÉM LOUVAREI\nPORQUE É A MINHA SALVAÇÃO,\nMEU REFÚGIO, MINHA FORTALEZA,\nLHE FAREI UMA HABITAÇÃO\nNO MEU CORAÇÃO.\n\nQUANDO ISRAEL SAIU DO EGITO,\nISRAEL CANTOU, CANTOU:\nO SENHOR É A MINHA FORÇA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (24, 'UMA OVELHINHA DE JESUS EU SOU', 'UMA OVELHINHA DE JESUS EU SOU', 'UMA OVELHINHA DE JESUS EU SOU,\nSEMPRE ESTÁ COMIGO, É MEU BOM PASTOR;\nME MOSTRA O CAMINHO EM QUE DEVO ANDAR,\nÉ MEU AMADO SALVADOR.\n\nME LIVRA DO PERIGO, ESTENDE O SEU CAJADO,\nÉ MEU MELHOR AMIGO, DO MAL ESTOU GUARDADO;\nEM TODA A MINHA VIDA EU O AMAREI\nE PARA SEMPRE VIVEREI COM JESUS.\n\nE PARA SEMPRE VIVEREI COM JESUS.', 'UMA OVELHINHA DE JESUS EU SOU,\nSEMPRE ESTÁ COMIGO, É MEU BOM PASTOR;\nME MOSTRA O CAMINHO EM QUE DEVO ANDAR,\nÉ MEU AMADO SALVADOR.\n\nME LIVRA DO PERIGO, ESTENDE O SEU CAJADO,\nÉ MEU MELHOR AMIGO, DO MAL ESTOU GUARDADO;\nEM TODA A MINHA VIDA EU O AMAREI\nE PARA SEMPRE VIVEREI COM JESUS.\n\nE PARA SEMPRE VIVEREI COM JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (25, 'ONDE QUER QUE TU FORES IREI, JESUS', 'ONDE QUER QUE TU FORES IREI, JESUS', 'ONDE QUER QUE TU FORES IREI, JESUS,\nA TI MINHA ALMA JÁ DEI;\nSOU PARTE DO TEU CORPO,\nPERTENÇO AO TEU POVO,\nTU ÉS MEU REMIDOR.\n\nCORO\nA TUA PALAVRA ALIMENTA A ALMA DO PECADOR,\nCOLHEMOS EM TEU CAMPO, TRIGO, Ó SENHOR,\nDELÍCIAS EM TUA MESA E CÂNTICOS DE LOUVOR;\nALEGRO-ME CONTIGO, TU ÉS MEU REMIDOR.\n\nAJOELHO-ME A TEUS PÉS, AGRADEÇO A SALVAÇÃO\nQUE DE GRAÇA RECEBI, MEU SENHOR;\nTUA VOZ É PODEROSA,\nORDENAS BÊNÇÃOS PARA MIM\nE ME CONFORTAS NOS TEUS BRAÇOS DE AMOR.\n\nCORO\nA TUA PALAVRA ALIMENTA A ALMA DO PECADOR,\nCOLHEMOS EM TEU CAMPO, TRIGO, Ó SENHOR,\nDELÍCIAS EM TUA MESA E CÂNTICOS DE LOUVOR;\nALEGRO-ME CONTIGO, TU ÉS MEU REMIDOR.', 'ONDE QUER QUE TU FORES IREI, JESUS,\nA TI MINHA ALMA JÁ DEI;\nSOU PARTE DO TEU CORPO,\nPERTENÇO AO TEU POVO,\nTU ÉS MEU REMIDOR.\n\n<coro>\nA TUA PALAVRA ALIMENTA A ALMA DO PECADOR,\nCOLHEMOS EM TEU CAMPO, TRIGO, Ó SENHOR,\nDELÍCIAS EM TUA MESA E CÂNTICOS DE LOUVOR;\nALEGRO-ME CONTIGO, TU ÉS MEU REMIDOR.\n\nAJOELHO-ME A TEUS PÉS, AGRADEÇO A SALVAÇÃO\nQUE DE GRAÇA RECEBI, MEU SENHOR;\nTUA VOZ É PODEROSA,\nORDENAS BÊNÇÃOS PARA MIM\nE ME CONFORTAS NOS TEUS BRAÇOS DE AMOR.\n\n<coro>\nA TUA PALAVRA ALIMENTA A ALMA DO PECADOR,\nCOLHEMOS EM TEU CAMPO, TRIGO, Ó SENHOR,\nDELÍCIAS EM TUA MESA E CÂNTICOS DE LOUVOR;\nALEGRO-ME CONTIGO, TU ÉS MEU REMIDOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (26, 'EU SOU UMA OVELHINHA', 'EU SOU UMA OVELHINHA', 'EU SOU UMA OVELHINHA DE JESUS,\nEU SOU UMA OVELHINHA DE JESUS.\nJESUS É O BOM PASTOR,\nJESUS CUIDA DE MIM.\nEU SOU UMA OVELHINHA\nDO SENHOR.\n\nBEM CEDO, AO LEVANTAR, EU VOU ORAR,\nAGRADECER A NOITE QUE ME DEU;\nEU LOUVO COM AMOR\nE DIGO SEMPRE ASSIM:\nEU SOU UM PEQUENINO DO SENHOR,\nEU SOU UM PEQUENINO DO SENHOR.', 'EU SOU UMA OVELHINHA DE JESUS,\nEU SOU UMA OVELHINHA DE JESUS.\nJESUS É O BOM PASTOR,\nJESUS CUIDA DE MIM.\nEU SOU UMA OVELHINHA\nDO SENHOR.\n\nBEM CEDO, AO LEVANTAR, EU VOU ORAR,\nAGRADECER A NOITE QUE ME DEU;\nEU LOUVO COM AMOR\nE DIGO SEMPRE ASSIM:\nEU SOU UM PEQUENINO DO SENHOR,\nEU SOU UM PEQUENINO DO SENHOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (27, 'ELE É A RAIZ DE DAVI', 'ELE É A RAIZ DE DAVI', 'ELE É A RAIZ, A RAIZ DE DAVI,\nELE É O LEÃO, O LEÃO DE JUDÁ,\nELE É A RAIZ, A RAIZ DE DAVI,\nMARAVILHOSO, CONSELHEIRO, \nPRÍNCIPE DA PAZ.\n\nE AGORA QUAL É A RAZÃO DA MINHA FÉ?\n(EU VOU DIZER)\nSIM, CRISTO, MEU AMADO SALVADOR.\n\nFINAL: SIM, CRISTO, MEU AMADO SALVADOR.', 'ELE É A RAIZ, A RAIZ DE DAVI,\nELE É O LEÃO, O LEÃO DE JUDÁ,\nELE É A RAIZ, A RAIZ DE DAVI,\nMARAVILHOSO, CONSELHEIRO, \nPRÍNCIPE DA PAZ.\n\nE AGORA QUAL É A RAZÃO DA MINHA FÉ?<bis>\n(EU VOU DIZER)<bis>\nSIM, CRISTO, MEU AMADO SALVADOR.<bis>\n<final>SIM, CRISTO, MEU AMADO SALVADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (28, 'SOU UMA CRIANÇA FELIZ', 'SOU UMA CRIANÇA FELIZ', 'SOU UMA CRIANÇA FELIZ\nPORQUE TENHO JESUS EM MEU CORAÇÃO,\nCOMO PROVA DESTE AMOR TÃO GRANDE\nEU CANTO AO MEU SENHOR\nUMA NOVA CANÇÃO.\n\nCORO \nUMA CANÇÃO DE AMOR\nQUE EXPRESSA A MINHA GRATIDÃO,\nOH! QUERIDO SALVADOR,\nPELA GRANDE SALVAÇÃO.\n\nJESUS, TU ÉS MELHOR QUE TUDO\nO QUE EXISTE DE MAIS PRECIOSO,\nNADA PODE SE COMPARAR A ESTE AMOR\nQUE FLUI DE UM DEUS TÃO MARAVILHOSO.\n\nCORO \nUMA CANÇÃO DE AMOR\nQUE EXPRESSA A MINHA GRATIDÃO,\nOH! QUERIDO SALVADOR,\nPELA GRANDE SALVAÇÃO.', 'SOU UMA CRIANÇA FELIZ\nPORQUE TENHO JESUS EM MEU CORAÇÃO,\nCOMO PROVA DESTE AMOR TÃO GRANDE\nEU CANTO AO MEU SENHOR\nUMA NOVA CANÇÃO.\n\n<coro>\nUMA CANÇÃO DE AMOR<bis>\nQUE EXPRESSA A MINHA GRATIDÃO,<bis>\nOH! QUERIDO SALVADOR,<bis>\nPELA GRANDE SALVAÇÃO.<bis>\n\nJESUS, TU ÉS MELHOR QUE TUDO\nO QUE EXISTE DE MAIS PRECIOSO,\nNADA PODE SE COMPARAR A ESTE AMOR\nQUE FLUI DE UM DEUS TÃO MARAVILHOSO.\n\n<coro>\nUMA CANÇÃO DE AMOR<bis>\nQUE EXPRESSA A MINHA GRATIDÃO,<bis>\nOH! QUERIDO SALVADOR,<bis>\nPELA GRANDE SALVAÇÃO.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (29, 'JESUS, QUANDO ME LEMBRO', 'JESUS, QUANDO ME LEMBRO', 'JESUS, QUANDO ME LEMBRO\nDO DIA EM QUE A TI ME ENTREGUEI,\nLEMBRO DO CALOR QUE SENTIA\nE DO AMOR QUE ME INVADIA,\nLEMBRO QUE A PALAVRA ABRIA\nE TUA VOZ OUVIA DIZER:\n\n''VINDE A MIM,\nOS CANSADOS E OPRIMIDOS,\nE EU VOS ALIVIAREI.\nVINDE A MIM,\nOS CANSADOS E OPRIMIDOS,\nE EU VOS ALIVIAREI.''', 'JESUS, QUANDO ME LEMBRO\nDO DIA EM QUE A TI ME ENTREGUEI,\nLEMBRO DO CALOR QUE SENTIA\nE DO AMOR QUE ME INVADIA,\nLEMBRO QUE A PALAVRA ABRIA\nE TUA VOZ OUVIA DIZER:\n\n''VINDE A MIM,\nOS CANSADOS E OPRIMIDOS,\nE EU VOS ALIVIAREI.\nVINDE A MIM,\nOS CANSADOS E OPRIMIDOS,\nE EU VOS ALIVIAREI.''', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (30, 'ELE VIVE EM MIM', 'ELE VIVE EM MIM', 'ELE VIVE EM MIM, (BIS)\nA FLOR DO JARDIM, JESUS,\nELE VIVE EM MIM.\n\nELE É O MEU REI, (BIS)\nSÓ A ELE SERVIREI, ELE É MEU REI.\n\nELE VAI VOLTAR, (BIS)\nVEM A CRISTO SEM TARDAR, \nELE VAI VOLTAR.', 'ELE VIVE EM MIM, <bis>\nA FLOR DO JARDIM, JESUS,\nELE VIVE EM MIM.\n\nELE É O MEU REI, <bis>\nSÓ A ELE SERVIREI, ELE É MEU REI.\n\nELE VAI VOLTAR, <bis>\nVEM A CRISTO SEM TARDAR, \nELE VAI VOLTAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (31, 'EU QUERO SER O SAL DA TERRA', 'EU QUERO SER O SAL DA TERRA', 'EU QUERO SER O SAL DA TERRA,\nEU QUERO SER A LUZ DO MUNDO,\nEU QUERO SER O SAL DA TERRA,\nEU QUERO SER A LUZ DO MUNDO.\n\nEU QUERO BRILHAR, \nEU QUERO BRILHAR, \nEU QUERO BRILHAR ATÉ JESUS\nVOLTAR.', 'EU QUERO SER O SAL DA TERRA,\nEU QUERO SER A LUZ DO MUNDO,\nEU QUERO SER O SAL DA TERRA,\nEU QUERO SER A LUZ DO MUNDO.\n\nEU QUERO BRILHAR, <bis>\nEU QUERO BRILHAR, <bis>\nEU QUERO BRILHAR ATÉ JESUS<bis>\nVOLTAR.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (32, 'PRÍNCIPE DA PAZ', 'PRÍNCIPE DA PAZ', 'PRÍNCIPE DA PAZ, QUERO TE AMAR,\nTEUS MANDAMENTOS, SIM,\nTODOS GUARDAR;\nÓ DEUS, VEM AJUDAR-ME\nA FAZER TUA VONTADE\nE EM TUDO TEU NOME LOUVAR.\n\nJESUS REDENTOR,\nQUERO TE ADORAR\nEM ESPÍRITO E EM VERDADE;\nÓ DEUS, VEM ENSINAR-ME\nA LOUVAR TUA GRANDEZA\nE BENDIZER TEU NOME,\nÓ SENHOR!', 'PRÍNCIPE DA PAZ, QUERO TE AMAR,\nTEUS MANDAMENTOS, SIM,\nTODOS GUARDAR;\nÓ DEUS, VEM AJUDAR-ME\nA FAZER TUA VONTADE\nE EM TUDO TEU NOME LOUVAR.\n\nJESUS REDENTOR,\nQUERO TE ADORAR\nEM ESPÍRITO E EM VERDADE;\nÓ DEUS, VEM ENSINAR-ME\nA LOUVAR TUA GRANDEZA\nE BENDIZER TEU NOME,\nÓ SENHOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (33, 'CRISTO, MEU BOM MESTRE', 'CRISTO, MEU BOM MESTRE', 'CRISTO, MEU BOM MESTRE,\nEU TE AMO E TE QUERO;\nEU TE ADORO, MEU SENHOR E REI.\n\nSENHOR (SENHOR), MEU REI,\nSENHOR (SENHOR), MEU REI. \n\nREPETIR O HINO', 'CRISTO, MEU BOM MESTRE,<bis>\nEU TE AMO E TE QUERO;<bis>\nEU TE ADORO, MEU SENHOR E REI.<bis>\n<bis>\nSENHOR (SENHOR), MEU REI,\nSENHOR (SENHOR), MEU REI.\n\n<repetir tipo=''O HINOx''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (34, 'TENHO UM SENHOR MUITO FORTE', 'TENHO UM SENHOR MUITO FORTE', 'TENHO UM SENHOR MUITO FORTE, \nVENCEU A MORTE\nPARA ME DAR UM LUGAR LÁ NO CÉU.\n\nESTE SENHOR É JESUS QUE ME CONDUZ\nPARA UM LAR DE GOZO E DE PAZ.\n\nQUERO SERVI-LO, QUERO LOUVÁ-LO,\nJUSTO SENHOR, DEUS FORTE, MARAVILHOSO,\nCONSELHEIRO, PAI DA ETERNIDADE,\nPRÍNCIPE DA PAZ, JESUS.', 'TENHO UM SENHOR MUITO FORTE, \nVENCEU A MORTE\nPARA ME DAR UM LUGAR LÁ NO CÉU.\n\nESTE SENHOR É JESUS QUE ME CONDUZ\nPARA UM LAR DE GOZO E DE PAZ.\n\nQUERO SERVI-LO, QUERO LOUVÁ-LO,\nJUSTO SENHOR, DEUS FORTE, MARAVILHOSO,\nCONSELHEIRO, PAI DA ETERNIDADE,\nPRÍNCIPE DA PAZ, JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (35, 'QUERO SER COMO DAVI', 'QUERO SER COMO DAVI', 'QUERO SER COMO DAVI,\nTÃO PEQUENINO, \nNÃO CONFIAVA EM SI;\nQUERO SER TEMENTE A DEUS\nE ASSIM VENCER O FILISTEU.', 'QUERO SER COMO DAVI,\nTÃO PEQUENINO, \nNÃO CONFIAVA EM SI;\nQUERO SER TEMENTE A DEUS\nE ASSIM VENCER O FILISTEU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (36, 'EU QUERO ANDAR SEMPRE COM JESUS', 'EU QUERO ANDAR SEMPRE COM JESUS', 'EU QUERO ANDAR SEMPRE COM JESUS,\nÀ ETERNIDADE ELE ME CONDUZ;\nE QUANDO A LUTA TIVER QUE ENFRENTAR\nELE ESTARÁ A ME PROTEGER.\n\nSUSTENTA-ME, PEGA A MINHA MÃO,\nLEVANTA-ME, DÁ-ME A SALVAÇÃO;\nCRESCER COM ELE É O MAIOR TESOURO,\nTRABALHAR PRA ELE É A MINHA ADORAÇÃO. (2X)', 'EU QUERO ANDAR SEMPRE COM JESUS,\nÀ ETERNIDADE ELE ME CONDUZ;\nE QUANDO A LUTA TIVER QUE ENFRENTAR\nELE ESTARÁ A ME PROTEGER.\n\nSUSTENTA-ME, PEGA A MINHA MÃO,\nLEVANTA-ME, DÁ-ME A SALVAÇÃO;\nCRESCER COM ELE É O MAIOR TESOURO,\nTRABALHAR PRA ELE É A MINHA ADORAÇÃO. <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (37, 'NO MEU CORAÇÃO HÁ UM TESOURO (PRÍNCIPE DA VIDA)', 'NO MEU CORAÇÃO HÁ UM TESOURO (PRÍNCIPE DA VIDA)', 'NO MEU CORAÇÃO HÁ UM TESOURO\nO MAIOR QUE POSSA EXISTIR\nA MELHOR COISA QUE FIZ FOI ENCONTRÁ-LO\nPOIS VIDA ETERNA ADQUIRI.\n\nPRÍNCIPE DA VIDA, PAI DA ETERNIDADE\nÉ O MEU TESOURO.\nPRÍNCIPE DA VIDA, PAI DA ETERNIDADE\nÉ O MEU TESOURO, É O MEU JESUS.', 'NO MEU CORAÇÃO HÁ UM TESOURO\nO MAIOR QUE POSSA EXISTIR\nA MELHOR COISA QUE FIZ FOI ENCONTRÁ-LO\nPOIS VIDA ETERNA ADQUIRI.\n\nPRÍNCIPE DA VIDA, PAI DA ETERNIDADE\nÉ O MEU TESOURO.\nPRÍNCIPE DA VIDA, PAI DA ETERNIDADE\nÉ O MEU TESOURO, É O MEU JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (38, 'TENHO UM CORAÇÃO ALEGRE', 'TENHO UM CORAÇÃO ALEGRE', 'TENHO UM CORAÇÃO ALEGRE\nPORQUE ESTOU NA CASA DO PAI;\nO MEU PAI CUIDA DE MIM,\nNELE TENHO PAZ.\n\nNÃO DEIXAREI SUA CASA\nPORQUE AQUI HÁ FARTURA DE PÃO;\nNÃO DEIXAREI JESUS\nPOIS NELE HÁ SALVAÇÃO.\n\nTENHO UM CORAÇÃO ALEGRE\nPORQUE ESTOU NA CASA DO PAI;\nO MEU PAI CUIDA DE MIM,\nNELE TENHO PAZ,\nNELE HÁ SALVAÇÃO.', 'TENHO UM CORAÇÃO ALEGRE\nPORQUE ESTOU NA CASA DO PAI;\nO MEU PAI CUIDA DE MIM,\nNELE TENHO PAZ.\n\nNÃO DEIXAREI SUA CASA\nPORQUE AQUI HÁ FARTURA DE PÃO;\nNÃO DEIXAREI JESUS\nPOIS NELE HÁ SALVAÇÃO.\n\nTENHO UM CORAÇÃO ALEGRE\nPORQUE ESTOU NA CASA DO PAI;\nO MEU PAI CUIDA DE MIM,\nNELE TENHO PAZ,\nNELE HÁ SALVAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (39, 'NA AREIA NÃO QUERO CONSTRUIR (FIRME, SIM!)', 'NA AREIA NÃO QUERO CONSTRUIR (FIRME, SIM!)', 'NA AREIA NÃO QUERO CONSTRUIR,\nSEI MUITO BEM, A CASA VAI CAIR;\nMINHA BÍBLIA JÁ ME DIZ:\nÉ NA ROCHA QUE DEVO CONSTRUIR.\n\nCORO\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ,\nNÃO NA AREIA, SIM NA ROCHA,\nE JESUS VAI SUSTENTAR;\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ.\n\nEM JESUS, ROCHA ETERNA,\nMINHA CASA FIRME ESTÁ;\nNEM A CHUVA, VENTO OU MAR,\nMINHA CASA VAI DERRUBAR.\n\nCORO\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ,\nNÃO NA AREIA, SIM NA ROCHA,\nE JESUS VAI SUSTENTAR;\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ.', 'NA AREIA NÃO QUERO CONSTRUIR,\nSEI MUITO BEM, A CASA VAI CAIR;\nMINHA BÍBLIA JÁ ME DIZ:\nÉ NA ROCHA QUE DEVO CONSTRUIR.\n\n<coro>\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ,\nNÃO NA AREIA, SIM NA ROCHA,\nE JESUS VAI SUSTENTAR;\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ.\n\nEM JESUS, ROCHA ETERNA,\nMINHA CASA FIRME ESTÁ;\nNEM A CHUVA, VENTO OU MAR,\nMINHA CASA VAI DERRUBAR.\n\n<coro>\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ,\nNÃO NA AREIA, SIM NA ROCHA,\nE JESUS VAI SUSTENTAR;\nFIRME, SIM! FIRME, SIM!\nMINHA CASA FIRME ESTÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (40, 'QUERO OUVIR (MEU QUERER)', 'QUERO OUVIR (MEU QUERER)', 'QUERO OUVIR A TUA VOZ, Ó MEU SENHOR,\nA FALAR TÃO PURA E MEIGA AO CORAÇÃO\nE SENTIR O TOQUE DO TEU SANTO ESPÍRITO\nPARA QUE EU POSSA RENOVAR \nA COMUNHÃO.\n\nCORO (2X)\nQUERO LOUVAR, \nCOM ALEGRIA EM MEU VIVER\nRENOVAR A MINHA FÉ, \nENTREGAR TODO O MEU SER.\n\nQUERO FALAR DESTE SEU IMENSO AMOR.\nE DIZER A TODO O MUNDO QUE JESUS \nÉ O SALVADOR.\nQUE LÁ NA CRUZ ELE MORREU \nPARA NOS SALVAR\nDERRAMOU SEU SANGUE PURA \nE A VIDA ETERNA DÁ.\n\n\nCORO (2X)\nQUERO LOUVAR, \nCOM ALEGRIA EM MEU VIVER\nRENOVAR A MINHA FÉ, \nENTREGAR TODO O MEU SER.', 'QUERO OUVIR A TUA VOZ, Ó MEU SENHOR,\nA FALAR TÃO PURA E MEIGA AO CORAÇÃO\nE SENTIR O TOQUE DO TEU SANTO ESPÍRITO\nPARA QUE EU POSSA RENOVAR \nA COMUNHÃO.\n\n<coro tipo=''2X''>\nQUERO LOUVAR, \nCOM ALEGRIA EM MEU VIVER\nRENOVAR A MINHA FÉ, \nENTREGAR TODO O MEU SER.\n\nQUERO FALAR DESTE SEU IMENSO AMOR.\nE DIZER A TODO O MUNDO QUE JESUS \nÉ O SALVADOR.\nQUE LÁ NA CRUZ ELE MORREU \nPARA NOS SALVAR\nDERRAMOU SEU SANGUE PURA \nE A VIDA ETERNA DÁ.\n\n\n<coro tipo=''2X''>\nQUERO LOUVAR, \nCOM ALEGRIA EM MEU VIVER\nRENOVAR A MINHA FÉ, \nENTREGAR TODO O MEU SER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (41, 'A MINHA CASA FIRME ESTÁ', 'A MINHA CASA FIRME ESTÁ', 'A MINHA CASA FIRME ESTÁ,\nFIRMADA NA ROCHA ELA ESTÁ.\nPODEM A CHUVA E O VENTO SOPRAR,\nQUE ELA NÃO SE ABALARÁ,\nPOIS ESTA CASA É O MEU CORAÇÃO.\nNELA JESUS FAZ HABITAÇÃO.\nQUERO FALAR NESSA MINHA CANÇÃO\nQUE JESUS CRISTO É A SALVAÇÃO.\n\nA MINHA CASA FIRME ESTÁ,\nFIRMADA NA ROCHA ELA ESTÁ.\nPODEM A CHUVA E O VENTO SOPRAR,\nQUE ELA NÃO SE ABALARÁ,\nPOIS ESTA CASA É O MEU CORAÇÃO.\nNELA JESUS FAZ HABITAÇÃO.\nQUERO FALAR NESSA MINHA CANÇÃO\nQUE JESUS CRISTO É A SALVAÇÃO.', 'A MINHA CASA FIRME ESTÁ,\nFIRMADA NA ROCHA ELA ESTÁ.\nPODEM A CHUVA E O VENTO SOPRAR,\nQUE ELA NÃO SE ABALARÁ,\nPOIS ESTA CASA É O MEU CORAÇÃO.\nNELA JESUS FAZ HABITAÇÃO.\nQUERO FALAR NESSA MINHA CANÇÃO\nQUE JESUS CRISTO É A SALVAÇÃO.\n\nA MINHA CASA FIRME ESTÁ,\nFIRMADA NA ROCHA ELA ESTÁ.\nPODEM A CHUVA E O VENTO SOPRAR,\nQUE ELA NÃO SE ABALARÁ,\nPOIS ESTA CASA É O MEU CORAÇÃO.\nNELA JESUS FAZ HABITAÇÃO.\nQUERO FALAR NESSA MINHA CANÇÃO\nQUE JESUS CRISTO É A SALVAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (42, 'MINHA VIDA E MEU CORAÇÃO', 'MINHA VIDA E MEU CORAÇÃO', 'MINHA VIDA E MEU CORAÇÃO\nPERTENCEM A JESUS, \nDIA A DIA, EM MEU VIVER, \nVOU ANDAR EM SUA LUZ.\nÀ PALAVRA VOU OBEDECER,\nCOM AMOR TESTEMUNHAR,\nE PRA SEMPRE, SEMPRE O LOUVAREI, \nNA ETERNIDADE EU VOU MORAR.', 'MINHA VIDA E MEU CORAÇÃO\nPERTENCEM A JESUS, \nDIA A DIA, EM MEU VIVER, \nVOU ANDAR EM SUA LUZ.\nÀ PALAVRA VOU OBEDECER,\nCOM AMOR TESTEMUNHAR,\nE PRA SEMPRE, SEMPRE O LOUVAREI, \nNA ETERNIDADE EU VOU MORAR.<bis>\n<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (43, 'SOU FELIZ', 'SOU FELIZ', 'SOU FELIZ \nTENHO JESUS EM MEU CORAÇÃO \n\nSOU FELIZ, ANDO EM SUA LUZ, \nNÃO ESTAREI NA ESCURIDÃO.', 'SOU FELIZ <bis>\nTENHO JESUS EM MEU CORAÇÃO <bis>\n<bis>\nSOU FELIZ, ANDO EM SUA LUZ, <bis>\nNÃO ESTAREI NA ESCURIDÃO.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (44, 'SOU SERVO DO SENHOR', 'SOU SERVO DO SENHOR', 'SOU SERVO DO SENHOR, SERVI-LO É MEU PRAZER \nPOIS SALVO EM SUA GRAÇA POR SEU FILHO JESUS, \nTORNOU-ME LIVRE. \n\nEM JESUS POSSO IR DIRETO AO PAI, \nCOM OUSADIA ENTRAR NO SANTO DOS SANTOS COMO REI E SACERDOTE O SENHOR ME COLOCOU \n\nPOSSO GOVERNAR, POSSO MINISTRAR, \nAO SENHOR SEMPRE ADORAR, EM ESPÍRITO \nE VERDADE HOJE E ETERNAMENTE.\n\nSOU SERVO DO SENHOR, SERVI-LO É MEU PRAZER \nPOIS SALVO EM SUA GRAÇA POR SEU FILHO JESUS, \nTORNOU-ME LIVRE. \n\nEM JESUS POSSO IR DIRETO AO PAI, \nCOM OUSADIA ENTRAR NO SANTO DOS SANTOS COMO REI E SACERDOTE O SENHOR ME COLOCOU \n\nPOSSO GOVERNAR, POSSO MINISTRAR, AO SENHOR SEMPRE ADORAR, EM ESPÍRITO E VERDADE \nHOJE E ETERNAMENTE. (2X)', 'SOU SERVO DO SENHOR, SERVI-LO É MEU PRAZER \nPOIS SALVO EM SUA GRAÇA POR SEU FILHO JESUS, \nTORNOU-ME LIVRE. \n\nEM JESUS POSSO IR DIRETO AO PAI, \nCOM OUSADIA ENTRAR NO SANTO DOS SANTOS COMO REI E SACERDOTE O SENHOR ME COLOCOU \n\nPOSSO GOVERNAR, POSSO MINISTRAR, \nAO SENHOR SEMPRE ADORAR, EM ESPÍRITO \nE VERDADE HOJE E ETERNAMENTE.\n\nSOU SERVO DO SENHOR, SERVI-LO É MEU PRAZER \nPOIS SALVO EM SUA GRAÇA POR SEU FILHO JESUS, \nTORNOU-ME LIVRE. \n\nEM JESUS POSSO IR DIRETO AO PAI, \nCOM OUSADIA ENTRAR NO SANTO DOS SANTOS COMO REI E SACERDOTE O SENHOR ME COLOCOU \n\nPOSSO GOVERNAR, POSSO MINISTRAR, AO SENHOR SEMPRE ADORAR, EM ESPÍRITO E VERDADE \nHOJE E ETERNAMENTE. <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (45, 'JESUS RESSUSCITOU! (MEU AMIGO JESUS)', 'JESUS RESSUSCITOU! (MEU AMIGO JESUS)', 'CORO (2X)\nJESUS RESSUSCITOU! \nCANTAREI EM MEU CORAÇÃO\nTODA GLÓRIA, HONRA E LOUVOR,\nA JESUS, POR SUA PAZ E PERDÃO.\n\nNO MEU CORAÇÃO NÃO HÁ TRISTEZAS, \nPOIS JESUS, COM SEU SANGUE, O LAVOU.\nHOJE EU CANTO COM MUITA ALEGRIA,\nADORANDO AO MEU REI E SENHOR. \n\nHOJE POSSO TESTEMUNHAR\nDE UM AMIGO QUE SÓ ME QUER BEM.\nDEU, NA CRUZ, SUA VIDA POR MIM, \nPRA QUE EU VÁ NO CÉU MORAR TAMBÉM.\n\nCORO\nJESUS RESSUSCITOU! \nCANTAREI EM MEU CORAÇÃO\nTODA GLÓRIA, HONRA E LOUVOR,\nA JESUS, POR SUA PAZ E PERDÃO.\n\nFINAL\nTODA GLÓRIA, HONRA E LOUVOR\nA JESUS, POR SUA PAZ E PERDÃO.', '<coro tipo=''2X''>\nJESUS RESSUSCITOU! \nCANTAREI EM MEU CORAÇÃO\nTODA GLÓRIA, HONRA E LOUVOR,\nA JESUS, POR SUA PAZ E PERDÃO.\n\nNO MEU CORAÇÃO NÃO HÁ TRISTEZAS, \nPOIS JESUS, COM SEU SANGUE, O LAVOU.\nHOJE EU CANTO COM MUITA ALEGRIA,\nADORANDO AO MEU REI E SENHOR. \n\nHOJE POSSO TESTEMUNHAR\nDE UM AMIGO QUE SÓ ME QUER BEM.\nDEU, NA CRUZ, SUA VIDA POR MIM, \nPRA QUE EU VÁ NO CÉU MORAR TAMBÉM.\n\n<coro>\nJESUS RESSUSCITOU! \nCANTAREI EM MEU CORAÇÃO\nTODA GLÓRIA, HONRA E LOUVOR,\nA JESUS, POR SUA PAZ E PERDÃO.\n<final>TODA GLÓRIA, HONRA E LOUVOR\nA JESUS, POR SUA PAZ E PERDÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (46, 'COMO É BOM SERVIR A DEUS', 'COMO É BOM SERVIR A DEUS', 'COMO É BOM SERVIR A DEUS\nCONHECÊ-LO CADA VEZ MAIS\nE VIVENDO NO SEU AMOR\nSENTIR PROTEÇÃO.\n\nCORO (2X)\nQUE ME TRAZ SEGURANÇA, VIDA,\nAMOR, PAZ E ALEGRIA.\n\nCOM MEU DEUS EU SEI QUE SOU\nMAIS QUE VENCEDOR.\nVOU PASSANDO AS PROVAÇÕES\nFIRMADO NO SEU AMOR.', 'COMO É BOM SERVIR A DEUS\nCONHECÊ-LO CADA VEZ MAIS\nE VIVENDO NO SEU AMOR\nSENTIR PROTEÇÃO.\n\n<coro tipo=''2X''>\nQUE ME TRAZ SEGURANÇA, VIDA,\nAMOR, PAZ E ALEGRIA.\n\nCOM MEU DEUS EU SEI QUE SOU\nMAIS QUE VENCEDOR.\nVOU PASSANDO AS PROVAÇÕES\nFIRMADO NO SEU AMOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (47, 'TENHO NO MEU CORAÇÃO', 'TENHO NO MEU CORAÇÃO', 'CORO\nTENHO NO MEU CORAÇÃO O DESEJO \nDE SERVIR AO SENHOR.\nTENHO NO MEU CORAÇÃO O DESEJO \nDE LOUVAR AO SENHOR.\n\nSOU UM SERVO ALEGRE\nPORQUE POSSO SENTIR O AMOR DO SENHOR,\nPORQUE DESDE PEQUENINO POSSO \nOUVIR A VOZ DO SENHOR.\n\nQUANDO TRISTE EU ESTOU\nO SENHOR ME ESTENDE A MÃO.\nQUANDO OLHO PARA OS CÉUS,\nO SENHOR OUVE A MINHA ORAÇÃO.\n\nCORO\nTENHO NO MEU CORAÇÃO O DESEJO \nDE SERVIR AO SENHOR.\nTENHO NO MEU CORAÇÃO O DESEJO \nDE LOUVAR AO SENHOR.\n\nPARA TE LOUVAR. \nPARA TE LOUVAR.\n\nENTRÃO EU ABRO O MEU CORAÇÃO\nPARA TI, SENHOR, MEU JESUS.\nVEM EM MIM HABITAR,\nPOIS UM SERVO EU SOU.\nPOIS UM SERVO EU SOU.\nQUERO CRESCER NA TUA PRESENÇA Ó PAI,\nPARA TE LOUVAR.\nPARA TE LOUVAR.', '<coro>\nTENHO NO MEU CORAÇÃO O DESEJO \nDE SERVIR AO SENHOR.\nTENHO NO MEU CORAÇÃO O DESEJO \nDE LOUVAR AO SENHOR.\n\nSOU UM SERVO ALEGRE\nPORQUE POSSO SENTIR O AMOR DO SENHOR,\nPORQUE DESDE PEQUENINO POSSO \nOUVIR A VOZ DO SENHOR.\n\nQUANDO TRISTE EU ESTOU\nO SENHOR ME ESTENDE A MÃO.\nQUANDO OLHO PARA OS CÉUS,\nO SENHOR OUVE A MINHA ORAÇÃO.\n\n<coro>\nTENHO NO MEU CORAÇÃO O DESEJO \nDE SERVIR AO SENHOR.\nTENHO NO MEU CORAÇÃO O DESEJO \nDE LOUVAR AO SENHOR.\n\nPARA TE LOUVAR. \nPARA TE LOUVAR.\n\nENTRÃO EU ABRO O MEU CORAÇÃO\nPARA TI, SENHOR, MEU JESUS.\nVEM EM MIM HABITAR,\nPOIS UM SERVO EU SOU.\nPOIS UM SERVO EU SOU.\nQUERO CRESCER NA TUA PRESENÇA Ó PAI,\nPARA TE LOUVAR.\nPARA TE LOUVAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (48, 'JESUS CRISTO É O AMADO', 'JESUS CRISTO É O AMADO', 'JESUS CRISTO É O AMADO\nQUE MORREU PELO PECADOR\nO SEU SANGUE CLAMA AO PAI\nPARA REDENÇÃO,\nPARA OBTERMOS PERDÃO,\nSEGUNDO AS RIQUEZAS DE SUA GRAÇA.\n\nCORO \nPOR ESSE MOTIVO ESCOLHEMOS\nFICAR CONTIGO, JESUS,\nE HONRAR O TEU SACRIFÍCIO\nFEITO NO ALTAR DA CRUZ.\nESCOLHEMOS A VIDA E A BÊNÇÃO\nPARA NÓS E A NOSSA HERANÇA\nVIVERMOS SOB A TUA PROTEÇÃO.\n\nJESUS CRISTO É O AMADO\nQUE MORREU PELO PECADOR\nO SEU SANGUE CLAMA AO PAI\nPARA REDENÇÃO,\nPARA OBTERMOS PERDÃO,\nSEGUNDO AS RIQUEZAS DE SUA GRAÇA.\n\nCORO (2X)\nPOR ESSE MOTIVO ESCOLHEMOS\nFICAR CONTIGO, JESUS,\nE HONRAR O TEU SACRIFÍCIO\nFEITO NO ALTAR DA CRUZ.\nESCOLHEMOS A VIDA E A BÊNÇÃO\nPARA NÓS E A NOSSA HERANÇA\nVIVERMOS SOB A TUA PROTEÇÃO.', 'JESUS CRISTO É O AMADO\nQUE MORREU PELO PECADOR\nO SEU SANGUE CLAMA AO PAI\nPARA REDENÇÃO,\nPARA OBTERMOS PERDÃO,\nSEGUNDO AS RIQUEZAS DE SUA GRAÇA.\n\n<coro>\nPOR ESSE MOTIVO ESCOLHEMOS\nFICAR CONTIGO, JESUS,\nE HONRAR O TEU SACRIFÍCIO\nFEITO NO ALTAR DA CRUZ.\nESCOLHEMOS A VIDA E A BÊNÇÃO\nPARA NÓS E A NOSSA HERANÇA\nVIVERMOS SOB A TUA PROTEÇÃO.\n\nJESUS CRISTO É O AMADO\nQUE MORREU PELO PECADOR\nO SEU SANGUE CLAMA AO PAI\nPARA REDENÇÃO,\nPARA OBTERMOS PERDÃO,\nSEGUNDO AS RIQUEZAS DE SUA GRAÇA.\n\n<coro tipo=''2X''>\nPOR ESSE MOTIVO ESCOLHEMOS\nFICAR CONTIGO, JESUS,\nE HONRAR O TEU SACRIFÍCIO\nFEITO NO ALTAR DA CRUZ.\nESCOLHEMOS A VIDA E A BÊNÇÃO\nPARA NÓS E A NOSSA HERANÇA\nVIVERMOS SOB A TUA PROTEÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (49, 'A MINHA ALEGRIA É CRESCER COM O MEU SENHOR!', 'A MINHA ALEGRIA É CRESCER COM O MEU SENHOR!', 'A MINHA ALEGRIA É CRESCER COM O MEU SENHOR!\nSENHOR DA MINHA VIDA, O MEU GRANDE AMOR!\nA TI EU RENDEREI TODA GLÓRIA E LOUVOR.\nAQUI TRABALHAREI NA TUA OBRA COM AMOR.\n\nUSA-ME SENHOR, PRA PREGAR AO PECADOR,\nUSA-ME SENHOR, NA TUA OBRA DE AMOR,\nUSA-ME SENHOR, QUERO TE GLORIFICAR!\nUSA-ME SENHOR, EM TODO E QUALQUER LUGAR,\nUSA-ME SENHOR, ATÉ MEU JESUS VOLTAR!', 'A MINHA ALEGRIA É CRESCER COM O MEU SENHOR!\nSENHOR DA MINHA VIDA, O MEU GRANDE AMOR!\nA TI EU RENDEREI TODA GLÓRIA E LOUVOR.\nAQUI TRABALHAREI NA TUA OBRA COM AMOR.\n\nUSA-ME SENHOR, PRA PREGAR AO PECADOR,\nUSA-ME SENHOR, NA TUA OBRA DE AMOR,\nUSA-ME SENHOR, QUERO TE GLORIFICAR!\nUSA-ME SENHOR, EM TODO E QUALQUER LUGAR,\nUSA-ME SENHOR, ATÉ MEU JESUS VOLTAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (50, 'DO ALTO CÉU', 'DO ALTO CÉU', 'DO ALTO CÉU ELE ME AMOU,\nDO MUNDO MAU ME RETIROU;\nFIZ A ESCOLHA DA SALVAÇÃO.\nEU ACEITEI O CORDEIRO DE DEUS.\n\nSEU SANGUE LAVOU O MEU CORAÇÃO,\nDE TODO PECADO ME PERDOOU;\nE HOJE SOU SALVO PELA GRAÇA DE DEUS.\n\nFINAL\nE HOJE SOU SALVO PELA GRAÇA DE DEUS.', 'DO ALTO CÉU ELE ME AMOU,\nDO MUNDO MAU ME RETIROU;\nFIZ A ESCOLHA DA SALVAÇÃO.\nEU ACEITEI O CORDEIRO DE DEUS.\n\nSEU SANGUE LAVOU O MEU CORAÇÃO,\nDE TODO PECADO ME PERDOOU;\nE HOJE SOU SALVO PELA GRAÇA DE DEUS.\n<final>E HOJE SOU SALVO PELA GRAÇA DE DEUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (51, 'EIS-ME AQUI, SENHOR, EM TEU ALTAR', 'EIS-ME AQUI, SENHOR, EM TEU ALTAR', 'EIS-ME AQUI, SENHOR, \nEM TEU ALTAR, \nEIS-ME AQUI, SENHOR, \nPRONTO A TE ADORAR.\n\nSEI QUE A PRESENÇA \nDO SENHOR JESUS\nNÃO FALHARÁ,\nSEI QUE TU ESTÁS AQUI,\nPRONTO A ABENÇOAR.\n\nINSTRUMENTOS\n\nSANTO E GLORIOSO ÉS, CONOSCO ESTÁS,\nSANTO E GLORIOSO, VIMOS TE ADORAR,\nSANTO E GLORIOSO ÉS, Ó NOSSO AMADO,\nDO TEU ESPÍRITO TENS DERRAMADO,\nDANDO RENOVO E TRANSFORMANDO;\nSANTO E GLORIOSO ÉS,\nVEM EM NÓS TRANSBORDAR,\nÓ SANTO ESPÍRITO, TOMA O TEU LUGAR.\n\nSEI QUE A PRESENÇA \nDO SENHOR JESUS\nNÃO FALHARÁ,\nSEI QUE TU ESTÁS AQUI,\nPRONTO A ABENÇOAR.', 'EIS-ME AQUI, SENHOR, <bis>\nEM TEU ALTAR, <bis>\nEIS-ME AQUI, SENHOR, <bis>\nPRONTO A TE ADORAR.<bis>\n\nSEI QUE A PRESENÇA <bis>\nDO SENHOR JESUS<bis>\nNÃO FALHARÁ,<bis>\nSEI QUE TU ESTÁS AQUI,<bis>\nPRONTO A ABENÇOAR.<bis>\n<instrumentos>\n\n\nSANTO E GLORIOSO ÉS, CONOSCO ESTÁS,\nSANTO E GLORIOSO, VIMOS TE ADORAR,\nSANTO E GLORIOSO ÉS, Ó NOSSO AMADO,\nDO TEU ESPÍRITO TENS DERRAMADO,\nDANDO RENOVO E TRANSFORMANDO;\nSANTO E GLORIOSO ÉS,\nVEM EM NÓS TRANSBORDAR,\nÓ SANTO ESPÍRITO, TOMA O TEU LUGAR.\n\nSEI QUE A PRESENÇA <bis>\nDO SENHOR JESUS<bis>\nNÃO FALHARÁ,<bis>\nSEI QUE TU ESTÁS AQUI,<bis>\nPRONTO A ABENÇOAR.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '52- SEU NOME É MARAVILHOSO', '52- SEU NOME É MARAVILHOSO', 'SEU NOME É MARAVILHOSO, (3x)\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ.\n\nSEU NOME É CONSELHEIRO, (3X)\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ\n\nSEU NOME É DEUS FORTE, (3X)\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ. \n\nIREI SEGUI-LO PARA SEMPRE\nPOIS ELE DÁ FELICIDADE\nSEU NOME É MARAVILHOSO,\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ.', 'SEU NOME É MARAVILHOSO, <bis tipo=''3x''>\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ.\n\nSEU NOME É CONSELHEIRO, <bis tipo=''3x''>\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ\n\nSEU NOME É DEUS FORTE, <bis tipo=''3x''>\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ. \n\nIREI SEGUI-LO PARA SEMPRE\nPOIS ELE DÁ FELICIDADE\nSEU NOME É MARAVILHOSO,\nPAI DA ETERNIDADE, PRÍNCIPE DA PAZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (53, 'É BOM, É BOM DEMAIS', 'É BOM, É BOM DEMAIS', 'É BOM, É BOM DEMAIS\nÉ MUITO BOM TER JESUS NO CORAÇÃO.\n\nVIVER COM ELE, PERTINHO DELE,\nÉ MUITO BOM TER JESUS NO CORAÇÃO.', 'É BOM, É BOM DEMAIS<bis>\nÉ MUITO BOM TER JESUS NO CORAÇÃO.<bis>\n\nVIVER COM ELE, PERTINHO DELE,<bis>\nÉ MUITO BOM TER JESUS NO CORAÇÃO.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (54, 'COMO É BOM SABER', 'COMO É BOM SABER', 'COMO É BOM SABER QUE JESUS CRISTO\nFOI MENINO ASSIM COMO EU,\nQUE BRINCAVA E TRABALHAVA\nCOMO UM JOVEM GALILEU.\n\nCORO\nQUE PRAZER CONHECER CRISTO\nQUE TAMBÉM FOI MENINO AQUI\nE SABER QUE NO CÉU LINDO,\nQUER TER-ME JUNTO A SI!\n\nE É MELHOR SABER QUE JESUS CRISTO\nJÁ SUBIU LÁ PARA O CÉU\nE PREPARA UM LUGARZINHO\nDE UM MENINO, ASSIM, COMO EU.\n\nCORO\nQUE PRAZER CONHECER CRISTO\nQUE TAMBÉM FOI MENINO AQUI\nE SABER QUE NO CÉU LINDO,\nQUER TER-ME JUNTO A SI!', 'COMO É BOM SABER QUE JESUS CRISTO\nFOI MENINO ASSIM COMO EU,\nQUE BRINCAVA E TRABALHAVA\nCOMO UM JOVEM GALILEU.\n\n<coro>\nQUE PRAZER CONHECER CRISTO\nQUE TAMBÉM FOI MENINO AQUI\nE SABER QUE NO CÉU LINDO,\nQUER TER-ME JUNTO A SI!\n\nE É MELHOR SABER QUE JESUS CRISTO\nJÁ SUBIU LÁ PARA O CÉU\nE PREPARA UM LUGARZINHO\nDE UM MENINO, ASSIM, COMO EU.\n\n<coro>\nQUE PRAZER CONHECER CRISTO\nQUE TAMBÉM FOI MENINO AQUI\nE SABER QUE NO CÉU LINDO,\nQUER TER-ME JUNTO A SI!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (55, 'É SOMENTE TEU MEU CORAÇÃO SENHOR', 'É SOMENTE TEU MEU CORAÇÃO SENHOR', 'É SOMENTE TEU MEU CORAÇÃO, SENHOR,\nÉ SOMENTE TEU MEU CORPO E MEU LOUVOR;\nÉ SOMENTE TEU, MEU PAI, O MEU AMOR,\nSOU SOMENTE TEU, MEU REDENTOR.\n\nQUERO TE AMAR, MEU DEUS, Ó MEU SENHOR,\nQUERO TE ADORAR, PRA SEMPRE, COM ARDOR,\nQUERO A TI ORAR COM FÉ E COM FERVOR,\nSOU SOMENTE TEU, MEU REDENTOR.', 'É SOMENTE TEU MEU CORAÇÃO, SENHOR,\nÉ SOMENTE TEU MEU CORPO E MEU LOUVOR;\nÉ SOMENTE TEU, MEU PAI, O MEU AMOR,\nSOU SOMENTE TEU, MEU REDENTOR.\n\nQUERO TE AMAR, MEU DEUS, Ó MEU SENHOR,\nQUERO TE ADORAR, PRA SEMPRE, COM ARDOR,\nQUERO A TI ORAR COM FÉ E COM FERVOR,\nSOU SOMENTE TEU, MEU REDENTOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (56, 'CRISTO É O SENHOR', 'CRISTO É O SENHOR', 'CRISTO É O SENHOR,DONO DO MEU VIVER,\nELE ME SALVOU, COM SEU SANGUE ME LAVOU;\n\nINSTRUMENTOS\n\nREPETIR O HINO\n\nFINAL: PRA SEMPRE COM ELE VOU ESTAR.', 'CRISTO É O SENHOR,DONO DO MEU VIVER,\nELE ME SALVOU, COM SEU SANGUE ME LAVOU;\n<instrumentos>\n<repetir tipo=''O HINOx''>\n<final>PRA SEMPRE COM ELE VOU ESTAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (57, 'HÁ UMA LINDA CANÇÃO DE AMOR', 'HÁ UMA LINDA CANÇÃO DE AMOR', 'HÁ UMA LINDA CANÇÃO DE AMOR\nDENTRO DO MEU CORAÇÃO,\nCRISTO ME DEU PLENA PAZ E PERDÃO,\nOH! EU SOU FELIZ!\nOH! EU SOU FELIZ, FELIZ (2x)\nCRISTO ME DEU PLENA PAZ E PERDÃO,\nOH! EU SOU FELIZ!', 'HÁ UMA LINDA CANÇÃO DE AMOR\nDENTRO DO MEU CORAÇÃO,\nCRISTO ME DEU PLENA PAZ E PERDÃO,\nOH! EU SOU FELIZ!\nOH! EU SOU FELIZ, FELIZ <bis tipo=''2x''>\nCRISTO ME DEU PLENA PAZ E PERDÃO,\nOH! EU SOU FELIZ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (58, 'VIVER É TÃO LINDO', 'VIVER É TÃO LINDO', 'VIVER É TÃO LINDO QUANDO SE TEM JESUS,\nO MUNDO É TÃO PEQUENO\nPARA O QUE EU TENHO EM MIM;\nE O QUE TENHO\nÉ BEM MAIOR QUE TUDO NA VIDA\nEU TENHO É JESUS\n\nVIVO A CANTAR, VIVO A SORRIR\nTUDO O QUE EU TENHO\nJAMAIS SE ACABARÁ.', 'VIVER É TÃO LINDO QUANDO SE TEM JESUS,\nO MUNDO É TÃO PEQUENO\nPARA O QUE EU TENHO EM MIM;\nE O QUE TENHO\nÉ BEM MAIOR QUE TUDO NA VIDA\nEU TENHO É JESUS\n\nVIVO A CANTAR, VIVO A SORRIR\nTUDO O QUE EU TENHO\nJAMAIS SE ACABARÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (59, 'O NOME DO MEU SENHOR', 'O NOME DO MEU SENHOR', 'O NOME DO MEU SENHOR,\nO QUE VENCEU A MORTE E A CRUZ,\nO ÚNICO QUE É DIGNO DE LOUVOR,\nO SEU NOME É JESUS!\n\nCORO\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\n\nO MEU SENHOR DERRAMOU\nO SEU PRECIOSO SANGUE NA CRUZ,\nPERDOOU MEUS PECADOS,\nLAVOU-ME, O SEU NOME É JESUS!\n\nCORO\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\n\nAGORA VOU, FELIZ, TE ADORAR, \nPOIS O TEU SANGUE ME LIMPOU.\nCAMINHANDO VOU PARA A PÁTRIA,\nÓ JESUS, VEM ME BUSCAR!\n\nCORO\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\nMINHA ESPERANÇA É JESUS,', 'O NOME DO MEU SENHOR,\nO QUE VENCEU A MORTE E A CRUZ,\nO ÚNICO QUE É DIGNO DE LOUVOR,\nO SEU NOME É JESUS!\n\n<coro>\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\n\nO MEU SENHOR DERRAMOU\nO SEU PRECIOSO SANGUE NA CRUZ,\nPERDOOU MEUS PECADOS,\nLAVOU-ME, O SEU NOME É JESUS!\n\n<coro>\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\n\nAGORA VOU, FELIZ, TE ADORAR, \nPOIS O TEU SANGUE ME LIMPOU.\nCAMINHANDO VOU PARA A PÁTRIA,\nÓ JESUS, VEM ME BUSCAR!\n\n<coro>\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\nÉ FIEL, É A PAZ, É AMOR, É O SALVADOR!\nÉ A ESPERANÇA ETERNA.\nMINHA ESPERANÇA É JESUS,', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (60, 'DEUS FALOU COMIGO', 'DEUS FALOU COMIGO', 'DEUS FALOU COMIGO,\nDEUS QUER FALAR COM VOCÊ;\nDEUS FALOU COMIGO\nQUE A PORTA DO CÉU É JESUS,\nA PORTA DO CÉU É JESUS,\nA PORTA DO CÉU É JESUS.', 'DEUS FALOU COMIGO,<bis>\nDEUS QUER FALAR COM VOCÊ;<bis>\nDEUS FALOU COMIGO<bis>\nQUE A PORTA DO CÉU É JESUS,<bis>\nA PORTA DO CÉU É JESUS,<bis>\nA PORTA DO CÉU É JESUS.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (61, 'SEI QUE NA CRUZ SEU SANGUE VERTEU', 'SEI QUE NA CRUZ SEU SANGUE VERTEU', 'SEI QUE NA CRUZ SEU SANGUE VERTEU,\nMORREU ALI MEU SENHOR,\nMAS NO TERCEIRO DIA RESSUCITOU\nPRA ME DAR O CÉU DE AMOR.\n\nEU QUERO JESUS QUE ME SALVA, (3X)\nCOM ELE QUERO IR AO CÉU.\nLÁ NO CÉU, (3X)\nQUERO MORAR COM MEU JESUS.\nLÁ NO CÉU, (3X)\nQUERO MORAR COM MEU JESUS.\n\nSEI QUE NA CRUZ SEU SANGUE VERTEU,\nMORREU ALI MEU SENHOR,\nMAS NO TERCEIRO DIA RESSUCITOU\nPRA ME DAR O CÉU DE AMOR.\n\nEU QUERO JESUS QUE ME SALVA, (3X)\nCOM ELE QUERO IR AO CÉU.\nLÁ NO CÉU, (3X)\nQUERO MORAR COM MEU JESUS.\nLÁ NO CÉU, (3X)\nQUERO MORAR COM MEU JESUS.', 'SEI QUE NA CRUZ SEU SANGUE VERTEU,\nMORREU ALI MEU SENHOR,\nMAS NO TERCEIRO DIA RESSUCITOU\nPRA ME DAR O CÉU DE AMOR.\n\nEU QUERO JESUS QUE ME SALVA, <bis tipo=''3x''>\nCOM ELE QUERO IR AO CÉU.\nLÁ NO CÉU, <bis tipo=''3x''>\nQUERO MORAR COM MEU JESUS.\nLÁ NO CÉU, <bis tipo=''3x''>\nQUERO MORAR COM MEU JESUS.\n\nSEI QUE NA CRUZ SEU SANGUE VERTEU,\nMORREU ALI MEU SENHOR,\nMAS NO TERCEIRO DIA RESSUCITOU\nPRA ME DAR O CÉU DE AMOR.\n\nEU QUERO JESUS QUE ME SALVA, <bis tipo=''3x''>\nCOM ELE QUERO IR AO CÉU.\nLÁ NO CÉU, <bis tipo=''3x''>\nQUERO MORAR COM MEU JESUS.\nLÁ NO CÉU, <bis tipo=''3x''>\nQUERO MORAR COM MEU JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (62, 'É TÃO TRISTE NÃO VER A LUZ (O CEGO BARTIMEU)', 'É TÃO TRISTE NÃO VER A LUZ (O CEGO BARTIMEU)', 'É TÃO TRISTE NÃO VER A LUZ,\nA ESCURIDÃO DESTA VIDA VIVER,\nÀ BEIRA DO CAMINHO \nBARTIMEU VIVIA A SOFRER.\n\nMAS UMA VOZ DE ESPERANÇA\nAOS SEUS OUVIDOS UM DIA CHEGOU,\nA MULTIDÃO O IMPEDIA\nE O CEGO BEM ALTO GRITOU:\n\n- Ó JESUS, FILHO DE DAVI,\nTEM MISERICÓRDIA DE MIM;\nQUERIA VER O SOL NASCER,\nA LUZ DA VIDA RESPLANDECER.\n\nE JESUS TEVE COMPAIXÃO,\nDEU-LHE CURA E REDENÇÃO,\nE FELIZ PELO CAMINHO \nA JESUS SEGUIU.\n\nÉ TÃO TRISTE NÃO VER A LUZ,\nA ESCURIDÃO DESTA VIDA VIVER,\nÀ BEIRA DO CAMINHO \nBARTIMEU VIVIA A SOFRER.\n\nMAS UMA VOZ DE ESPERANÇA\nAOS SEUS OUVIDOS UM DIA CHEGOU,\nA MULTIDÃO O IMPEDIA\nE O CEGO BEM ALTO GRITOU:\n\nÓ JESUS, FILHO DE DAVI,\nTEM MISERICÓRDIA DE MIM;\nQUERIA VER O SOL NASCER,\nA LUZ DA VIDA RESPLANDECER.\n\nE JESUS TEVE COMPAIXÃO,\nDEU-LHE CURA E REDENÇÃO,\nE FELIZ PELO CAMINHO \nA JESUS SEGUIU.', 'É TÃO TRISTE NÃO VER A LUZ,\nA ESCURIDÃO DESTA VIDA VIVER,\nÀ BEIRA DO CAMINHO \nBARTIMEU VIVIA A SOFRER.\n\nMAS UMA VOZ DE ESPERANÇA\nAOS SEUS OUVIDOS UM DIA CHEGOU,\nA MULTIDÃO O IMPEDIA\nE O CEGO BEM ALTO GRITOU:\n\n- Ó JESUS, FILHO DE DAVI,\nTEM MISERICÓRDIA DE MIM;\nQUERIA VER O SOL NASCER,\nA LUZ DA VIDA RESPLANDECER.\n\nE JESUS TEVE COMPAIXÃO,\nDEU-LHE CURA E REDENÇÃO,\nE FELIZ PELO CAMINHO \nA JESUS SEGUIU.\n\nÉ TÃO TRISTE NÃO VER A LUZ,\nA ESCURIDÃO DESTA VIDA VIVER,\nÀ BEIRA DO CAMINHO \nBARTIMEU VIVIA A SOFRER.\n\nMAS UMA VOZ DE ESPERANÇA\nAOS SEUS OUVIDOS UM DIA CHEGOU,\nA MULTIDÃO O IMPEDIA\nE O CEGO BEM ALTO GRITOU:\n\nÓ JESUS, FILHO DE DAVI,\nTEM MISERICÓRDIA DE MIM;\nQUERIA VER O SOL NASCER,\nA LUZ DA VIDA RESPLANDECER.\n\nE JESUS TEVE COMPAIXÃO,\nDEU-LHE CURA E REDENÇÃO,\nE FELIZ PELO CAMINHO \nA JESUS SEGUIU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (63, 'TEM BOM ÂNIMO, POBRE PECADOR', 'TEM BOM ÂNIMO, POBRE PECADOR', 'TEM BOM ÂNIMO, POBRE PECADOR,\nJESUS ESTÁ PRESENTE PARA TE SALVAR;\nSALVOU ZAQUEU, O RICO QUE ERA POBRE,\nBUSCOU UM CEGO À BEIRA DO CAMINHO.\n\n(FALANDO): ''BARTIMEU,\nQUE QUERES QUE EU TE FAÇA?''\n\nQUE EU VEJA, FOI A RESPOSTA PRONTA;\nVENDO AGORA O ROSTO DE JESUS,\nLOGO O SEGUIU LOUVANDO ALEGREMENTE.\n\nPODES TER TUDO OU NADA POSSUIR,\nJESUS PERGUNTA AGORA:\n''QUE QUERES QUE EU TE FAÇA?''\nRESPONDE DEPRESSA: A TUA SALVAÇÃO;\nVIDA ETERNA JESUS TE DÁ AGORA.', 'TEM BOM ÂNIMO, POBRE PECADOR,\nJESUS ESTÁ PRESENTE PARA TE SALVAR;\nSALVOU ZAQUEU, O RICO QUE ERA POBRE,\nBUSCOU UM CEGO À BEIRA DO CAMINHO.\n\n(FALANDO): ''BARTIMEU,\nQUE QUERES QUE EU TE FAÇA?''\n\nQUE EU VEJA, FOI A RESPOSTA PRONTA;\nVENDO AGORA O ROSTO DE JESUS,\nLOGO O SEGUIU LOUVANDO ALEGREMENTE.\n\nPODES TER TUDO OU NADA POSSUIR,\nJESUS PERGUNTA AGORA:\n''QUE QUERES QUE EU TE FAÇA?''\nRESPONDE DEPRESSA: A TUA SALVAÇÃO;\nVIDA ETERNA JESUS TE DÁ AGORA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (64, 'EU VOU CONTAR UMA HISTÓRIA', 'EU VOU CONTAR UMA HISTÓRIA', 'EU VOU CONTAR UMA HISTÓRIA\nPRA VOCÊ NÃO ESQUECER,\nA HISTÓRIA DE UM HOMEM\nQUE A JESUS QUERIA VER.\n\nSUBIU EM UMA ÁRVORE PRA VER \nJESUS PASSAR POIS ERA TÃO PEQUENO, \nNÃO PODIA O AVISTAR.\n\nOLHANDO PARA CIMA JESUS O ENCONTROU,\nCOM SUA VOZ SUAVE, ENTÃO ELE FALOU:\n\n''- ZAQUEU, DESCE DEPRESSA\nPORQUE HOJE ME CONVÉM\nPOUSAR EM TUA CASA,\nVEM DEPRESSA, Ó SIM, VEM''.\n\nZAQUEU ENTÃO DESCEU\nQUANDO JESUS O CONVIDOU,\nJESUS MUDOU SUA VIDA,\nEM OUTRO HOMEM SE TORNOU.', 'EU VOU CONTAR UMA HISTÓRIA\nPRA VOCÊ NÃO ESQUECER,\nA HISTÓRIA DE UM HOMEM\nQUE A JESUS QUERIA VER.\n\nSUBIU EM UMA ÁRVORE PRA VER \nJESUS PASSAR POIS ERA TÃO PEQUENO, \nNÃO PODIA O AVISTAR.\n\nOLHANDO PARA CIMA JESUS O ENCONTROU,\nCOM SUA VOZ SUAVE, ENTÃO ELE FALOU:\n\n''- ZAQUEU, DESCE DEPRESSA\nPORQUE HOJE ME CONVÉM\nPOUSAR EM TUA CASA,\nVEM DEPRESSA, Ó SIM, VEM''.\n\nZAQUEU ENTÃO DESCEU\nQUANDO JESUS O CONVIDOU,\nJESUS MUDOU SUA VIDA,\nEM OUTRO HOMEM SE TORNOU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (65, 'ONDE NASCEU JESUS?', 'ONDE NASCEU JESUS?', 'ONDE NASCEU JESUS?\nEU LOGO TE RESPONDO:\nEM BELÉM O MEU JESUS NASCEU.\n\nQUEM É SEU PAI?\nEU LOGO TE RESPONDO:\nDE DEUS É FILHO\nE ELE TAMBÉM É DEUS.\n\nEM QUE CIDADE CRESCEU?\nEU LOGO TE RESPONDO:\nEM NAZARÉ\nO MEU JESUS CRESCEU.\n\nQUEM O BATIZOU?\nEU LOGO TE RESPONDO:\nFOI JOÃO BATISTA\nNO RIO JORDÃO.\n\nE DIGO MAIS:\nELE ESTÁ VIVO,\nFALA CONOSCO,\nNOS TRAZENDO A PAZ.', 'ONDE NASCEU JESUS?\nEU LOGO TE RESPONDO:\nEM BELÉM O MEU JESUS NASCEU.\n\nQUEM É SEU PAI?\nEU LOGO TE RESPONDO:\nDE DEUS É FILHO\nE ELE TAMBÉM É DEUS.\n\nEM QUE CIDADE CRESCEU?\nEU LOGO TE RESPONDO:\nEM NAZARÉ\nO MEU JESUS CRESCEU.\n\nQUEM O BATIZOU?\nEU LOGO TE RESPONDO:\nFOI JOÃO BATISTA\nNO RIO JORDÃO.\n\nE DIGO MAIS:\nELE ESTÁ VIVO,\nFALA CONOSCO,\nNOS TRAZENDO A PAZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (66, 'NASCEU UM NOVO DIA', 'NASCEU UM NOVO DIA', 'NASCEU UM NOVO DIA;\nBRILHOU A LUZ DO SEU AMOR;\nA PAZ VEIO ENTÃO REINAR\nQUANDO JESUS EM MIM HABITOU.', 'NASCEU UM NOVO DIA;<bis>\nBRILHOU A LUZ DO SEU AMOR;<bis>\nA PAZ VEIO ENTÃO REINAR<bis>\nQUANDO JESUS EM MIM HABITOU.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (67, 'MARAVILHA É O AMOR DE DEUS', 'MARAVILHA É O AMOR DE DEUS', 'MARAVILHA, MARAVILHA, \nMARAVILHA É O AMOR DE DEUS, REVELADO NO CALVÁRIO, \nJESUS POR NÓS MORREU.\n\nMARAVILHA É ANUNCIAR ESSE AMOR \nPRA VOCÊ QUE HOJE ESTÁ AQUI; \nVEM CONHECÊ-LO, VEM RECEBÊ-LO, \nE A ALEGRIA INUNDARÁ TEU SER.\n\nMARAVILHA, MARAVILHA, MARAVILHA\nÉ A SALVAÇÃO. NÃO MORREREMOS! \nSIM, ESTAREMOS ETERNAMENTE \nCOM O NOSSO DEUS!', 'MARAVILHA, MARAVILHA, \nMARAVILHA É O AMOR DE DEUS, REVELADO NO CALVÁRIO, \nJESUS POR NÓS MORREU.\n\nMARAVILHA É ANUNCIAR ESSE AMOR \nPRA VOCÊ QUE HOJE ESTÁ AQUI; \nVEM CONHECÊ-LO, VEM RECEBÊ-LO, \nE A ALEGRIA INUNDARÁ TEU SER.\n\nMARAVILHA, MARAVILHA, MARAVILHA\nÉ A SALVAÇÃO. NÃO MORREREMOS! \nSIM, ESTAREMOS ETERNAMENTE <bis>\nCOM O NOSSO DEUS!<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (68, 'VEM PARA O MEIO', 'VEM PARA O MEIO', 'VEM PARA O MEIO \nDE UM POVO QUE SABE \nO CAMINHO DA ETERNIDADE,\nONDE A PROFECIA APONTA A DIREÇÃO; \nESSE POVO SEGUE E \nALCANÇA A SALVAÇÃO.\n\nVEM PARA O MEIO, \nJESUS ESTÁ AQUI, \nMERGULHA NESSAS ÁGUAS \nDA SALVAÇÃO;\nESSAS ÁGUAS CURAM E NOVA CRIATURA SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.\n\nVEM PARA O MEIO \nDE UM POVO QUE SABE \nO CAMINHO DA ETERNIDADE,\nONDE A PROFECIA APONTA A DIREÇÃO; \nESSE POVO SEGUE E \nALCANÇA A SALVAÇÃO.\n\nVEM PARA O MEIO, \nJESUS ESTÁ AQUI, \nMERGULHA NESSAS ÁGUAS \nDA SALVAÇÃO;\nESSAS ÁGUAS CURAM E NOVA CRIATURA SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.', 'VEM PARA O MEIO \nDE UM POVO QUE SABE \nO CAMINHO DA ETERNIDADE,\nONDE A PROFECIA APONTA A DIREÇÃO; \nESSE POVO SEGUE E \nALCANÇA A SALVAÇÃO.\n\nVEM PARA O MEIO, \nJESUS ESTÁ AQUI, \nMERGULHA NESSAS ÁGUAS \nDA SALVAÇÃO;\nESSAS ÁGUAS CURAM E NOVA CRIATURA SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.\n\nVEM PARA O MEIO \nDE UM POVO QUE SABE \nO CAMINHO DA ETERNIDADE,\nONDE A PROFECIA APONTA A DIREÇÃO; \nESSE POVO SEGUE E \nALCANÇA A SALVAÇÃO.\n\nVEM PARA O MEIO, \nJESUS ESTÁ AQUI, \nMERGULHA NESSAS ÁGUAS \nDA SALVAÇÃO;\nESSAS ÁGUAS CURAM E NOVA CRIATURA SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (69, 'VOCÊ SABE O QUE É SALVAÇÃO?', 'VOCÊ SABE O QUE É SALVAÇÃO?', 'VOCÊ SABE O QUE É SALVAÇÃO?\nÉ SENTIR UMA GRANDE ALEGRIA\nQUE O MUNDO NÃO CONHECE,\nNELE HÁ TREVAS E SOLIDÃO.\n\nJESUS NOS DEU SALVAÇÃO\nQUANDO LÁ NA CRUZ MORREU,\nLEVOU OS NOSSOS PECADOS,\nLIBERTOS AGORA ESTAMOS.\n\nDÊ A ELE O SEU LOUVOR,\nUMA VIDA DE GRATIDÃO;\nVENHA AGORA E ENTREGUE\nA JESUS SEU CORAÇÃO.\n\nVENHA AGORA E ENTREGUE\nA JESUS SEU CORAÇÃO.', 'VOCÊ SABE O QUE É SALVAÇÃO?\nÉ SENTIR UMA GRANDE ALEGRIA\nQUE O MUNDO NÃO CONHECE,\nNELE HÁ TREVAS E SOLIDÃO.\n\nJESUS NOS DEU SALVAÇÃO\nQUANDO LÁ NA CRUZ MORREU,\nLEVOU OS NOSSOS PECADOS,\nLIBERTOS AGORA ESTAMOS.\n\nDÊ A ELE O SEU LOUVOR,\nUMA VIDA DE GRATIDÃO;\nVENHA AGORA E ENTREGUE\nA JESUS SEU CORAÇÃO.\n\nVENHA AGORA E ENTREGUE\nA JESUS SEU CORAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (70, 'O DIA DO SENHOR VIRÁ', 'O DIA DO SENHOR VIRÁ', 'O DIA DO SENHOR VIRÁ \nCOM JUÍZO SOBRE TODO MAL;\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nGRANDE BÊNÇÃO\nESTÁ A TE ESPERAR. \n\n\nO SOL DA JUSTIÇA NASCERÁ, \nSALVAÇÃO TRARÁ EM SUAS ASAS;\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nGRANDE BÊNÇÃO\nESTÁ A TE ESPERAR. \n\n\nO SOL DA JUSTIÇA NASCERÁ, SALVAÇÃO E LIBERTAÇÃO;\n\nSAIREIS E ANUNCIAREIS, \nEM SUAS ASAS \n''INDA HÁ LUGAR. \n\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nEM SUAS ASAS \nTE ABRIGAR\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nEM SUAS ASAS \nTE ABRIGAR', 'O DIA DO SENHOR VIRÁ \nCOM JUÍZO SOBRE TODO MAL;\n\nVEM DEPRESSA, <bis>\nVEM DEPRESSA, <bis>\nGRANDE BÊNÇÃO<bis>\nESTÁ A TE ESPERAR. <bis>\n\n\nO SOL DA JUSTIÇA NASCERÁ, \nSALVAÇÃO TRARÁ EM SUAS ASAS;\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nGRANDE BÊNÇÃO\nESTÁ A TE ESPERAR. \n\n\nO SOL DA JUSTIÇA NASCERÁ, SALVAÇÃO E LIBERTAÇÃO;\n\nSAIREIS E ANUNCIAREIS, \nEM SUAS ASAS <bis>\n''INDA HÁ LUGAR. <bis>\n<bis>\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nEM SUAS ASAS \nTE ABRIGAR\n\nVEM DEPRESSA, \nVEM DEPRESSA, \nEM SUAS ASAS \nTE ABRIGAR', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (71, 'JESUS VIU A MULTIDÃO', 'JESUS VIU A MULTIDÃO', 'JESUS VIU A MULTIDÃO\nE NÃO OS DEIXOU IR,\nESTAVAM TÃO FAMINTOS,\nCOMO PODIAM PARTIR?\n\nENTÃO ELE ORDENOU:\n''DAI-LHES DE COMER'',\nOS DISCÍPULOS PERGUNTARAM: \nSENHOR, O QUE VAMOS FAZER?\n\nINSTRUMENTOS\n\nCINCO PÃES E DOIS PEIXINHOS \nCINCO MIL ALIMENTOU,\nASSENTADOS SOBRE A RELVA,\nTODO O POVO SE FARTOU.\n\nJESUS É A SOLUÇÃO,\nELE É A PROVISÃO,\nO FILHO DO DEUS VIVO\nFAZ A MULTIPLICAÇÃO.', 'JESUS VIU A MULTIDÃO\nE NÃO OS DEIXOU IR,\nESTAVAM TÃO FAMINTOS,\nCOMO PODIAM PARTIR?\n\nENTÃO ELE ORDENOU:\n''DAI-LHES DE COMER'',\nOS DISCÍPULOS PERGUNTARAM: \nSENHOR, O QUE VAMOS FAZER?\n<instrumentos>\n\n\nCINCO PÃES E DOIS PEIXINHOS \nCINCO MIL ALIMENTOU,\nASSENTADOS SOBRE A RELVA,\nTODO O POVO SE FARTOU.\n\nJESUS É A SOLUÇÃO,\nELE É A PROVISÃO,\nO FILHO DO DEUS VIVO\nFAZ A MULTIPLICAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (72, 'TU ÉS O CRISTO, O FILHO DO DEUS VIVO', 'TU ÉS O CRISTO, O FILHO DO DEUS VIVO', 'TU ÉS O CRISTO, \nO FILHO DO DEUS VIVO,\nNOSSO SALVADOR, \nJESUS NOME DOCE;\n\nMORRESTE NA CRUZ PRA NOS SALVAR,\nRESSUSCITASTE E NO CÉU ESTÁS,\nVOLTARÁS E NOS LEVARÁS\nPARA CONTIGO HABITAR.\n\nTU ÉS O CRISTO, \nO FILHO DO DEUS VIVO,\nNOSSO SALVADOR, \nJESUS NOME DOCE;\n\nMORRESTE NA CRUZ PRA NOS SALVAR,\nRESSUSCITASTE E NO CÉU ESTÁS,\nVOLTARÁS E NOS LEVARÁS\nPARA CONTIGO HABITAR.', 'TU ÉS O CRISTO, \nO FILHO DO DEUS VIVO,\nNOSSO SALVADOR, \nJESUS NOME DOCE;\n\nMORRESTE NA CRUZ PRA NOS SALVAR,\nRESSUSCITASTE E NO CÉU ESTÁS,\nVOLTARÁS E NOS LEVARÁS\nPARA CONTIGO HABITAR.\n\nTU ÉS O CRISTO, \nO FILHO DO DEUS VIVO,\nNOSSO SALVADOR, \nJESUS NOME DOCE;\n\nMORRESTE NA CRUZ PRA NOS SALVAR,\nRESSUSCITASTE E NO CÉU ESTÁS,\nVOLTARÁS E NOS LEVARÁS\nPARA CONTIGO HABITAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (73, 'DE ETERNIDADE A ETERNIDADE', 'DE ETERNIDADE A ETERNIDADE', 'DE ETERNIDADE A ETERNIDADE JESUS É O NOSSO DEUS.\nTODAS AS COISAS POR ELE FORAM FEITAS \nE SEM ELE NADA DO QUE \nFOI FEITO SE FEZ.\n\nO HOMEM DEUS CRIOU, IGUAL A ELE O FORMOU, PODENDO ASSIM VIVER ETERNAMENTE \nCOM JESUS.\n\nMAS O HOMEM PECOU E DE DEUS SE AFASTOU.\n\nNOVO PROJETO DEUS CRIOU \nPOR SEU AMOR,\nPRA RESGATAR O HOMEM, \nPOBRE PECADOR:\n\n\n''PORQUE DEUS AMOU \nO MUNDO DE TAL MANEIRA QUE DEU O SEU FILHO UNIGÊNITO, PARA QUE TODO AQUELE \nQUE NELE CRÊ NÃO PEREÇA, \nMAS TENHA A VIDA ETERNA.''\n\n.\n\nCREIO EM JESUS, \nETERNAMENTE VIVEREI; SEGUINDO A JESUS \nPARA O CÉU EU SUBIREI E ADORAREI O REI, \nADORAREI O REI, ADORAREI O REI JESUS.', 'DE ETERNIDADE A ETERNIDADE JESUS É O NOSSO DEUS.\nTODAS AS COISAS POR ELE FORAM FEITAS \nE SEM ELE NADA DO QUE \nFOI FEITO SE FEZ.\n\nO HOMEM DEUS CRIOU, IGUAL A ELE O FORMOU, PODENDO ASSIM VIVER ETERNAMENTE \nCOM JESUS.\n\nMAS O HOMEM PECOU E DE DEUS SE AFASTOU.\n\nNOVO PROJETO DEUS CRIOU \nPOR SEU AMOR,\nPRA RESGATAR O HOMEM, \nPOBRE PECADOR:\n\n\n''PORQUE DEUS AMOU \nO MUNDO DE TAL MANEIRA QUE DEU O SEU FILHO UNIGÊNITO, PARA QUE TODO AQUELE \nQUE NELE CRÊ NÃO PEREÇA, \nMAS TENHA A VIDA ETERNA.''\n\n.\n\nCREIO EM JESUS, \nETERNAMENTE VIVEREI; SEGUINDO A JESUS \nPARA O CÉU EU SUBIREI E ADORAREI O REI, \nADORAREI O REI, ADORAREI O REI JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (74, 'AQUILO QUE MELHOR EXISTE', 'AQUILO QUE MELHOR EXISTE', 'AQUILO QUE MELHOR EXISTE\nÉ FALAR DE JESUS.\nELE É O CAMINHO E A VIDA,\nA VERDADE E A LUZ.\n\nJESUS, AO APROXIMAR-SE, \nJOÃO BATISTA APONTOU:\n''EIS O CORDEIRO DE DEUS, \n QUE VEIO AO MUNDO\n NOS DAR SALVAÇÃO''.\n\nOS DISCÍPULOS, DESANIMADOS\nPOR PESCAREM EM VÃO,\nJESUS OS MANDA \nDE VOLTA AO MAR\nE MUITOS PEIXES PESCAR.\n\nALEGRES DESCOBRIRAM:\n''O CORDEIRO DE DEUS\nESTÁ VIVO ENTRE NÓS!''\nREINA PRA SEMPRE \nO MEU SALVADOR.', 'AQUILO QUE MELHOR EXISTE\nÉ FALAR DE JESUS.\nELE É O CAMINHO E A VIDA,\nA VERDADE E A LUZ.\n\nJESUS, AO APROXIMAR-SE, \nJOÃO BATISTA APONTOU:\n''EIS O CORDEIRO DE DEUS, <bis>\n QUE VEIO AO MUNDO<bis>\n NOS DAR SALVAÇÃO''.<bis>\n\nOS DISCÍPULOS, DESANIMADOS\nPOR PESCAREM EM VÃO,\nJESUS OS MANDA \nDE VOLTA AO MAR\nE MUITOS PEIXES PESCAR.\n\nALEGRES DESCOBRIRAM:\n''O CORDEIRO DE DEUS\nESTÁ VIVO ENTRE NÓS!''\nREINA PRA SEMPRE \nO MEU SALVADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (75, 'VOCÊ SABE QUEM FOI JOÃO BATISTA?', 'VOCÊ SABE QUEM FOI JOÃO BATISTA?', 'VOCÊ SABE QUEM FOI JOÃO BATISTA? \nFOI UM PROFETA DE DEUS. ELE VEIO PARA TESTEMUNHAR DE UMA VERDADEIRA LUZ.\n\nQUEM CRÊ EM JESUS TEM \nO PODER DE SER FEITO \nFILHO DE DEUS,\nCOM O DIREITO NA HERANÇA DA VIDA ETERNA COM JESUS.\n\nVOCÊ SABE QUEM FOI O OUTRO JOÃO? \nUM APÓSTOLO DE JESUS.\nESCREVEU O EVANGELHO \nDE JOÃO, PRA MOSTRAR \nQUE JESUS É DEUS.\n\nESCREVEU TAMBÉM JOÃO 1, 2, 3\nE O LIVRO DE APOCALIPSE,\nQUE CONTA A HISTÓRIA \nDO TEMPO DO FIM\nE DAS LINDAS PROMESSAS \nDE DEUS PARA A SUA IGREJA.', 'VOCÊ SABE QUEM FOI JOÃO BATISTA? \nFOI UM PROFETA DE DEUS. ELE VEIO PARA TESTEMUNHAR DE UMA VERDADEIRA LUZ.\n\nQUEM CRÊ EM JESUS TEM \nO PODER DE SER FEITO \nFILHO DE DEUS,\nCOM O DIREITO NA HERANÇA DA VIDA ETERNA COM JESUS.\n\nVOCÊ SABE QUEM FOI O OUTRO JOÃO? \nUM APÓSTOLO DE JESUS.\nESCREVEU O EVANGELHO \nDE JOÃO, PRA MOSTRAR \nQUE JESUS É DEUS.\n\nESCREVEU TAMBÉM JOÃO 1, 2, 3\nE O LIVRO DE APOCALIPSE,\nQUE CONTA A HISTÓRIA \nDO TEMPO DO FIM\nE DAS LINDAS PROMESSAS \nDE DEUS PARA A SUA IGREJA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (76, 'JESUS FALOU QUE O CÉU É PRA MIM', 'JESUS FALOU QUE O CÉU É PRA MIM', 'JESUS FALOU QUE \nO CÉU É PRA MIM (3X)\nJESUS FALOU QUE \nO CÉU É PRA MIM, \nO CÉU É PRA MIM, \nEU VOU COM ELE SIM.\n\nCORO \nE SE VOCÊ QUISER O CÉU TAMBÉM PRECISA ACEITAR \nJESUS EM SEU CORAÇÃO,\nPARA PODER LHE TRANSFORMAR\nE O CÉU LHE DAR \nE LÁ VOCÊ MORAR.\n\nEU SOU FIEL E \nJESUS ME QUER BEM, (3X)\nPOR ISSO EU SEI QUE \nO CÉU É PRA MIM,\nO CÉU É PRA MIM. \nEU VOU PRA GLÓRIA, SIM.\n\nCORO \nE SE VOCÊ QUISER O CÉU TAMBÉM PRECISA ACEITAR \nJESUS EM SEU CORAÇÃO,\nPARA PODER LHE TRANSFORMAR\nE O CÉU LHE DAR \nE LÁ VOCÊ MORAR.', 'JESUS FALOU QUE \nO CÉU É PRA MIM <bis tipo=''3x''>\nJESUS FALOU QUE \nO CÉU É PRA MIM, \nO CÉU É PRA MIM, \nEU VOU COM ELE SIM.\n\n<coro>\nE SE VOCÊ QUISER O CÉU TAMBÉM PRECISA ACEITAR \nJESUS EM SEU CORAÇÃO,\nPARA PODER LHE TRANSFORMAR\nE O CÉU LHE DAR \nE LÁ VOCÊ MORAR.\n\nEU SOU FIEL E \nJESUS ME QUER BEM, <bis tipo=''3x''>\nPOR ISSO EU SEI QUE \nO CÉU É PRA MIM,\nO CÉU É PRA MIM. \nEU VOU PRA GLÓRIA, SIM.\n\n<coro>\nE SE VOCÊ QUISER O CÉU TAMBÉM PRECISA ACEITAR \nJESUS EM SEU CORAÇÃO,\nPARA PODER LHE TRANSFORMAR\nE O CÉU LHE DAR \nE LÁ VOCÊ MORAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (77, 'VOU CONTAR-VOS DE JESUS', 'VOU CONTAR-VOS DE JESUS', 'VOU CONTAR-VOS DE JESUS\nO QUE JOÃO NOS ENSINOU:\nELE, POR AMOR, SE FEZ \nNOSSO SALVADOR.\n\nDE ALUNOS QUE CHAMOU:\nPEDRO, ANDRÉ, TIAGO E JOÃO,\nFILIPE, BARTOLOMEU E\nMATEUS, TIAGO, SIMÃO, TOMÉ,\nJUDAS, O BOM AMIGO,\nOUTRO JUDAS, O TRAIDOR.\n\n\n\n \n\nJESUS A TODOS CHAMOU: \n''EU SOU CAMINHO, \nA VERDADE E A LUZ'',\nA ELES ENSINOU.\n\n\nVOU CONTAR-VOS DE JESUS\nO QUE JOÃO NOS ENSINOU:\nELE, POR AMOR, SE FEZ \nNOSSO SALVADOR.\n\nDE ALUNOS QUE CHAMOU:\nPEDRO, ANDRÉ, TIAGO E JOÃO,\nFILIPE, BARTOLOMEU E\nMATEUS, TIAGO, SIMÃO, TOMÉ,\nJUDAS, O BOM AMIGO,\nOUTRO JUDAS, O TRAIDOR.\n \n\n\n\n \n\nJESUS A TODOS CHAMOU: \n''EU SOU CAMINHO, \nA VERDADE E A LUZ'',\nA ELES ENSINOU.', 'VOU CONTAR-VOS DE JESUS\nO QUE JOÃO NOS ENSINOU:\nELE, POR AMOR, SE FEZ \nNOSSO SALVADOR.\n\nDE ALUNOS QUE CHAMOU:\nPEDRO, ANDRÉ, TIAGO E JOÃO,\nFILIPE, BARTOLOMEU E\nMATEUS, TIAGO, SIMÃO, TOMÉ,\nJUDAS, O BOM AMIGO,\nOUTRO JUDAS, O TRAIDOR.\n\n\n\n \n\nJESUS A TODOS CHAMOU: \n''EU SOU CAMINHO, \nA VERDADE E A LUZ'',\nA ELES ENSINOU.\n\n\nVOU CONTAR-VOS DE JESUS\nO QUE JOÃO NOS ENSINOU:\nELE, POR AMOR, SE FEZ \nNOSSO SALVADOR.\n\nDE ALUNOS QUE CHAMOU:\nPEDRO, ANDRÉ, TIAGO E JOÃO,\nFILIPE, BARTOLOMEU E\nMATEUS, TIAGO, SIMÃO, TOMÉ,\nJUDAS, O BOM AMIGO,\nOUTRO JUDAS, O TRAIDOR.\n \n\n\n\n \n\nJESUS A TODOS CHAMOU: \n''EU SOU CAMINHO, \nA VERDADE E A LUZ'',\nA ELES ENSINOU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (78, 'O SENHOR É A MINHA LUZ', 'O SENHOR É A MINHA LUZ', 'O SENHOR É A MINHA LUZ\nE A MINHA SALVAÇÃO.\nA QUEM EU TEMEREI? DE QUEM ME RECEAREI?\n\nBOM E RETO É O SENHOR, POIS APONTA O CAMINHO AO PECADOR. NELE HÁ O PERDÃO, NELE ESPERO TODO DIA. (3X)', 'O SENHOR É A MINHA LUZ<bis>\nE A MINHA SALVAÇÃO.<bis>\nA QUEM EU TEMEREI? DE QUEM ME RECEAREI?<bis>\n\nBOM E RETO É O SENHOR, POIS APONTA O CAMINHO AO PECADOR. NELE HÁ O PERDÃO, NELE ESPERO TODO DIA. <bis tipo=''3x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (79, 'DEUS AMA VOCÊ', 'DEUS AMA VOCÊ', 'DEUS AMA VOCÊ\nE ELE QUER TE SALVAR,\nELE VAI OPERAR \nEM SEU CORAÇÃO.\n\nA VIDA QUE UM DIA VOCÊ NÃO CONHECIA,\nGOZO, PAZ E ALEGRIA EM JESUS ENCONTROU.\n\nELE É O CAMINHO, \nA VERDADE E A VIDA\nE OFERECE A VOCÊ SALVAÇÃO.\nBASTA ABRIR A PORTA DO CORAÇÃO,\nPRA SENTIR A SUA PAZ E PERDÃO.\n\nELE É O CAMINHO, \nA VERDADE E A VIDA\nE OFERECE A VOCÊ SALVAÇÃO.\nBASTA ABRIR A PORTA DO CORAÇÃO,\nPRA SENTIR A SUA PAZ E PERDÃO. (2X)', 'DEUS AMA VOCÊ\nE ELE QUER TE SALVAR,\nELE VAI OPERAR \nEM SEU CORAÇÃO.\n\nA VIDA QUE UM DIA VOCÊ NÃO CONHECIA,\nGOZO, PAZ E ALEGRIA EM JESUS ENCONTROU.\n\nELE É O CAMINHO,\n\n\n \nA VERDADE E A VIDA\nE OFERECE A VOCÊ SALVAÇÃO.\nBASTA ABRIR\n A PORTA DO CORAÇÃO,\nPRA SENTIR A SUA PAZ E PERDÃO.\n\nELE É O CAMINHO,\n\n\n \nA VERDADE E A VIDA\nE OFERECE A VOCÊ SALVAÇÃO.\nBASTA ABRIR\n A PORTA DO CORAÇÃO,\nPRA SENTIR A SUA PAZ E PERDÃO. <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (80, 'EXISTE UM LUGAR', 'EXISTE UM LUGAR', 'EXISTE UM LUGAR\nQUE MEU JESUS FOI PREPARAR.\nSE VOCÊ QUISER CHEGAR LÁ,\nÉ SÓ A ELE SE ENTREGAR.\n\nESSE LUGAR É O CÉU DE LUZ,\nONDE HABITA O MEU JESUS.\nSE QUERES PAZ, ALEGRIA E PERDÃO\nENTREGA A ELE O TEU CORAÇÃO.', 'EXISTE UM LUGAR\nQUE MEU JESUS FOI PREPARAR.\nSE VOCÊ QUISER CHEGAR LÁ,\nÉ SÓ A ELE SE ENTREGAR.\n\nESSE LUGAR É O CÉU DE LUZ,\nONDE HABITA O MEU JESUS.\nSE QUERES PAZ, ALEGRIA E PERDÃO\nENTREGA A ELE O TEU CORAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (81, 'QUANDO OUVI JESUS ME CHAMAR', 'QUANDO OUVI JESUS ME CHAMAR', 'QUANDO OUVI JESUS ME CHAMAR PENSEI QUE ERA IRREAL,\nSUA VOZ DOCE E MEIGA \nA DIZER: ''VINDE PEQUENINOS DO PAI''.\n\nENTÃO PUDE CRER QUE JESUS\nQUER USAR-ME TAMBÉM.\nAINDA PEQUENINO SOU,\nMAS POSSO LEVAR, DE DEUS, \nA MENSAGEM DE AMOR. \n\n\nCORO\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.\n\n\nSE QUERES TER DE CRISTO O PERDÃO\nABRE HOJE O TEU CORAÇÃO.\nDEIXE CRISTO ENTRAR E REINAR \nE A PAZ EM TUA VIDA NUNCA IRÁ FALTAR.\n\n\nCORO\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM. \n\n\nCORO\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.', 'QUANDO OUVI JESUS ME CHAMAR PENSEI QUE ERA IRREAL,\nSUA VOZ DOCE E MEIGA \nA DIZER: ''VINDE PEQUENINOS DO PAI''.\n\nENTÃO PUDE CRER QUE JESUS\nQUER USAR-ME TAMBÉM.\nAINDA PEQUENINO SOU,\nMAS POSSO LEVAR, DE DEUS, \nA MENSAGEM DE AMOR. \n\n<coro>\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.\n\n\nSE QUERES TER DE CRISTO O PERDÃO\nABRE HOJE O TEU CORAÇÃO.\nDEIXE CRISTO ENTRAR E REINAR \nE A PAZ EM TUA VIDA NUNCA IRÁ FALTAR.\n\n<coro>\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM. \n\n<coro>\nQUEM QUER SUBIR PARA O CÉU \nPEQUENO SE FAÇA TAMBÉM,\nENTREGA TUA VIDA A JESUS,\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.\nO PAI CELESTE QUE DESEJA \nA TI TODO BEM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (82, 'JESUS VEM NOS BUSCAR', 'JESUS VEM NOS BUSCAR', 'JESUS VEM NOS BUSCAR, PROMETEU E NÃO FALHARÁ, PORÉM ELE NOS DISSE: DOIS CAMINHOS HAVERÁ.\n\nUM CAMINHO É CERTO, É ESTREITO E APERTADO, É O CAMINHO DE JESUS, FIRMADO NELE QUERO ESTAR.\n\nOUTRO CAMINHO TAMBÉM HÁ, É LARGO, ESPAÇOSO \nE CONDUZ À PERDIÇÃO, POR ELE MUITOS VÃO, \nPOIS REJEITAM DE JESUS A SALVAÇÃO.\n\nJESUS A TODOS CONVIDA: ''EU SOU O CAMINHO A VERDADE E A VIDA''.\n VEM DEPRESSA, VEM DEPRESSA, VEM, A PORTA ABERTA UM DIA FECHARÁ.', 'JESUS VEM NOS BUSCAR, PROMETEU E NÃO FALHARÁ, PORÉM ELE NOS DISSE: DOIS CAMINHOS HAVERÁ.\n\nUM CAMINHO É CERTO, É ESTREITO E APERTADO, É O CAMINHO DE JESUS, FIRMADO NELE QUERO ESTAR.\n\nOUTRO CAMINHO TAMBÉM HÁ, É LARGO, ESPAÇOSO \nE CONDUZ À PERDIÇÃO, POR ELE MUITOS VÃO, \nPOIS REJEITAM DE JESUS A SALVAÇÃO.\n\nJESUS A TODOS CONVIDA: ''EU SOU O CAMINHO A VERDADE E A VIDA''.\n VEM DEPRESSA, VEM DEPRESSA, VEM, A PORTA ABERTA UM DIA FECHARÁ.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (83, 'FOI NO CAMINHO PARA DAMASCO', 'FOI NO CAMINHO PARA DAMASCO', 'FOI NO CAMINHO PARA DAMASCO \nQUE O GRANDE SAULO, PERSEGUIDOR,\nVIU GLORIOSA LUZ CELESTE, \nQUE POR TERRA O DERRUBOU.\n\nDESSA LUZ SURGIU A VOZ:\nSAULO, SAULO, \nQUE ME PERSEGUES.\nELE, CAÍDO, RESPONDEU:\nQUEM ÉS, SENHOR? \nQUEM ÉS, SENHOR?\n\nINSTRUMENTOS\n\nEU SOU JESUS, QUE TU PERSEGUES.\nQUE QUERES TU, SENHOR, QUE EU FAÇA?\nLEVANTA-TE E OBEDECE.\nNOVO CAMINHO JESUS TE DÁ.\n\nQUERO TAMBÉM SER DE JESUS,\nTER ESTA LUZ, ME ILUMINAR.\nE A CADA PASSO OUVIR SUA VOZ, \nATÉ O DIA QUE AO CÉU CHEGAR.', 'FOI NO CAMINHO PARA DAMASCO \nQUE O GRANDE SAULO, PERSEGUIDOR,\nVIU GLORIOSA LUZ CELESTE, \nQUE POR TERRA O DERRUBOU.\n\nDESSA LUZ SURGIU A VOZ:\nSAULO, SAULO, \nQUE ME PERSEGUES.\nELE, CAÍDO, RESPONDEU:\nQUEM ÉS, SENHOR? \nQUEM ÉS, SENHOR?\n<instrumentos>\n\n\nEU SOU JESUS, QUE TU PERSEGUES.\nQUE QUERES TU, SENHOR, QUE EU FAÇA?\nLEVANTA-TE E OBEDECE.\nNOVO CAMINHO JESUS TE DÁ.\n\nQUERO TAMBÉM SER DE JESUS,\nTER ESTA LUZ, ME ILUMINAR.\nE A CADA PASSO OUVIR SUA VOZ, \nATÉ O DIA QUE AO CÉU CHEGAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (84, 'QUERES SER FELIZ?', 'QUERES SER FELIZ?', 'QUERES SER FELIZ, CONHECER JESUS?\nELE VAI TE DAR ALEGRIA, VIDA E PAZ.\n\nEU JÁ SOU FELIZ, \nDEI MEU CORAÇÃO \nE JESUS EM MIM \nVEIO HABITAR.\n\nQUERES SER FELIZ, CONHECER JESUS?\nELE VAI TE DAR ALEGRIA, VIDA E PAZ.\n\nEU JÁ SOU FELIZ, DEI MEU CORAÇÃO \nE JESUS EM MIM VEIO HABITAR.', 'QUERES SER FELIZ, CONHECER JESUS?\nELE VAI TE DAR ALEGRIA, VIDA E PAZ.\n\nEU JÁ SOU FELIZ, \nDEI MEU CORAÇÃO \nE JESUS EM MIM \nVEIO HABITAR.\n\nQUERES SER FELIZ, CONHECER JESUS?\nELE VAI TE DAR ALEGRIA, VIDA E PAZ.\n\nEU JÁ SOU FELIZ, DEI MEU CORAÇÃO \nE JESUS EM MIM VEIO HABITAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (85, 'NESTE DIA ESPECIAL', 'NESTE DIA ESPECIAL', 'Neste dia especial, \nVou lhe apresentar Jesus,\nQue dissipa todo o mal e faz\nRaiar em nós sua luz. \n\nCORO\nJESUS É BOM AMIGO, \nABRIGO NO TEMPORAL,\nQUE NOS LIVRA DO PERIGO \nE POR NÓS VENCEU O MAL. \n\nABRA o seu coração e venha conhecer jesus,\nCom amor e segurança À\nVida eterna O conduz \n\nCORO\nJESUS É BOM AMIGO, \nABRIGO NO TEMPORAL,\nQUE NOS LIVRA DO PERIGO \nE POR NÓS VENCEU O MAL. \n\nFINAL: SIM, POR NÓS VENCEU O MAL.', 'Neste dia especial, \nVou lhe apresentar Jesus,\nQue dissipa todo o mal e faz\nRaiar em nós sua luz. \n\n<coro>\nJESUS É BOM AMIGO, \nABRIGO NO TEMPORAL,\nQUE NOS LIVRA DO PERIGO \nE POR NÓS VENCEU O MAL. \n\nABRA o seu coração e venha conhecer jesus,\nCom amor e segurança À\nVida eterna O conduz \n\n<coro>\nJESUS É BOM AMIGO, \nABRIGO NO TEMPORAL,\nQUE NOS LIVRA DO PERIGO \nE POR NÓS VENCEU O MAL. \n<final>SIM, POR NÓS VENCEU O MAL.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (86, 'UM DIA MORREU O MEU JESUS', 'UM DIA MORREU O MEU JESUS', 'UM DIA MORREU O MEU JESUS\nNAQUELA CRUZ POR MIM,\nO SANGUE DERRAMADO \nLIMPOU OS MEUS PECADOS.\nEU VOU CANTAR, \nPORQUE JESUS ESTÁ AQUI.\n\nCORO\nAGORA MEU JESUS VOU ADORAR, EU VOU CANTAR. \nEU VOU LOUVAR COMO DAVI,\nAO DERROTAR \nOS QUE QUERIAM O ATINGIR.\n \nINSTRUMENTOS\n\nJESUS, EU QUERO \nMINHA VIDA TE ENTREGAR \nE QUERO MAIS \nA TUA OBRA REALIZAR,\nSERVI-LO SEMPRE \nDE TODO O CORAÇÃO\nE SEMPRE EU CANTAREI \nESTA CANÇÃO.\n\nCORO (2X)\nAGORA MEU JESUS VOU ADORAR, EU VOU CANTAR. \nEU VOU LOUVAR COMO DAVI,\nAO DERROTAR OS QUE \nQUERIAM O ATINGIR.', 'UM DIA MORREU O MEU JESUS\nNAQUELA CRUZ POR MIM,\nO SANGUE DERRAMADO \nLIMPOU OS MEUS PECADOS.\nEU VOU CANTAR, \nPORQUE JESUS ESTÁ AQUI.\n\n<coro>\nAGORA MEU JESUS VOU ADORAR, EU VOU CANTAR. \nEU VOU LOUVAR COMO DAVI,\nAO DERROTAR \nOS QUE QUERIAM O ATINGIR.\n<instrumentos>\n\n\nJESUS, EU QUERO \nMINHA VIDA TE ENTREGAR \nE QUERO MAIS \nA TUA OBRA REALIZAR,\nSERVI-LO SEMPRE \nDE TODO O CORAÇÃO\nE SEMPRE EU CANTAREI \nESTA CANÇÃO.\n\n<coro tipo=''2X''>\nAGORA MEU JESUS VOU ADORAR, EU VOU CANTAR. \nEU VOU LOUVAR COMO DAVI,\nAO DERROTAR OS QUE \nQUERIAM O ATINGIR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (87, 'O SENHOR É O BOM PASTOR', 'O SENHOR É O BOM PASTOR', 'O SENHOR É O BOM PASTOR,\nELE É O SALVADOR,\nO DEUS DE PAZ E DE ALEGRIA,\nO DEUS DE AMOR.\n\nCORO\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\n\nELE CURA E SALVA,\nFALA AOS CORAÇÕES,\nCUIDA DOS SEUS FILHOS\nCOM MUITO AMOR.\n\nCORO\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\n\n\n\n\nCORO\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\nNO CAMINHO DE CRISTO JESUS.', 'O SENHOR É O BOM PASTOR,\nELE É O SALVADOR,\nO DEUS DE PAZ E DE ALEGRIA,\nO DEUS DE AMOR.\n\n<coro>\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\n\nELE CURA E SALVA,\nFALA AOS CORAÇÕES,\nCUIDA DOS SEUS FILHOS\nCOM MUITO AMOR.\n\n<coro>\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\n\n\n\n\n<coro>\nELE VEM ME BUSCAR \nE VAI ME LEVAR\nPARA A CIDADE CELESTIAL.\nVOCÊ TAMBÉM PODE IR,\nÉ SÓ ANDAR NO CAMINHO \nDE CRISTO JESUS.\nNO CAMINHO DE CRISTO JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (88, 'VOU CONTAR PARA VOCÊ UMA HISTÓRIA ESPECIAL', 'VOU CONTAR PARA VOCÊ UMA HISTÓRIA ESPECIAL', 'VOU CONTAR PARA VOCÊ\nUMA HISTÓRIA ESPECIAL:\nÉ A HISTÓRIA DE JESUS,\nNOSSO AMIGO LEAL.\n\nELE VEIO COM A MISSÃO\nDE NOS DAR A SALVAÇÃO,\nPARA TANTO HOMEM SE FEZ,\nDEIXOU O CÉU DE ESPLENDOR,\nVEIO À TERRA DEMONSTRAR\nDE DEUS O INFINITO AMOR\n\nPADECEU EM UMA CRUZ\nE MORREU PARA NOS LIMPAR,\nNOSSO PECADO LAVAR\nCOM SEU SANGUE REMIDOR,\nE VIVO ELE ESTÁ!\n\n\nNO TERCEIRO DIA \nRESSUSCITOU,\nÀ DIREITA DE DEUS PAI\nROGA PELO PECADOR.\n\nBREVE, BREVE VOLTARÁ\nPARA A IGREJA ARREBATAR\nE JUNTOS VAMOS MORAR\nNO CELESTE LAR DE AMOR.\n\nSE VOCÊ TAMBÉM QUISER\nNESTE LAR DE AMOR MORAR\nBASTA ABRIR SEU CORAÇÃO\nE DEIXAR JESUS ENTRAR.\n\nFINAL:\nBASTA ABRIR SEU CORAÇÃO\nE DEIXAR JESUS ENTRAR.', 'VOU CONTAR PARA VOCÊ\nUMA HISTÓRIA ESPECIAL:\nÉ A HISTÓRIA DE JESUS,\nNOSSO AMIGO LEAL.\n\nELE VEIO COM A MISSÃO\nDE NOS DAR A SALVAÇÃO,\nPARA TANTO HOMEM SE FEZ,\nDEIXOU O CÉU DE ESPLENDOR,\nVEIO À TERRA DEMONSTRAR\nDE DEUS O INFINITO AMOR\n\nPADECEU EM UMA CRUZ\nE MORREU PARA NOS LIMPAR,\nNOSSO PECADO LAVAR\nCOM SEU SANGUE REMIDOR,\nE VIVO ELE ESTÁ!\n\n\nNO TERCEIRO DIA \nRESSUSCITOU,\nÀ DIREITA DE DEUS PAI\nROGA PELO PECADOR.\n\nBREVE, BREVE VOLTARÁ\nPARA A IGREJA ARREBATAR\nE JUNTOS VAMOS MORAR\nNO CELESTE LAR DE AMOR.\n\nSE VOCÊ TAMBÉM QUISER\nNESTE LAR DE AMOR MORAR\nBASTA ABRIR SEU CORAÇÃO\nE DEIXAR JESUS ENTRAR.\n<final>BASTA ABRIR SEU CORAÇÃO\nE DEIXAR JESUS ENTRAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (89, 'CERTO HOMEM, PRÍNCIPE DOS JUDEUS (NICODEMOS)', 'CERTO HOMEM, PRÍNCIPE DOS JUDEUS (NICODEMOS)', 'CERTO HOMEM, \nPRÍNCIPE DOS JUDEUS,\nFOI AO MESTRE \nPERGUNTAR-LHE ASSIM: \n\nBEM SABEMOS QUE \nÉS MESTRE VINDO DE DEUS. \nCOMO PODE ALGUÉM \nNASCER DE NOVO? \n\nAQUELE QUE NÃO NASCER\nDA ÁGUA E DO ESPÍRITO \nNÃO PODE VER O REINO DE DEUS. \nMAS AQUELE QUE PERMANECER \nFIEL ATÉ O FIM, O VERÁ.', 'CERTO HOMEM, \nPRÍNCIPE DOS JUDEUS,\nFOI AO MESTRE \nPERGUNTAR-LHE ASSIM: \n\nBEM SABEMOS QUE \nÉS MESTRE VINDO DE DEUS. \nCOMO PODE ALGUÉM \nNASCER DE NOVO? \n\nAQUELE QUE NÃO NASCER\nDA ÁGUA E DO ESPÍRITO \nNÃO PODE VER O REINO DE DEUS. \nMAS AQUELE QUE PERMANECER \nFIEL ATÉ O FIM, O VERÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (90, 'ELE MORREU MAS RESSURGIU', 'ELE MORREU MAS RESSURGIU', 'ELE MORREU, MAS RESSURGIU; \nPLENA PAZ ENCHEU O MEU VIVER; \nJESUS É TUDO O QUE SEMPRE QUIS, \nJESUS ME TROUXE O SEU PERDÃO.\n\n\nQUERO FALAR DESTA SALVAÇÃO, \nPOR ONDE QUER QUE EU POSSA ANDAR, \nJESUS É TUDO, ELE É A PAZ. \nQUE VOCÊ PODE ENCONTRAR (2X)\n\nINSTRUMENTOS\n\nCRISTO, O SENHOR, É QUEM ME CONDUZ, \nLIVRA-ME DO MAL E DA TENTAÇÃO. \nE O SEU AMOR SEMPRE TRADUZ \nVIDA REAL E O CÉU PRA MIM! \n\nCRISTO JESUS É O MEU SENHOR\nSEMPRE PRESENTE NO MEU CORAÇÃO.\nBREVE VIRÁ DO CÉU ME BUSCAR. \nQUE ALEGRIA SERÁ! (2X)', 'ELE MORREU, MAS RESSURGIU; \nPLENA PAZ ENCHEU O MEU VIVER; \nJESUS É TUDO O QUE SEMPRE QUIS, \nJESUS ME TROUXE O SEU PERDÃO.\n\n\nQUERO FALAR DESTA SALVAÇÃO, \nPOR ONDE QUER QUE EU POSSA ANDAR, \nJESUS É TUDO, ELE É A PAZ. \nQUE VOCÊ PODE ENCONTRAR <bis tipo=''2x''>\n<instrumentos>\n\n\nCRISTO, O SENHOR, É QUEM ME CONDUZ, \nLIVRA-ME DO MAL E DA TENTAÇÃO. \nE O SEU AMOR SEMPRE TRADUZ \nVIDA REAL E O CÉU PRA MIM! \n\nCRISTO JESUS É O MEU SENHOR\nSEMPRE PRESENTE NO MEU CORAÇÃO.\nBREVE VIRÁ DO CÉU ME BUSCAR. \nQUE ALEGRIA SERÁ! <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (91, 'TENHO ALGO PRA VOCÊ', 'TENHO ALGO PRA VOCÊ', 'TENHO ALGO PRA VOCÊ NESTA CANÇÃO:\nTEM ALGUÉM QUE MORA EM MEU CORAÇÃO.\nESTE ALGUÉM DESEJA DAR A VOCÊ O PERDÃO.\n\nESTE ALGUÉM É MUITO \nIMPORTANTE!\nESTÁ BEM PERTO DE VOCÊ \nA TODO INSTANTE.\nELE SÓ POR NÓS MORREU \nNUMA CRUZ. ESTE ALGUÉM, \nLHE DIGO, É: JESUS', 'TENHO ALGO PRA VOCÊ NESTA CANÇÃO:\nTEM ALGUÉM QUE MORA EM MEU CORAÇÃO.\nESTE ALGUÉM DESEJA DAR A VOCÊ O PERDÃO.\n\nESTE ALGUÉM É MUITO \nIMPORTANTE!\nESTÁ BEM PERTO DE VOCÊ \nA TODO INSTANTE.\nELE SÓ POR NÓS MORREU \nNUMA CRUZ. ESTE ALGUÉM, \nLHE DIGO, É: JESUS', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (92, 'JESUS CURA E SALVA', 'JESUS CURA E SALVA', 'JESUS CURA E SALVA,\nJESUS É O MEU SALVADOR;\nJESUS É MEU AMIGO,\nE ELE É O MEU REDENTOR. \n\nQUANDO ESTOU DOENTE, CURA ELE DÁ, \nQUANDO ESTOU TRISTE, A PAZ VEM REINAR!\n\nJESUS É FORÇA \nE ESPERANÇA! \nJESUS É O PRÍNCIPE\nDA PAZ!', 'JESUS CURA E SALVA,\nJESUS É O MEU SALVADOR;\nJESUS É MEU AMIGO,\nE ELE É O MEU REDENTOR. \n\nQUANDO ESTOU DOENTE, CURA ELE DÁ, \nQUANDO ESTOU TRISTE, A PAZ VEM REINAR!\n\nJESUS É FORÇA \nE ESPERANÇA! \nJESUS É O PRÍNCIPE\nDA PAZ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (93, 'JESUS TE AMA', 'JESUS TE AMA', 'JESUS TE AMA,\nELE QUER TE SALVAR,\nDEIXA A LUZ ENTRAR \nEM TEU CORAÇÃO.\n\nELE QUER TRANSFORMAR \nTEU CHORO EM ALEGRIA,\nELE QUER TE DAR PAZ, \nGOZO E ESPERANÇA.\n\nJESUS TE AMA \n(JESUS TE AMA),\nELE QUER TE SALVAR\n(ELE QUER TE SALVAR),\nDEIXA A LUZ \n(DEIXA A LUZ)\nENTRAR EM TEU CORAÇÃO.\n\nELE QUER TRANSFORMAR \nTEU CHORO EM ALEGRIA,\nELE QUER TE DAR PAZ, \nGOZO E ESPERANÇA.\n\nSE TU QUISERES\n(SE TU QUISERES)\nACEITAR A CRISTO\n(ACEITAR A CRISTO),\nABRE HOJE MESMO \n(ABRE HOJE MESMO)\nO SEU CORAÇÃO!\n\nJESUS TE CHAMA!\nJESUS TE AMA!\nJESUS TE AMA!', 'JESUS TE AMA,\nELE QUER TE SALVAR,\nDEIXA A LUZ ENTRAR \nEM TEU CORAÇÃO.\n\nELE QUER TRANSFORMAR \nTEU CHORO EM ALEGRIA,\nELE QUER TE DAR PAZ, \nGOZO E ESPERANÇA.\n\nJESUS TE AMA \n(JESUS TE AMA),\nELE QUER TE SALVAR\n(ELE QUER TE SALVAR),\nDEIXA A LUZ \n(DEIXA A LUZ)\nENTRAR EM TEU CORAÇÃO.\n\nELE QUER TRANSFORMAR \nTEU CHORO EM ALEGRIA,\nELE QUER TE DAR PAZ, \nGOZO E ESPERANÇA.\n\nSE TU QUISERES\n(SE TU QUISERES)\nACEITAR A CRISTO\n(ACEITAR A CRISTO),\nABRE HOJE MESMO \n(ABRE HOJE MESMO)\nO SEU CORAÇÃO!\n\nJESUS TE CHAMA!\nJESUS TE AMA!\nJESUS TE AMA!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (94, 'AQUELE QUE TEM SEDE', 'AQUELE QUE TEM SEDE', 'AQUELE QUE TEM SEDE \nVÁ À FONTE E BEBA,\nSUAS ÁGUAS DESSEDENTAM\nE TRAZEM VIDA.\n\nRIOS DE ÁGUAS CORRERÃO\nNO SEU INTERIOR, E A ALEGRIA QUE SALTA\nPARA A VIDA ETERNA.\n\nJESUS É ESSA FONTE DE VIDA, QUE SACIA A SEDE DA ALMA.\nVENHA A ELE E BEBA,\nE UMA VIDA ETERNA LHE DARÁ. \n\nAQUELE QUE TEM SEDE \nVÁ À FONTE E BEBA,\nSUAS ÁGUAS DESSEDENTAM\nE TRAZEM VIDA.\n\nRIOS DE ÁGUAS CORRERÃO\nNO SEU INTERIOR, E A ALEGRIA QUE SALTA\nPARA A VIDA ETERNA.', 'AQUELE QUE TEM SEDE \nVÁ À FONTE E BEBA,\nSUAS ÁGUAS DESSEDENTAM\nE TRAZEM VIDA.\n\nRIOS DE ÁGUAS CORRERÃO\nNO SEU INTERIOR, E A ALEGRIA QUE SALTA\nPARA A VIDA ETERNA.\n\nJESUS É ESSA FONTE DE VIDA, QUE SACIA A SEDE DA ALMA.\nVENHA A ELE E BEBA,\nE UMA VIDA ETERNA LHE DARÁ. \n\nAQUELE QUE TEM SEDE \nVÁ À FONTE E BEBA,\nSUAS ÁGUAS DESSEDENTAM\nE TRAZEM VIDA.\n\nRIOS DE ÁGUAS CORRERÃO\nNO SEU INTERIOR, E A ALEGRIA QUE SALTA\nPARA A VIDA ETERNA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (95, 'DO PÃO DO CÉU', 'DO PÃO DO CÉU', 'DO PÃO DO CÉU ME NUTRIREI,\nDA FONTE ETERNA BEBEREI;\n''E QUEM BEBER'', \nNOS DIZ JESUS,\n''JAMAIS DE SEDE SOFRERÁ.''\n\nNÃO MAIS SEDE? \nQUE DIZEIS? \nNÃO MAIS SEDE \nASSIM SERÁS!\n\n''E QUEM BEBER,'' \nNOS DIZ JESUS\n''JAMAIS DE SEDE SOFRERÁ.''\nSEDE NÃO TERÁ!', 'DO PÃO DO CÉU ME NUTRIREI,\nDA FONTE ETERNA BEBEREI;\n''E QUEM BEBER'', \nNOS DIZ JESUS,\n''JAMAIS DE SEDE SOFRERÁ.''\n\nNÃO MAIS SEDE? <bis>\nQUE DIZEIS? <bis>\nNÃO MAIS SEDE <bis>\nASSIM SERÁS!<bis>\n\n''E QUEM BEBER,'' \nNOS DIZ JESUS\n''JAMAIS DE SEDE SOFRERÁ.''\nSEDE NÃO TERÁ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (96, 'SONHEI COM JESUS ESTA NOITE', 'SONHEI COM JESUS ESTA NOITE', 'SONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''\n\nEU IMPLOREI A JESUS: ''SENHOR TEM DE MIM COMPAIXÃO EU VIVO VAGANDO NO MUNDO SEM PAZ SEM CONSOLAÇÃO'' ''EU VIVO VAGANDO NO MUNDO SEM PAZ SEM CONSOLAÇÃO''\n\nSONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''\n\nUMA VOZ ME FALOU BAIXINHO NO FUNDO DO CORAÇÃO ''OH PECADOR VEM DE PRESSA CRISTO TE DÁ SALVAÇÃO'' ''OH PECADOR VEM DE PRESSA CRISTO TE DÁ SALVAÇÃO''\n\nSONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''', 'SONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''\n\nEU IMPLOREI A JESUS: ''SENHOR TEM DE MIM COMPAIXÃO EU VIVO VAGANDO NO MUNDO SEM PAZ SEM CONSOLAÇÃO'' ''EU VIVO VAGANDO NO MUNDO SEM PAZ SEM CONSOLAÇÃO''\n\nSONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''\n\nUMA VOZ ME FALOU BAIXINHO NO FUNDO DO CORAÇÃO ''OH PECADOR VEM DE PRESSA CRISTO TE DÁ SALVAÇÃO'' ''OH PECADOR VEM DE PRESSA CRISTO TE DÁ SALVAÇÃO''\n\nSONHEI COM JESUS ESTA NOITE UM CONSELHO ELE ME DEU: ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU'' ''NÃO SIGAS POR OUTRO CAMINHO QUE A PORTA DO CÉU SOU EU''', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (97, 'JESUS É O CAMINHO', 'JESUS É O CAMINHO', 'JESUS É O CAMINHO \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.\n\nJESUS É A VERDADE \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.\n\nJESUS É A MINHA VIDA \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.', 'JESUS É O CAMINHO \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.\n\nJESUS É A VERDADE \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.\n\nJESUS É A MINHA VIDA \nEU VOU AO CÉU COM ELE\n\nEU VOU, EU VOU \nEU VOU AO CÉU COM ELE.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (98, 'EU ABRI MEU CORAÇÃO', 'EU ABRI MEU CORAÇÃO', 'EU ABRI MEU CORAÇÃO\nE JESUS VEIO HABITAR;\nDE MANSO BATEU\nLOGO A PORTA ABRI EU,\nE ELE VEIO EM MIM MORAR.\n\nEU ABRI MEU CORAÇÃO\nE JESUS VEIO HABITAR;\nDE MANSO BATEU\nLOGO A PORTA ABRI EU,\nE ELE VEIO EM MIM MORAR.', 'EU ABRI MEU CORAÇÃO\nE JESUS VEIO HABITAR;\nDE MANSO BATEU\nLOGO A PORTA ABRI EU,\nE ELE VEIO EM MIM MORAR.\n\nEU ABRI MEU CORAÇÃO\nE JESUS VEIO HABITAR;\nDE MANSO BATEU\nLOGO A PORTA ABRI EU,\nE ELE VEIO EM MIM MORAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (99, 'NO MEU CORAÇÃO', 'NO MEU CORAÇÃO', 'NO MEU CORAÇÃO\nNO MEU CORAÇÃO\nVEM HOJE ENTRAR, Ó CRISTO!\nVEM HOJE ENTRAR, SIM, VEM MORAR\nNO MEU CORAÇÃO, Ó CRISTO.', 'NO MEU CORAÇÃO\nNO MEU CORAÇÃO\nVEM HOJE ENTRAR, Ó CRISTO!\nVEM HOJE ENTRAR, SIM, VEM MORAR\nNO MEU CORAÇÃO, Ó CRISTO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (100, 'CRISTO SENTE AMOR POR MIM', 'CRISTO SENTE AMOR POR MIM', 'CRISTO SENTE AMOR POR MIM,\nCOM CERTEZA EU CREIO ASSIM,\nPOR AMOR DE MIM MORREU,\nVIVO ESTÁ, POR MIM, NO CÉU.\n\nCORO\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.\n\nCRISTO TEM POR MIM AMOR\nE SE FEZ MEU SALVADOR,\nHOJE AINDA TEM PRAZER\nEM MENINOS RECEBER.\n\nCORO\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.\n\nPOR GOZAR SEU RICO AMOR\nHEI DE AMAR MEU SALVADOR,\nE DESEJO AQUI MOSTRAR\nSEU AMOR TÃO EXEMPLAR.\n\nCORO\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.', 'CRISTO SENTE AMOR POR MIM,\nCOM CERTEZA EU CREIO ASSIM,\nPOR AMOR DE MIM MORREU,\nVIVO ESTÁ, POR MIM, NO CÉU.\n\n<coro>\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.\n\nCRISTO TEM POR MIM AMOR\nE SE FEZ MEU SALVADOR,\nHOJE AINDA TEM PRAZER\nEM MENINOS RECEBER.<coro>\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.\n\nPOR GOZAR SEU RICO AMOR\nHEI DE AMAR MEU SALVADOR,\nE DESEJO AQUI MOSTRAR\nSEU AMOR TÃO EXEMPLAR.<coro>\nCRISTO NOS AMA, \nCRISTO NOS CHAMA, \nCRISTO PROCLAMA\nTÃO GRANDE SALVAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (101, 'JESUS ME AMA', 'JESUS ME AMA', 'JESUS ME AMA E QUER SALVAR-ME,\nJESUS ME AMA E QUER-ME BEM.\n\nCORO\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nESTIVE PRESO NO VIL PECADO,\nESTIVE PRESO, MAS ME SALVOU.\n\nCORO\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nCASTIGO DURO QUE EU MEREÇO,\nJESUS SOFREU JÁ EM MEU LUGAR.\n\nCORO\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nAGORA, QUERONA MINHA VIDA,\nAO MEU AMIGO SEMPRE AGRADAR.\n\nCORO\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.', 'JESUS ME AMA E QUER SALVAR-ME,\nJESUS ME AMA E QUER-ME BEM.<coro>\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nESTIVE PRESO NO VIL PECADO,\nESTIVE PRESO, MAS ME SALVOU.<coro>\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nCASTIGO DURO QUE EU MEREÇO,\nJESUS SOFREU JÁ EM MEU LUGAR.<coro>\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.\n\nAGORA, QUERONA MINHA VIDA,\nAO MEU AMIGO SEMPRE AGRADAR.<coro>\nPOR ISSO EU CANTO,\nSEMPRE ELE AMA,\nJESUS ME AMA, \nMEU SALVADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (102, 'DAS MARAVILHAS QUE A BÍBLIA CONTÉM', 'DAS MARAVILHAS QUE A BÍBLIA CONTÉM', 'DAS MARAVILHAS \nQUE A BÍBLIA CONTÉM,\nEIS A MAIS LINDA:\nJESUS ME QUER BEM;\n\nCHEGO-ME A ELE, \nNINGUÉM ME DETÉM,\nQUANDO ME LEMBRO \nDE QUE ME QUER BEM.\n\nOH! QUE PRAZER! \nJESUS ME QUER BEM,\nSIM, ME QUER BEM, \nA TI TAMBÉM;\nOH! QUE PRAZER! \nJESUS ME QUER BEM,\nSIM, ME QUER BEM, JESUS.', 'DAS MARAVILHAS \nQUE A BÍBLIA CONTÉM,\nEIS A MAIS LINDA:\nJESUS ME QUER BEM;\n\nCHEGO-ME A ELE, \nNINGUÉM ME DETÉM,\nQUANDO ME LEMBRO \nDE QUE ME QUER BEM.\n\nOH! QUE PRAZER! \nJESUS ME QUER BEM,\nSIM, ME QUER BEM, \nA TI TAMBÉM;\nOH! QUE PRAZER! \nJESUS ME QUER BEM,\nSIM, ME QUER BEM, JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (103, 'VINDE, MENINOS', 'VINDE, MENINOS', 'VINDE, MENINOS, \nVINDE A JESUS!\nELE GANHOU-VOS \nBÊNÇÃOS NA CRUZ,\nOS PEQUENINOS ELE CONDUZ,\nÓ VINDE AO SALVADOR!\n\nCORO\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.\n\nJÁ SEM DEMORA,\nHOJE CONVÉM\nIR CAMINHANDO À \nGLÓRIA ALÉM;\nJESUS VOS CHAMA, \nQUER VOSSO BEM,\nÓ VINDE AO SALVADOR!\n\nCORO\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.\n\nCRISTO VOS AMA, \nBEM ELE O DIZ,\nQUER RECEBER-VOS\nNO BOM PAÍS;\nQUER CONCEDER-VOS\nVIDA FELIZ,\nÓ VINDE AO SALVADOR!\n\nCORO\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.', 'VINDE, MENINOS, \nVINDE A JESUS!\nELE GANHOU-VOS \nBÊNÇÃOS NA CRUZ,\nOS PEQUENINOS ELE CONDUZ,\nÓ VINDE AO SALVADOR!\n\n<coro>\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.\n\nJÁ SEM DEMORA,\nHOJE CONVÉM\nIR CAMINHANDO À \nGLÓRIA ALÉM;\nJESUS VOS CHAMA, \nQUER VOSSO BEM,\nÓ VINDE AO SALVADOR!\n\n<coro>\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.\n\nCRISTO VOS AMA, \nBEM ELE O DIZ,\nQUER RECEBER-VOS\nNO BOM PAÍS;\nQUER CONCEDER-VOS\nVIDA FELIZ,\nÓ VINDE AO SALVADOR!\n\n<coro>\nQUE ALEGRIA! \nSEM PECADO OU MAL\nREUNIR-NOS TODOS, AFINAL,\nNA SANTA PÁTRIA CELESTIAL\nCOM NOSSO SALVADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (104, 'NO CAMINHO ELE ME GUIARÁ', 'NO CAMINHO ELE ME GUIARÁ', 'NO CAMINHO ELE ME GUIARÁ,\nELE QUER BEM\nA TODO PECADOR,\nO SEU AMOR POR MIM, \nVOCÊ OUVIU?\nDEUS GOSTA DE VOCÊ.\n\nCORO\nDEUS GOSTA DE VOCÊ, (BIS)\nO SEU AMOR VOCÊ VERÁ\nPOR TODA A PARTE QUE OLHAR;\nDEUS GOSTA DE VOCÊ.\n\nO SOL DOURADO\nELE FAZ NASCER,\nAS LINDAS FLORES\nELE FAZ ABRIR,\nQUANDO O DESERTO\nCHORA A CHUVA CAI,\nDEUS GOSTA DE VOCÊ.\n\nCORO\nDEUS GOSTA DE VOCÊ, (BIS)\nO SEU AMOR VOCÊ VERÁ\nPOR TODA A PARTE QUE OLHAR;\nDEUS GOSTA DE VOCÊ.', 'NO CAMINHO ELE ME GUIARÁ,\nELE QUER BEM\nA TODO PECADOR,\nO SEU AMOR POR MIM, \nVOCÊ OUVIU?\nDEUS GOSTA DE VOCÊ.\n\n<coro>\nDEUS GOSTA DE VOCÊ, <bis>\nO SEU AMOR VOCÊ VERÁ\nPOR TODA A PARTE QUE OLHAR;\nDEUS GOSTA DE VOCÊ.\n\nO SOL DOURADO\nELE FAZ NASCER,\nAS LINDAS FLORES\nELE FAZ ABRIR,\nQUANDO O DESERTO\nCHORA A CHUVA CAI,\nDEUS GOSTA DE VOCÊ.\n\n<coro>\nDEUS GOSTA DE VOCÊ, <bis>\nO SEU AMOR VOCÊ VERÁ\nPOR TODA A PARTE QUE OLHAR;\nDEUS GOSTA DE VOCÊ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (105, 'HAVEREMOS DE CHEGAR', 'HAVEREMOS DE CHEGAR', 'HAVEREMOS DE CHEGAR\nPELO PODER DO SENHOR EM JERUSALÉM;\nONDE A FELICIDADE PARA SEMPRE REINARÁ, EM JERUSALÉM.\n\nCORO\nALELUIA, CANTAREMOS,\nLOUVANDO AO SALVADOR\nEM JERUSALÉM,\nPOIS ALI JAMAIS OS MALES\nPODERÃO NOS ALCANÇAR,\nNA FELIZ JERUSALÉM.\n\nINSTRUMENTOS\n\nQUERES TU TAMBÉM ENTRAR \nCOM OS SALVOS POR JESUS EM JERUSALÉM?\nÉ PRECISO, HOJE MESMO, ACEITAR ESSA LUZ,\nCAMINHANDO A JERUSALÉM.\n\nCORO\nALELUIA, CANTAREMOS,\nLOUVANDO AO SALVADOR\nEM JERUSALÉM,\nPOIS ALI JAMAIS OS MALES\nPODERÃO NOS ALCANÇAR,\nNA FELIZ JERUSALÉM. \nNA FELIZ JERUSALÉM. \nNA FELIZ JERUSALÉM.', 'HAVEREMOS DE CHEGAR\nPELO PODER DO SENHOR EM JERUSALÉM;\nONDE A FELICIDADE PARA SEMPRE REINARÁ, EM JERUSALÉM.\n\n<coro>\nALELUIA, CANTAREMOS,\nLOUVANDO AO SALVADOR\nEM JERUSALÉM,\nPOIS ALI JAMAIS OS MALES\nPODERÃO NOS ALCANÇAR,\nNA FELIZ JERUSALÉM.\n<instrumentos>\n\n\nQUERES TU TAMBÉM ENTRAR \nCOM OS SALVOS POR JESUS EM JERUSALÉM?\nÉ PRECISO, HOJE MESMO, ACEITAR ESSA LUZ,\nCAMINHANDO A JERUSALÉM.\n\n<coro>\nALELUIA, CANTAREMOS,\nLOUVANDO AO SALVADOR\nEM JERUSALÉM,\nPOIS ALI JAMAIS OS MALES\nPODERÃO NOS ALCANÇAR,\nNA FELIZ JERUSALÉM. \nNA FELIZ JERUSALÉM. \nNA FELIZ JERUSALÉM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (106, 'JESUS CRISTO É O CAMINHO', 'JESUS CRISTO É O CAMINHO', 'JESUS CRISTO É O CAMINHO\nE O GUIA DE VALOR;\nELE SALVA TODO AQUELE\nQUE CONFIA EM SEU AMOR.\n\nJESUS CRISTO É O CAMINHO,\nJESUS CRISTO ME SALVOU,\nEU FUI SALVO PELA GRAÇA \nQUE EM MIM DEPOSITOU. \nEU FUI SALVO PELA GRAÇA \nQUE EM MIM DEPOSITOU.', 'JESUS CRISTO É O CAMINHO\nE O GUIA DE VALOR;\nELE SALVA TODO AQUELE\nQUE CONFIA EM SEU AMOR.\n\nJESUS CRISTO É O CAMINHO,\nJESUS CRISTO ME SALVOU,\nEU FUI SALVO PELA GRAÇA \nQUE EM MIM DEPOSITOU. \nEU FUI SALVO PELA GRAÇA \nQUE EM MIM DEPOSITOU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (107, 'EU QUERO CANTAR', 'EU QUERO CANTAR', 'EU QUERO CANTAR, \nEU QUERO FALAR\nQUE JESUS SALVA E CURA,\nQUE JESUS DEU-ME PAZ.\n\nREPETIR O HINO', 'EU QUERO CANTAR, \nEU QUERO FALAR\nQUE JESUS SALVA E CURA,\nQUE JESUS DEU-ME PAZ.\n\n<repetir tipo=''O HINOx''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (108, 'HOJE É UM GRANDE DIA', 'HOJE É UM GRANDE DIA', 'HOJE É UM GRANDE DIA, É DIA DE LOUVAR;\nLOUVEMOS A JESUS QUE ESTÁ NESTE LUGAR;\nHOJE É DIA DE VITÓRIA E VITÓRIA \nELE NOS DÁ; RECEBA JESUS, \nELE QUER TE ABENÇOAR.\n\nCORO\nVENHAM TODOS JÁ,\nA JESUS VAMOS LOUVAR!\nACEITEM O SALVADOR \nQUE VIDA ETERNA \nQUER LHES DAR!\n\nHOJE AQUI ESTOU PARA TE LOUVAR\nPOR TANTAS MARAVILHAS, \nPOR SEMPRE ME AMAR.\nTUA OBRA EM MINHA VIDA, \nVOU ANUNCIAR, OBRA DE ALEGRIA \nE ALEGRIA QUE É SEM PAR!\n\nCORO\nVENHAM TODOS JÁ,\nA JESUS VAMOS LOUVAR!\nACEITEM O SALVADOR \nQUE VIDA ETERNA \nQUER LHES DAR!', 'HOJE É UM GRANDE DIA, É DIA DE LOUVAR;\nLOUVEMOS A JESUS QUE ESTÁ NESTE LUGAR;\nHOJE É DIA DE VITÓRIA E VITÓRIA \nELE NOS DÁ; RECEBA JESUS, \nELE QUER TE ABENÇOAR.\n\n<coro>\nVENHAM TODOS JÁ,\nA JESUS VAMOS LOUVAR!\nACEITEM O SALVADOR \nQUE VIDA ETERNA \nQUER LHES DAR!\n\nHOJE AQUI ESTOU PARA TE LOUVAR\nPOR TANTAS MARAVILHAS, \nPOR SEMPRE ME AMAR.\nTUA OBRA EM MINHA VIDA, \nVOU ANUNCIAR, OBRA DE ALEGRIA \nE ALEGRIA QUE É SEM PAR!\n\n<coro>\nVENHAM TODOS JÁ,\nA JESUS VAMOS LOUVAR!\nACEITEM O SALVADOR \nQUE VIDA ETERNA \nQUER LHES DAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (109, 'CANTA ALEGREMENTE, Ó FILHA DE SIÃO', 'CANTA ALEGREMENTE, Ó FILHA DE SIÃO', 'CANTA ALEGREMENTE, \nÓ FILHA DE SIÃO;\nREJUBILA, Ó ISRAEL:\nREGOZIJA-TE E EXULTA \nDE TODO O CORAÇÃO,\nÓ FILHA DE JERUSALÉM.\n\nO SENHOR AFASTOU OS TEUS JUÍZOS,\nEXTERMINOU O TEU INIMIGO;\nO SENHOR, O REI DE ISRAEL,\nESTÁ NO MEIO DE TI;\nTU NÃO VERÁS MAIS MAL ALGUM.\n\n NAQUELE DIA SE DIRÁ \n A JERUSALÉM: NÃO TEMAS, \n Ó SIÃO, NÃO ENFRAQUEÇAM \n AS TUAS MÃOS.\n\nO SENHOR TEU DEUS \nESTÁ NO MEIO DE TI, \nPODEROSO PARA TE SALVAR; \nSE DELEITARÁ EM TI \nCOM ALEGRIA;\n\nCALAR-SE-Á POR SEU AMOR,\nREGOZIJAR-SE-Á EM TI COM JÚBILO,\nÓ FILHA DE JERUSALÉM (2X)', 'CANTA ALEGREMENTE, \nÓ FILHA DE SIÃO;\nREJUBILA, Ó ISRAEL:\nREGOZIJA-TE E EXULTA \nDE TODO O CORAÇÃO,\nÓ FILHA DE JERUSALÉM.\n\nO SENHOR AFASTOU OS TEUS JUÍZOS,\nEXTERMINOU O TEU INIMIGO;\nO SENHOR, O REI DE ISRAEL,\nESTÁ NO MEIO DE TI;\nTU NÃO VERÁS MAIS MAL ALGUM.\n\n NAQUELE DIA SE DIRÁ \n A JERUSALÉM: NÃO TEMAS, \n Ó SIÃO, NÃO ENFRAQUEÇAM \n AS TUAS MÃOS.\n\nO SENHOR TEU DEUS \nESTÁ NO MEIO DE TI, \nPODEROSO PARA TE SALVAR; \nSE DELEITARÁ EM TI \nCOM ALEGRIA;\n\nCALAR-SE-Á POR SEU AMOR,\nREGOZIJAR-SE-Á EM TI COM JÚBILO,\nÓ FILHA DE JERUSALÉM <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (110, 'EU TUDO POSSO', 'EU TUDO POSSO', 'CORO\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.\n \nEU VOO COMO UMA ÁGUIA, EU CRUZO MONTANHAS E VALES.\n\nCORO\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.\n\nEU VENÇO GIGANTES,\nEU VENÇO LEÕES,\nEU VENÇO OS LOBOS\nDO MUNDO. \n\nCORO\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE. \n\nEU CREIO NUM DEUS\nQUE VIVE E REINA,\nEU CREIO NUM DEUS\nQUE VENCE POR MIM. \n\nCORO\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.', '<coro>\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.\n \nEU VOO COMO UMA ÁGUIA, EU CRUZO MONTANHAS E VALES.\n\n<coro>\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.\n\nEU VENÇO GIGANTES,\nEU VENÇO LEÕES,\nEU VENÇO OS LOBOS\nDO MUNDO. \n\n<coro>\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE. \n\nEU CREIO NUM DEUS\nQUE VIVE E REINA,\nEU CREIO NUM DEUS\nQUE VENCE POR MIM. \n\n<coro>\nEU TUDO POSSO \nNAQUELE QUE \nME FORTALECE.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (111, 'ENTREGA O TEU CAMINHO', 'ENTREGA O TEU CAMINHO', 'ENTREGA O TEU CAMINHO \nAO SENHOR, CONFIA \nE O MAIS ELE FARÁ.\nALELUIA, ALELUIA, \nALELUIA, AMÉM.\nALELUIA, ALELUIA, \nALELUIA, AMÉM.', 'ENTREGA O TEU CAMINHO \nAO SENHOR, CONFIA \nE O MAIS ELE FARÁ.\nALELUIA, ALELUIA, \nALELUIA, AMÉM.\nALELUIA, ALELUIA, \nALELUIA, AMÉM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (112, 'CONSOLA-ME, ESPÍRITO SANTO', 'CONSOLA-ME, ESPÍRITO SANTO', 'CONSOLA-ME, \nESPÍRITO SANTO,\nPARA QUE EU POSSA \nAGUARDAR COM FÉ\nA VINDA DO FILHO \nDO DEUS DE ABRAÃO;\n\nCONSOLA-ME, \nCONSOLA-ME,\nCONSOLA-ME, SENHOR.\n\nCONSOLA-ME, \nESPÍRITO SANTO,\nPARA QUE EU POSSA \nAGUARDAR COM FÉ\nA VINDA DO FILHO \nDO DEUS DE ABRAÃO;\nCONSOLA-ME, CONSOLA-ME,\nCONSOLA-ME, SENHOR.', 'CONSOLA-ME, \nESPÍRITO SANTO,\nPARA QUE EU POSSA \nAGUARDAR COM FÉ\nA VINDA DO FILHO \nDO DEUS DE ABRAÃO;\n\nCONSOLA-ME, \nCONSOLA-ME,\nCONSOLA-ME, SENHOR.\n\nCONSOLA-ME, \nESPÍRITO SANTO,\nPARA QUE EU POSSA \nAGUARDAR COM FÉ\nA VINDA DO FILHO \nDO DEUS DE ABRAÃO;\nCONSOLA-ME, CONSOLA-ME,\nCONSOLA-ME, SENHOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (113, 'TUA MÃO É PODEROSA', 'TUA MÃO É PODEROSA', 'TUA MÃO É PODEROSA\nE O TEU NOME DOCE AMOR,\nNÃO TE AFASTARÁS DE MIM,\nNEM CONTENDES CONTRA MIM,\nANTES CUIDARÁS, \nSENHOR, DE MIM.\n\nTUA MÃO É PODEROSA\nE O TEU NOME DOCE AMOR,\nNÃO TE AFASTARÁS DE MIM,\nNEM CONTENDES CONTRA MIM,\nANTES CUIDARÁS,\nSENHOR, DE MIM.', 'TUA MÃO É PODEROSA\nE O TEU NOME DOCE AMOR,\nNÃO TE AFASTARÁS DE MIM,\nNEM CONTENDES CONTRA MIM,\nANTES CUIDARÁS, \nSENHOR, DE MIM.\n\nTUA MÃO É PODEROSA\nE O TEU NOME DOCE AMOR,\nNÃO TE AFASTARÁS DE MIM,\nNEM CONTENDES CONTRA MIM,\nANTES CUIDARÁS,\nSENHOR, DE MIM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (114, 'O SENHOR É QUEM CUIDA DE MIM', 'O SENHOR É QUEM CUIDA DE MIM', 'O SENHOR É QUEM \nCUIDA DE MIM, O SENHOR É QUEM\nCUIDA DE MIM,\n\nNADA HEI DE TEMER, \nCOM JESUS VOU VENCER, POIS EU SEI QUE \nELE CUIDA DE MIM.\n\nA JESUS SERVIREI \nCOM AMOR, POIS EU SEI \nQUE ELE É MEU SALVADOR.\nA MEU LADO ESTÁ, \nNUNCA VAI ME DEIXAR,\nPOIS EU SEI QUE ELE \nCUIDA DE MIM.', 'O SENHOR É QUEM \nCUIDA DE MIM, O SENHOR É QUEM\nCUIDA DE MIM,\n\nNADA HEI DE TEMER, \nCOM JESUS VOU VENCER, POIS EU SEI QUE \nELE CUIDA DE MIM.\n\nA JESUS SERVIREI \nCOM AMOR, POIS EU SEI \nQUE ELE É MEU SALVADOR.\nA MEU LADO ESTÁ, \nNUNCA VAI ME DEIXAR,\nPOIS EU SEI QUE ELE \nCUIDA DE MIM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (115, 'JESUS, O BOM PASTOR', 'JESUS, O BOM PASTOR', 'JESUS, O BOM PASTOR,\nCUIDA DE MIM \nCOM MUITO AMOR.\nA PASTOS VERDEJANTES\nSEMPRE LEVA-ME O SENHOR\n\nE A ÁGUAS TÃO TRANQUILAS MANSAMENTE ME CONDUZ.\nNAS VEREDAS DA JUSTIÇA,\nVIVEREI NA LUZ.\n\nSE MESMO O PERIGO \nTIVER QUE ENFRENTAR, \nSEI QUE MEU JESUS \nCOMIGO SEMPRE ESTARÁ.\nMEDO NÃO TEREI, \nPOIS SINTO SUA MÃO EM MIM.\nCOM O CAJADO DO SENHOR CONSOLO TENHO SIM!\n\nMESA ABUNDANTE HEI DE TER;\nÓLEO DO ESPÍRITO EM MEU VIVER;\nCÁLICE TRANSBORDANTE,\nVIDA ABUNDANTE,\nCOM A MISERICÓRDIA DO SENHOR.\n\nE POR LONGOS DIAS VIVEREI\nEM SUA CASA ETERNA HABITAREI. \nEM SUA CASA ETERNA HABITAREI.', 'JESUS, O BOM PASTOR,\nCUIDA DE MIM \nCOM MUITO AMOR.\nA PASTOS VERDEJANTES\nSEMPRE LEVA-ME O SENHOR\n\nE A ÁGUAS TÃO TRANQUILAS MANSAMENTE ME CONDUZ.\nNAS VEREDAS DA JUSTIÇA,\nVIVEREI NA LUZ.\n\nSE MESMO O PERIGO \nTIVER QUE ENFRENTAR, \nSEI QUE MEU JESUS \nCOMIGO SEMPRE ESTARÁ.\nMEDO NÃO TEREI, \nPOIS SINTO SUA MÃO EM MIM.\nCOM O CAJADO DO SENHOR CONSOLO TENHO SIM!\n\nMESA ABUNDANTE HEI DE TER;\nÓLEO DO ESPÍRITO EM MEU VIVER;\nCÁLICE TRANSBORDANTE,\nVIDA ABUNDANTE,\nCOM A MISERICÓRDIA DO SENHOR.\n\nE POR LONGOS DIAS VIVEREI\nEM SUA CASA ETERNA HABITAREI. \nEM SUA CASA ETERNA HABITAREI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (116, 'SOBRE AS ONDAS', 'SOBRE AS ONDAS', 'SOBRE AS ONDAS \nPODEREI ANDAR.\nJESUS ESTÁ COMIGO, \nNENHUM MAL ME ATINGIRÁ.\nSOPRA O VENTO, DEIXA SOPRAR\nJESUS ACALMA AS ONDAS\nE A PAZ VOLTA A REINAR.\n\nAS ONDAS VÃO SUBINDO,\nFORMANDO UM MONTÃO,\nESTE MUNDO MAU QUER\nNAUFRAGAR MEU CORAÇÃO.\nMAS NÃO TEMO, \nOLHO PARA JESUS.\nAO SOM DA SUA VOZ\nATÉ AS TREVAS VIRAM LUZ.', 'SOBRE AS ONDAS \nPODEREI ANDAR.\nJESUS ESTÁ COMIGO, \nNENHUM MAL ME ATINGIRÁ.\nSOPRA O VENTO, DEIXA SOPRAR\nJESUS ACALMA AS ONDAS\nE A PAZ VOLTA A REINAR.\n\nAS ONDAS VÃO SUBINDO,\nFORMANDO UM MONTÃO,\nESTE MUNDO MAU QUER\nNAUFRAGAR MEU CORAÇÃO.\nMAS NÃO TEMO, \nOLHO PARA JESUS.\nAO SOM DA SUA VOZ\nATÉ AS TREVAS VIRAM LUZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (117, 'DEITADA NA RELVA', 'DEITADA NA RELVA', 'DEITADA NA RELVA \nUMA FELIZ OVELHA\nJUNTO AO PASTOR \nESTÁ A DESCANSAR,\n\nNAS ÁGUAS TRANQUILAS\nSACIA SUA SEDE,\nDA RELVA BEM VERDE\nPODE SE ALIMENTAR.\n\nCORO\nOVELHA, JAMAIS \nDEIXE ESTE APRISCO. \nTENS O BOM PASTOR \nPARA DE TI CUIDAR.\nNO MUNDO LÁ FORA \nHÁ TRISTEZA E GUERRA, \nJESUS É A ALEGRIA, \nVERDADE E PAZ.\n\nE QUANDO AS TREVAS \nCAEM SOBRE O MUNDO\nO TENTADOR VEM \nDISPOSTO A TRAGAR.\nJESUS EM SEUS BRAÇOS, \nOVELHA, TE ACOLHE,\nPARA QUE TU POSSAS \nA VIDA HERDAR.\n\nCORO\nOVELHA, JAMAIS \nDEIXE ESTE APRISCO. \nTENS O BOM PASTOR \nPARA DE TI CUIDAR.\nNO MUNDO LÁ FORA \nHÁ TRISTEZA E GUERRA, \nJESUS É A ALEGRIA, \nVERDADE E PAZ.', 'DEITADA NA RELVA \nUMA FELIZ OVELHA\nJUNTO AO PASTOR \nESTÁ A DESCANSAR,\n\nNAS ÁGUAS TRANQUILAS\nSACIA SUA SEDE,\nDA RELVA BEM VERDE\nPODE SE ALIMENTAR.\n\n<coro>\nOVELHA, JAMAIS \nDEIXE ESTE APRISCO. \nTENS O BOM PASTOR \nPARA DE TI CUIDAR.\nNO MUNDO LÁ FORA \nHÁ TRISTEZA E GUERRA, \nJESUS É A ALEGRIA, \nVERDADE E PAZ.\n\nE QUANDO AS TREVAS \nCAEM SOBRE O MUNDO\nO TENTADOR VEM \nDISPOSTO A TRAGAR.\nJESUS EM SEUS BRAÇOS, \nOVELHA, TE ACOLHE,\nPARA QUE TU POSSAS \nA VIDA HERDAR.\n\n<coro>\nOVELHA, JAMAIS \nDEIXE ESTE APRISCO. \nTENS O BOM PASTOR \nPARA DE TI CUIDAR.\nNO MUNDO LÁ FORA \nHÁ TRISTEZA E GUERRA, \nJESUS É A ALEGRIA, \nVERDADE E PAZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (118, 'ÂNCORA SEGURA', 'ÂNCORA SEGURA', 'UMA ÂNCORA SEGURA \nTENHO NO SENHOR,\nQUEM NELE CONFIOU\nJAMAIS PERDIDO SE ACHOU.\n\nEU CONFIO NO SENHOR,\nSEGURO NELE ESTOU,\nSEI DE FATOS GRANDIOSOS,\nRESPOSTAS DO SENHOR:\n\nELIAS PEDIU A DEUS, FOGO DO CÉU DESCEU, CONSUMINDO O HOLOCAUSTO, O POVO SE ALEGROU: SÓ O SENHOR É DEUS! SÓ O SENHOR É DEUS!\n\nPEDRO SUBIU AO TEMPLO, VIU UM COXO A ESMOLAR. MELHOR QUE PRATA E OURO\nÉ O NOME DE JESUS.\nGRAÇA SE DERRAMOU, \nO COXO SE LEVANTOU.\nO POVO SE ALEGROU: \nSÓ O SENHOR É DEUS! \n \n\nPAULO VIU A TORMENTA DESTRUIR A NAU SEM RUMO. TODOS DESANIMADOS, \nPAULO ANUNCIOU:\nO ANJO DE DEUS FALOU: NINGUÉM SE PERDERÁ. TODOS CHEGARAM VIVOS,\nSÓ O SENHOR É DEUS!', 'UMA ÂNCORA SEGURA \nTENHO NO SENHOR,\nQUEM NELE CONFIOU\nJAMAIS PERDIDO SE ACHOU.\n\nEU CONFIO NO SENHOR,\nSEGURO NELE ESTOU,\nSEI DE FATOS GRANDIOSOS,\nRESPOSTAS DO SENHOR:\n\nELIAS PEDIU A DEUS, FOGO DO CÉU DESCEU, CONSUMINDO O HOLOCAUSTO, O POVO SE ALEGROU: SÓ O SENHOR É DEUS! SÓ O SENHOR É DEUS!\n\nPEDRO SUBIU AO TEMPLO, VIU UM COXO A ESMOLAR. MELHOR QUE PRATA E OURO\nÉ O NOME DE JESUS.\nGRAÇA SE DERRAMOU, \nO COXO SE LEVANTOU.\nO POVO SE ALEGROU: \nSÓ O SENHOR É DEUS! \n \n\nPAULO VIU A TORMENTA DESTRUIR A NAU SEM RUMO. TODOS DESANIMADOS, \nPAULO ANUNCIOU:\nO ANJO DE DEUS FALOU: NINGUÉM SE PERDERÁ. TODOS CHEGARAM VIVOS,\nSÓ O SENHOR É DEUS!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (119, 'JESUS, O MELHOR AMIGO', 'JESUS, O MELHOR AMIGO', 'JESUS, O MELHOR AMIGO,\nQUE SEMPRE ESTÁ PRESENTE.\nNELE HÁ PODER \nPARA MUDAR O CRENTE.\n\nCORO (2X) \nMESMO EM LUTAS E AFLIÇÕES ELE RESPONDE ÀS NOSSAS ORAÇÕES.\n\nJESUS TEM PODER.\nMESMO EM GUERRAS E BATALHAS\nVOCÊ VAI VENCER, \nPORQUE JESUS NÃO FALHA.\n\nSE VOCÊ QUISER UMA BÊNÇÃO,\nBASTA SOMENTE CRER,\nÉ SÓ PEDIR A ELE,\nQUE VOCÊ VAI RECEBER.\n\nCORO (2X) \nMESMO EM LUTAS E AFLIÇÕES ELE RESPONDE ÀS NOSSAS ORAÇÕES.', 'JESUS, O MELHOR AMIGO,\nQUE SEMPRE ESTÁ PRESENTE.\nNELE HÁ PODER \nPARA MUDAR O CRENTE.\n\n<coro tipo=''2X''>\nMESMO EM LUTAS E AFLIÇÕES ELE RESPONDE ÀS NOSSAS ORAÇÕES.\n\nJESUS TEM PODER.\nMESMO EM GUERRAS E BATALHAS\nVOCÊ VAI VENCER, \nPORQUE JESUS NÃO FALHA.\n\nSE VOCÊ QUISER UMA BÊNÇÃO,\nBASTA SOMENTE CRER,\nÉ SÓ PEDIR A ELE,\nQUE VOCÊ VAI RECEBER.\n\n<coro tipo=''2X''>\nMESMO EM LUTAS E AFLIÇÕES ELE RESPONDE ÀS NOSSAS ORAÇÕES.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (120, 'PODERÁ CANTAR', 'PODERÁ CANTAR', 'CORO\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.\n\n\nESPEREI PELO SENHOR COM PACIÊNCIA\nE ME FIRMOU OS PASSOS.\nDE ESCORREGAR LIVROU-ME,\nDEU-ME UM NOVO CANTO.\n\nCORO\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.\n\nO CORAÇÃO FIRME EM CRISTO\nPOR VENDAVAIS NÃO VACILARÁ.\nNÃO EM AREIA, MAS NA ROCHA,\nOUVI SUA VOZ, QUE SEGURANÇA!\n\n\nCORO\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.', '<coro>\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.\n\n\nESPEREI PELO SENHOR COM PACIÊNCIA\nE ME FIRMOU OS PASSOS.\nDE ESCORREGAR LIVROU-ME,\nDEU-ME UM NOVO CANTO.\n\n<coro>\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.\n\nO CORAÇÃO FIRME EM CRISTO\nPOR VENDAVAIS NÃO VACILARÁ.\nNÃO EM AREIA, MAS NA ROCHA,\nOUVI SUA VOZ, QUE SEGURANÇA!\n\n\n<coro>\nPODERÁ CANTAR \nQUEM NA ROCHA ESTIVER,\nPODERÁ CANTAR, \nPOIS COM JESUS \nFIRMADO ESTARÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (121, 'MEU BARQUINHO', 'MEU BARQUINHO', 'MEU BARQUINHO \nNAVEGA NO MAR,\nMUI FELIZ VIVO \nSEMPRE A CANTAR,\n\nGRANDES ONDAS\nVÊM PARA O NAUFRAGAR,\nNÃO TENHO MEDO, \nVOU A ÂNCORA LANÇAR.\n\nCORO\nVOU A JESUS, VOU A ÂNCORA LANÇAR.\nVOU A JESUS, POR SEU SANGUE VOU CLAMAR\nE FELIZ VOU AO PORTO CHEGAR.\nALELUIA! ALELUIA É O MEU CANTAR! \n\nMEU JESUS É AMIGO FIEL,\nPOR SUA MÃO ME CONDUZ ATÉ AO CÉU\nE SE UM DIA VIER A AFLIÇÃO,\nNÃO TENHO MEDO, \nPOIS É ELE O CAPITÃO.\n\nCORO\nVOU A JESUS, VOU A ÂNCORA LANÇAR.\nVOU A JESUS, POR SEU SANGUE VOU CLAMAR\nE FELIZ VOU AO PORTO CHEGAR.\nALELUIA! ALELUIA É O MEU CANTAR!', 'MEU BARQUINHO \nNAVEGA NO MAR,\nMUI FELIZ VIVO \nSEMPRE A CANTAR,\n\nGRANDES ONDAS\nVÊM PARA O NAUFRAGAR,\nNÃO TENHO MEDO, \nVOU A ÂNCORA LANÇAR.\n\n<coro>\nVOU A JESUS, VOU A ÂNCORA LANÇAR.\nVOU A JESUS, POR SEU SANGUE VOU CLAMAR\nE FELIZ VOU AO PORTO CHEGAR.\nALELUIA! ALELUIA É O MEU CANTAR! \n\nMEU JESUS É AMIGO FIEL,\nPOR SUA MÃO ME CONDUZ ATÉ AO CÉU\nE SE UM DIA VIER A AFLIÇÃO,\nNÃO TENHO MEDO, \nPOIS É ELE O CAPITÃO.\n\n<coro>\nVOU A JESUS, VOU A ÂNCORA LANÇAR.\nVOU A JESUS, POR SEU SANGUE VOU CLAMAR\nE FELIZ VOU AO PORTO CHEGAR.\nALELUIA! ALELUIA É O MEU CANTAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (122, 'CRISTO É MEU AMIGO', 'CRISTO É MEU AMIGO', 'CRISTO É MEU AMIGO,\nELE ESTÁ COMIGO.\nALELUIA, ALELUIA, \nALELUIA, ALELUIA,\nELE ESTÁ COMIGO.\n\nCRISTO É TEU AMIGO,\nELE ESTÁ CONTIGO.\nALELUIA, ALELUIA, \nALELUIA, ALELUIA,\nELE ESTÁ CONTIGO.', 'CRISTO É MEU AMIGO,\nELE ESTÁ COMIGO.\nALELUIA, ALELUIA, \nALELUIA, ALELUIA,\nELE ESTÁ COMIGO.\n\nCRISTO É TEU AMIGO,\nELE ESTÁ CONTIGO.\nALELUIA, ALELUIA, \nALELUIA, ALELUIA,\nELE ESTÁ CONTIGO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (123, 'NESTA BATALHA NÃO TEREIS QUE PELEJAR', 'NESTA BATALHA NÃO TEREIS QUE PELEJAR', 'NESTA BATALHA NÃO TEREIS QUE PELEJAR;\nAGUARDAI, FICAI PARADOS,\nE VEDE A SALVAÇÃO DO SENHOR \nPARA CONVOSCO, Ó JUDÁ E JERUSALÉM.\n\nNÃO TEMAIS, NEM VOS ASSUSTEIS;\nAMANHÃ SAÍ-LHES AO ENCONTRO,\nPORQUE O SENHOR SERÁ CONVOSCO.\nNESTA BATALHA NÃO TEREIS QUE PELEJAR.', 'NESTA BATALHA NÃO TEREIS QUE PELEJAR;\nAGUARDAI, FICAI PARADOS,\nE VEDE A SALVAÇÃO DO SENHOR \nPARA CONVOSCO, Ó JUDÁ E JERUSALÉM.\n\nNÃO TEMAIS, NEM VOS ASSUSTEIS;\nAMANHÃ SAÍ-LHES AO ENCONTRO,\nPORQUE O SENHOR SERÁ CONVOSCO.\nNESTA BATALHA NÃO TEREIS QUE PELEJAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (124, 'O CÉU E A TERRA PASSARÃO', 'O CÉU E A TERRA PASSARÃO', 'O CÉU E A TERRA PASSARÃO\nMAS AS MINHAS PALAVRAS \nNÃO HÃO DE PASSAR.\n\nEU SOU DEUS, SOU FIEL,\nNÃO TEMAIS, NEM VOS ASSUSTEIS!\nPROCLAMAI A VITÓRIA,\nRENOVAI A VOSSA FÉ,\nE O VOSSO ÂNIMO PORQUE\nA TERRA PROMETIDA VOS DAREI. (BIS)\n\n125 - COM JESUS VENCEDOR SEREI \n\nCOM JESUS VENCEDOR SEREI! \nCOM JESUS VENCEDOR SEREI! \nVENCEDOR, VENCEDOR,\nVENCEDOR SEREI!\nCOM JESUS VENCEDOR SEREI!\n\nNAS BATALHAS ELE ME ACOMPANHA. \nNAS BATALHAS ELE ME ACOMPANHA.\nMEU JESUS, MEU JESUS,\nSEMPRE ME ACOMPANHA.\nCOM JESUS VENCEDOR SEREI!\nCOM JESUS VENCEDOR SEREI!\n\nELE É O MEU SALVADOR.\nELE É O MEU SALVADOR. \nSALVADOR, SALVADOR \nÉ O MEU JESUS! \nCOM JESUS VENCEDOR SEREI!', 'O CÉU E A TERRA PASSARÃO\nMAS AS MINHAS PALAVRAS \nNÃO HÃO DE PASSAR.\n\nEU SOU DEUS, SOU FIEL,\nNÃO TEMAIS, NEM VOS ASSUSTEIS!\nPROCLAMAI A VITÓRIA,\nRENOVAI A VOSSA FÉ,\nE O VOSSO ÂNIMO PORQUE\nA TERRA PROMETIDA VOS DAREI. <bis>\n\n125 - COM JESUS VENCEDOR SEREI \n\nCOM JESUS VENCEDOR SEREI! \nCOM JESUS VENCEDOR SEREI! \nVENCEDOR, VENCEDOR,\nVENCEDOR SEREI!\nCOM JESUS VENCEDOR SEREI!\n\nNAS BATALHAS ELE ME ACOMPANHA. \nNAS BATALHAS ELE ME ACOMPANHA.\nMEU JESUS, MEU JESUS,\nSEMPRE ME ACOMPANHA.\nCOM JESUS VENCEDOR SEREI!\nCOM JESUS VENCEDOR SEREI!\n\nELE É O MEU SALVADOR.\nELE É O MEU SALVADOR. \nSALVADOR, SALVADOR \nÉ O MEU JESUS! \nCOM JESUS VENCEDOR SEREI!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (126, 'DEUS FORTE COMO JEOVÁ', 'DEUS FORTE COMO JEOVÁ', 'DEUS FORTE \nCOMO JEOVÁ\nNÃO HÁ OUTRO \nQUE EU CONHEÇA.\n\nDEUS DE VITÓRIA, \nVARÃO DE GUERRA,\nDEUS PODEROSO \nÉ O SENHOR. \n\nONDE, ONDE ESTÁ\nO TEU DEUS? \nONDE, ONDE ESTÁ\nO TEU DEUS? \n\nMEU DEUS ESTÁ NO CÉU,\nTAMBÉM NO MEU CORAÇÃO, \nO DO MUNDO ESTÁ MORTO\nMAS O MEU RESSUSCITOU.', 'DEUS FORTE \nCOMO JEOVÁ\nNÃO HÁ OUTRO \nQUE EU CONHEÇA.\n\nDEUS DE VITÓRIA, \nVARÃO DE GUERRA,\nDEUS PODEROSO \nÉ O SENHOR. \n\nONDE, ONDE ESTÁ\nO TEU DEUS? \nONDE, ONDE ESTÁ\nO TEU DEUS? \n\nMEU DEUS ESTÁ NO CÉU,\nTAMBÉM NO MEU CORAÇÃO, \nO DO MUNDO ESTÁ MORTO\nMAS O MEU RESSUSCITOU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (127, 'CRISTO É VITÓRIA', 'CRISTO É VITÓRIA', 'CRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER; \nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\nPOIS TEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.', 'CRISTO É VITÓRIA!\nPROCLAMAI COM REAL PRAZER; \nCRISTO É VITÓRIA!\nE COM ELE VAMOS NÓS VENCER!\n\nSE FALTAR PRAZER E LUZ,\nTUDO NOS DÁ JESUS,\nPOIS TEMOS VITÓRIA\nPOR QUEM JÁ VENCEU NA CRUZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (128, 'CRISTO É MEU AMIGO, É MEU AMIGO', 'CRISTO É MEU AMIGO, É MEU AMIGO', 'CRISTO É MEU AMIGO,\nÉ MEU AMIGO, \nSEGURA FIRME \nA MINHA MÃO! \n\nQUANDO EU ANDO BEM,\nQUANDO ESTOU DOENTE,\nQUANDO ESTOU CONTENTE,\nOU TRISTE ESTOU: ALELUIA!\n\nCRISTO É MEU AMIGO, \nÉ MEU AMIGO,\nSEGURA FIRME A MINHA MÃO!\n\nREPETIR O HINO', 'CRISTO É MEU AMIGO,\nÉ MEU AMIGO, \nSEGURA FIRME \nA MINHA MÃO! \n\nQUANDO EU ANDO BEM,\nQUANDO ESTOU DOENTE,\nQUANDO ESTOU CONTENTE,\nOU TRISTE ESTOU: ALELUIA!\n\nCRISTO É MEU AMIGO, \nÉ MEU AMIGO,\nSEGURA FIRME A MINHA MÃO!\n\n<repetir tipo=''O HINOx''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (129, 'ONTEM, HOJE E PARA SEMPRE', 'ONTEM, HOJE E PARA SEMPRE', 'ONTEM, HOJE E PARA SEMPRE\nO SALVADOR É IGUAL, TODOS MUDAM, \nMENOS CRISTO, ROCHA ETERNAL.\n\nROCHA ETERNAL, \nROCHA ETERNAL,\nTODOS MUDAM,\nMENOS CRISTO,\nROCHA ETERNAL.', 'ONTEM, HOJE E PARA SEMPRE\nO SALVADOR É IGUAL, TODOS MUDAM, \nMENOS CRISTO, ROCHA ETERNAL.\n\nROCHA ETERNAL, \nROCHA ETERNAL,\nTODOS MUDAM,\nMENOS CRISTO,\nROCHA ETERNAL.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (130, 'MEU BOM PASTOR É CRISTO', 'MEU BOM PASTOR É CRISTO', 'MEU BOM PASTOR É CRISTO, \nCOM ELE ANDAREI;\nCONDUZ-ME ÀS CALMAS ÁGUAS,\nCOM ELE ANDAREI, \nSEMPRE, SEMPRE\nCOM ELE ANDAREI.', 'MEU BOM PASTOR É CRISTO, \nCOM ELE ANDAREI;\nCONDUZ-ME ÀS CALMAS ÁGUAS,\nCOM ELE ANDAREI, \nSEMPRE, SEMPRE\nCOM ELE ANDAREI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (131, 'COM CRISTO NO BARCO', 'COM CRISTO NO BARCO', 'COM CRISTO NO BARCO\nTUDO VAI MUITO BEM,\nVAI MUITO BEM \nVAI MUITO BEM \nCOM CRISTO NO BARCO\nTUDO VAI MUITO BEM,\nE PASSA O TEMPORAL.\n\nPASSA O TEMPORAL, PASSA O TEMPORAL. COM CRISTO NO BARCO \nTUDO VAI MUITO BEM, E PASSA O TEMPORAL', 'COM CRISTO NO BARCO\nTUDO VAI MUITO BEM,\nVAI MUITO BEM \nVAI MUITO BEM \nCOM CRISTO NO BARCO\nTUDO VAI MUITO BEM,\nE PASSA O TEMPORAL.\n\nPASSA O TEMPORAL, PASSA O TEMPORAL. COM CRISTO NO BARCO \nTUDO VAI MUITO BEM, E PASSA O TEMPORAL', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (132, 'MEU BARCO É PEQUENO', 'MEU BARCO É PEQUENO', 'MEU BARCO É PEQUENO\nE GRANDE É O MAR,\nJESUS SEGURA MINHA MÃO;\nELE É MEU PILOTO\nE TUDO VAI BEM\nNA VIAGEM PRA JERUSALÉM.\n\nJESUS VÊ A SUA IGREJA \nCOMO UM FORTE EDIFÍCIO,\nFIRME E EDIFICADO \nPARA MORADA DE DEUS.\n\n133 - JESUS VÊ A SUA IGREJA \n\nCORO (2X)\nNÃO É FEITA DE TIJOLO \nE MADEIRA, NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO. \n\nEDIFÍCIO ESPECIAL\nDESENHADO POR JESUS,\nPARA SEMPRE ERGUIDO \nPELO SANTO ESPÍRITO.\n\nCORO (2X)\nNÃO É FEITA DE TIJOLO \nE MADEIRA, NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO. \n\nVENHA PARA A IGREJA,\nVAMOS JUNTOS TRABALHAR\nNESTA OBRA GLORIOSA \nATÉ JESUS VOLTAR.\n\nCORO (2X)\nNÃO É FEITA DE TIJOLO \nE MADEIRA NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO.', 'MEU BARCO É PEQUENO\nE GRANDE É O MAR,\nJESUS SEGURA MINHA MÃO;\nELE É MEU PILOTO\nE TUDO VAI BEM\nNA VIAGEM PRA JERUSALÉM.\n\nJESUS VÊ A SUA IGREJA \nCOMO UM FORTE EDIFÍCIO,\nFIRME E EDIFICADO \nPARA MORADA DE DEUS.\n\n133 - JESUS VÊ A SUA IGREJA \n\n<coro tipo=''2X''>\nNÃO É FEITA DE TIJOLO \nE MADEIRA, NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO. \n\nEDIFÍCIO ESPECIAL\nDESENHADO POR JESUS,\nPARA SEMPRE ERGUIDO \nPELO SANTO ESPÍRITO.\n\n<coro tipo=''2X''>\nNÃO É FEITA DE TIJOLO \nE MADEIRA, NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO. \n\nVENHA PARA A IGREJA,\nVAMOS JUNTOS TRABALHAR\nNESTA OBRA GLORIOSA \nATÉ JESUS VOLTAR.\n\n<coro tipo=''2X''>\nNÃO É FEITA DE TIJOLO \nE MADEIRA NÃO!\nÉ JESUS BEM VIVO NO CORAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (134, 'VOU CAMINHANDO PRA JERUSALÉM', 'VOU CAMINHANDO PRA JERUSALÉM', 'VOU CAMINHANDO \nPRA JERUSALÉM,\nA CADA DIA, \nCHEGO MAIS PERTO, \n\nQUEM ME CONDUZ \nÉ O MEU JESUS\nPOIS NO CLAMOR \nSEU SANGUE LIMPA \nE ANDO NA LUZ;\n\n\nE TENHO AS ARMAS ESPIRITUAIS: \nA ORAÇÃO, O LOUVOR, O JEJUM \nE MADRUGADA E A PALAVRA REVELADA\nQUE ALIMENTA A ALMA E NOS ENSINA \nA VONTADE DO SENHOR.\n\nVOU CAMINHANDO\nPRA JERUSALÉM,\nSE VOCÊ QUISER, \nVENHA COMIGO TAMBÉM\nSE VOCÊ QUISER, \nVENHA COMIGO TAMBÉM', 'VOU CAMINHANDO \nPRA JERUSALÉM,\nA CADA DIA, \nCHEGO MAIS PERTO, \n\nQUEM ME CONDUZ \nÉ O MEU JESUS\nPOIS NO CLAMOR \nSEU SANGUE LIMPA \nE ANDO NA LUZ;\n\n\nE TENHO AS ARMAS ESPIRITUAIS: \nA ORAÇÃO, O LOUVOR, O JEJUM \nE MADRUGADA E A PALAVRA REVELADA\nQUE ALIMENTA A ALMA E NOS ENSINA \nA VONTADE DO SENHOR.\n\nVOU CAMINHANDO\nPRA JERUSALÉM,\nSE VOCÊ QUISER, \nVENHA COMIGO TAMBÉM\nSE VOCÊ QUISER, \nVENHA COMIGO TAMBÉM', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (135, 'FLUA EM MIM, SENHOR', 'FLUA EM MIM, SENHOR', 'FLUA EM MIM, SENHOR,\nDO TEU ESPÍRITO,\nEU VOU TESTEMUNHAR \nDE TEU AMOR SEM PAR,\nAO MUNDO ANUNCIAR\nQUE CRISTO SALVA O PECADOR.\n\nFLUA EM MIM, SENHOR, \nDO TEU ESPÍRITO,\nFLUA EM MIM, SENHOR,\nDO TEU ESPÍRITO,\nEU VOU TESTEMUNHAR\nDE TEU AMOR SEM PAR,\nAO MUNDO ANUNCIAR\nQUE CRISTO SALVA O PECADOR.', 'FLUA EM MIM, SENHOR,\nDO TEU ESPÍRITO,\nEU VOU TESTEMUNHAR \nDE TEU AMOR SEM PAR,\nAO MUNDO ANUNCIAR\nQUE CRISTO SALVA O PECADOR.\n\nFLUA EM MIM, SENHOR, \nDO TEU ESPÍRITO,\nFLUA EM MIM, SENHOR,\nDO TEU ESPÍRITO,\nEU VOU TESTEMUNHAR\nDE TEU AMOR SEM PAR,\nAO MUNDO ANUNCIAR\nQUE CRISTO SALVA O PECADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (136, 'LÂMPADA PARA OS MEUS PÉS', 'LÂMPADA PARA OS MEUS PÉS', 'LÂMPADA PARA OS MEUS PÉS,\nO CAMINHO ILUMINA,\nREVELADA POR DEUS,\nGUIARÁ O MEU CORAÇÃO.\n\nCORO\nA BÍBLIA É UM TESOURO \nDESCOBERTO PARA AQUELES \nQUE DE JESUS ESTÃO PERTO;\nA MINHA BÍBLIA VOU SEMPRE LER, PARA MAIS DE JESUS CONHECER.\n\n\nQUERO AMAR TUA PALAVRA,\nGUARDÁ-LA SEMPRE \nEM MEU CORAÇÃO,\nENSINAR ÀS PESSOAS\nQUE SÓ JESUS É A SALVAÇÃO.\n\nCORO\nA BÍBLIA É UM TESOURO \nDESCOBERTO PARA AQUELES \nQUE DE JESUS ESTÃO PERTO;\nA MINHA BÍBLIA \nVOU SEMPRE LER, PARA MAIS \nDE JESUS CONHECER.', 'LÂMPADA PARA OS MEUS PÉS,\nO CAMINHO ILUMINA,\nREVELADA POR DEUS,\nGUIARÁ O MEU CORAÇÃO.\n\n<coro>\nA BÍBLIA É UM TESOURO \nDESCOBERTO PARA AQUELES \nQUE DE JESUS ESTÃO PERTO;\nA MINHA BÍBLIA VOU SEMPRE LER, PARA MAIS DE JESUS CONHECER.\n\n\nQUERO AMAR TUA PALAVRA,\nGUARDÁ-LA SEMPRE \nEM MEU CORAÇÃO,\nENSINAR ÀS PESSOAS\nQUE SÓ JESUS É A SALVAÇÃO.\n\n<coro>\nA BÍBLIA É UM TESOURO \nDESCOBERTO PARA AQUELES \nQUE DE JESUS ESTÃO PERTO;\nA MINHA BÍBLIA \nVOU SEMPRE LER, PARA MAIS \nDE JESUS CONHECER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (137, 'NÃO POR FORÇA', 'NÃO POR FORÇA', '''NÃO POR FORÇA NEM \nPOR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.\n''NÃO POR FORÇA NEM \nPOR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.\n\nDIZ O SENHOR DOS EXÉRCITOS,\nDIZ O SENHOR DOS EXÉRCITOS:\n''NÃO POR FORÇA \nNEM POR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.', '''NÃO POR FORÇA NEM \nPOR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.\n''NÃO POR FORÇA NEM \nPOR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.\n\nDIZ O SENHOR DOS EXÉRCITOS,\nDIZ O SENHOR DOS EXÉRCITOS:\n''NÃO POR FORÇA \nNEM POR VIOLÊNCIA,\nMAS PELO MEU ESPÍRITO''.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (138, 'SOU UM SOLDADO DO BOM SALVADOR', 'SOU UM SOLDADO DO BOM SALVADOR', 'SOU UM SOLDADO \nDO BOM SALVADOR,\nPOR JESUS LUTANDO\nCOM FÉ E AMOR.\n\nESPADA SEGURANDO BEM FIRME EM MINHA MÃO,\nA JESUS SEGUINDO, O GRANDE CAPITÃO.\n\nAO CÉU EU VOU MARCHANDO, \nJESUS ME ESPERA LÁ,\nPRA FRENTE EU VOU ANDANDO, \nAO CÉU EU VOU CHEGAR.\nFALANDO: UM, DOIS, TRÊS, QUATRO. \n\nSOU UM SOLDADO \nDO BOM SALVADOR,\nPOR JESUS LUTANDO\nCOM FÉ E AMOR.', 'SOU UM SOLDADO \nDO BOM SALVADOR,\nPOR JESUS LUTANDO\nCOM FÉ E AMOR.\n\nESPADA SEGURANDO BEM FIRME EM MINHA MÃO,\nA JESUS SEGUINDO, O GRANDE CAPITÃO.\n\nAO CÉU EU VOU MARCHANDO, \nJESUS ME ESPERA LÁ,\nPRA FRENTE EU VOU ANDANDO, \nAO CÉU EU VOU CHEGAR.\nFALANDO: UM, DOIS, TRÊS, QUATRO. \n\nSOU UM SOLDADO \nDO BOM SALVADOR,\nPOR JESUS LUTANDO\nCOM FÉ E AMOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (139, 'DONS DO ESPÍRITO SANTO', 'DONS DO ESPÍRITO SANTO', 'DONS DO ESPÍRITO SANTO,\nBÊNÇÃOS QUE ALMEJO TANTO,\nSÃO COMO PEDRAS PRECIOSAS,\nCOMO O PERFUME DAS ROSAS.\n\n\nSABEDORIA, CIÊNCIA, FÉ, \nDONS DE CURAR, E MARAVILHAS, PROFECIA, DISCERNIMENTO, \nLÍNGUAS ESTRANHAS, INTERPRETAÇÃO.\n\nDONS DO ESPÍRITO SANTO,\nBÊNÇÃOS QUE ALMEJO TANTO,\nSÃO COMO PEDRAS PRECIOSAS,\nCOMO O PERFUME DAS ROSAS.\n\nSABEDORIA, CIÊNCIA, FÉ, \nDONS DE CURAR, E MARAVILHAS, PROFECIA, DISCERNIMENTO, \nLÍNGUAS ESTRANHAS, INTERPRETAÇÃO.', 'DONS DO ESPÍRITO SANTO,\nBÊNÇÃOS QUE ALMEJO TANTO,\nSÃO COMO PEDRAS PRECIOSAS,\nCOMO O PERFUME DAS ROSAS.\n\n\nSABEDORIA, CIÊNCIA, FÉ, \nDONS DE CURAR, E MARAVILHAS, PROFECIA, DISCERNIMENTO, \nLÍNGUAS ESTRANHAS, INTERPRETAÇÃO.\n\nDONS DO ESPÍRITO SANTO,\nBÊNÇÃOS QUE ALMEJO TANTO,\nSÃO COMO PEDRAS PRECIOSAS,\nCOMO O PERFUME DAS ROSAS.\n\nSABEDORIA, CIÊNCIA, FÉ, \nDONS DE CURAR, E MARAVILHAS, PROFECIA, DISCERNIMENTO, \nLÍNGUAS ESTRANHAS, INTERPRETAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (140, 'UMA LUZ RESPLANDECENTE', 'UMA LUZ RESPLANDECENTE', 'UMA LUZ RESPLANDECENTE\nHÁ EM VOLTA DO TEU OLHAR,\nTUA FACE RELUZENTE\nVEM HOJE ME MOSTRAR.\n\nSEI QUE UM DIA TU VIRÁS\nE ENTÃO ME LEVARÁS\nANTES MESMO QUE EU PEÇA:\nSENHOR, VEM ME BUSCAR!\n\nSEGURA-ME PELA MÃO\nQUANDO A VIDA ATRAVESSAR,\nSEI QUE TU ESTARÁS COMIGO\nQUANDO O MAL ME ENCONTRAR.', 'UMA LUZ RESPLANDECENTE\nHÁ EM VOLTA DO TEU OLHAR,\nTUA FACE RELUZENTE\nVEM HOJE ME MOSTRAR.\n\nSEI QUE UM DIA TU VIRÁS\nE ENTÃO ME LEVARÁS\nANTES MESMO QUE EU PEÇA:\nSENHOR, VEM ME BUSCAR!\n\nSEGURA-ME PELA MÃO\nQUANDO A VIDA ATRAVESSAR,\nSEI QUE TU ESTARÁS COMIGO\nQUANDO O MAL ME ENCONTRAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (141, 'QUEM IRÁ?', 'QUEM IRÁ?', 'QUEM IRÁ, QUEM IRÁ \nLEVAR A PRECIOSA SEMENTE? \n\nAQUELE QUE LEVA \nA PRECIOSA SEMENTE ANDANDO E CHORANDO\nVOLTARÁ, SIM, COM ALEGRIA,\nTRAZENDO CONSIGO\nOS SEU MOLHOS\n\nEU IREI, SIM IREI,\nLEVAR A PALAVRA DE DEUS.\nEU IREI, SIM IREI,\nLEVAR A PALAVRA DE DEUS.\n\nAQUELE QUE LEVA \nA PRECIOSA SEMENTE ANDANDO E CHORANDO\nVOLTARÁ, SIM, COM ALEGRIA,\nTRAZENDO CONSIGO\nOS SEU MOLHOS', 'QUEM IRÁ, QUEM IRÁ <bis>\nLEVAR A PRECIOSA SEMENTE? <bis>\n\nAQUELE QUE LEVA \nA PRECIOSA SEMENTE ANDANDO E CHORANDO\nVOLTARÁ, SIM, COM ALEGRIA,\nTRAZENDO CONSIGO\nOS SEU MOLHOS\n\nEU IREI, SIM IREI,\nLEVAR A PALAVRA DE DEUS.\nEU IREI, SIM IREI,\nLEVAR A PALAVRA DE DEUS.\n\nAQUELE QUE LEVA \nA PRECIOSA SEMENTE ANDANDO E CHORANDO\nVOLTARÁ, SIM, COM ALEGRIA,\nTRAZENDO CONSIGO\nOS SEU MOLHOS', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (142, 'COMO UMA FOLHA AO VENTO', 'COMO UMA FOLHA AO VENTO', 'COMO UMA FOLHA AO VENTO\nVOA PRA LÁ E PRA CÁ,\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.\n\nNÃO FAÇO MAIS O QUE EU QUERO,\nMAS O QUE DEUS REVELAR;\nCOMO UMA FOLHA AO VENTO,\nVOANDO, VAI SEMPRE ONDE \nO VENTO SOPRAR,\n\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.', 'COMO UMA FOLHA AO VENTO\nVOA PRA LÁ E PRA CÁ,\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.\n\nNÃO FAÇO MAIS O QUE EU QUERO,\nMAS O QUE DEUS REVELAR;\nCOMO UMA FOLHA AO VENTO,\nVOANDO, VAI SEMPRE ONDE \nO VENTO SOPRAR,\n\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.\nEU TAMBÉM QUERO ESTAR\nAONDE O ESPÍRITO SANTO MANDAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (143, 'TENHO UMA CANDEIA (CANDEIA ACESA)', 'TENHO UMA CANDEIA (CANDEIA ACESA)', 'CORO\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE \nJESUS VOLTARÁ;\n\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!\n\nACENDE TUA CANDEIA, \nNÃO A DEIXES APAGAR,\nILUMINANDO O TEU ROSTO \nJESUS TE VERÁ.\n\nCORO\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE JESUS VOLTARÁ;\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!\n\nCANDEIA VAZIA \nEU NÃO QUERO, NÃO,\nCANDEIA CHEIA, \nEU QUERO, SIM,\nCANDEIA COM FOGO \nPRONTA PARA SUBIR. \n\nCANDEIA VAZIA \nEU NÃO QUERO, NÃO,\nCANDEIA CHEIA, \nEU QUERO, SIM,\nCANDEIA COM FOGO \nPRONTA PARA SUBIR. \n\nCORO\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE JESUS VOLTARÁ;\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!', '<coro>\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE \nJESUS VOLTARÁ;\n\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!\n\nACENDE TUA CANDEIA, \nNÃO A DEIXES APAGAR,\nILUMINANDO O TEU ROSTO \nJESUS TE VERÁ.\n\n<coro>\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE JESUS VOLTARÁ;\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!\n\nCANDEIA VAZIA \nEU NÃO QUERO, NÃO,\nCANDEIA CHEIA, \nEU QUERO, SIM,\nCANDEIA COM FOGO \nPRONTA PARA SUBIR. \n\nCANDEIA VAZIA \nEU NÃO QUERO, NÃO,\nCANDEIA CHEIA, \nEU QUERO, SIM,\nCANDEIA COM FOGO \nPRONTA PARA SUBIR. \n\n<coro>\nTENHO UMA CANDEIA, \nDE ÓLEO ESTÁ CHEIA, \nELA ANUNCIA QUE JESUS VOLTARÁ;\nLUZ BRILHANTE, REFULGENTE, \nÉ O GRITO DA IGREJA:\nJESUS VAI VOLTAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (144, 'NOVA ALIANÇA', 'NOVA ALIANÇA', 'NOVA ALIANÇA \nFEZ O MEU SENHOR\nCOM O SEU POVO \nNUM ATO DE AMOR; \n''EIS QUE FAÇO NOVAS \nTODAS AS COISAS'',\nASSIM FALOU O SENHOR.\n\nPREPARO O MEU CORAÇÃO\nPARA O ARREBATAMENTO,\nNÃO SERÁ FÁCIL, LUTAS VIRÃO,\nMAS NA BUSCA AO SENHOR\nELE DARÁ A SOLUÇÃO;\n\nCOM O ESPÍRITO SANTO\nQUER BATIZAR E EXPERIÊNCIAS \nCOM OS DONS QUER DAR,\n\nEU NÃO TEMEREI, \nCOM CRISTO ANDAREI \nNA DIREÇÃO DO ESPÍRITO SANTO.\n\nQUANDO EU CAMINHAR\nCOM MEU JESUS\nVAI RAIAR A LUZ\nE VIDAS SE ENTREGARÃO,\nRECEBENDO A SALVAÇÃO;\n\n\n\nE JUNTOS NUM CORPO UNIDO\nVAMOS RUMO À\nTÃO ESPERADA SIÃO.\nTÃO ESPERADA SIÃO.', 'NOVA ALIANÇA \nFEZ O MEU SENHOR\nCOM O SEU POVO \nNUM ATO DE AMOR; \n''EIS QUE FAÇO NOVAS \nTODAS AS COISAS'',\nASSIM FALOU O SENHOR.\n\nPREPARO O MEU CORAÇÃO\nPARA O ARREBATAMENTO,\nNÃO SERÁ FÁCIL, LUTAS VIRÃO,\nMAS NA BUSCA AO SENHOR\nELE DARÁ A SOLUÇÃO;\n\nCOM O ESPÍRITO SANTO\nQUER BATIZAR E EXPERIÊNCIAS \nCOM OS DONS QUER DAR,\n\nEU NÃO TEMEREI, \nCOM CRISTO ANDAREI \nNA DIREÇÃO DO ESPÍRITO SANTO.\n\nQUANDO EU CAMINHAR\nCOM MEU JESUS\nVAI RAIAR A LUZ\nE VIDAS SE ENTREGARÃO,\nRECEBENDO A SALVAÇÃO;\n\n\n\nE JUNTOS NUM CORPO UNIDO\nVAMOS RUMO À\nTÃO ESPERADA SIÃO.\nTÃO ESPERADA SIÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (145, 'REVELAÇÃO ABRE PRA VOCÊ', 'REVELAÇÃO ABRE PRA VOCÊ', 'REVELAÇÃO ABRE PRA VOCÊ CONHECIMENTO DE DEUS \nE SEU PODER; O ESPÍRITO SANTO \nMOSTRA AO QUE CRÊ\n\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\n\nREVELAÇÃO ABRE PRA VOCÊ CONHECIMENTO DE DEUS E SEU PODER;\nO ESPÍRITO SANTO MOSTRA AO QUE CRÊ\n\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.', 'REVELAÇÃO ABRE PRA VOCÊ CONHECIMENTO DE DEUS \nE SEU PODER; O ESPÍRITO SANTO \nMOSTRA AO QUE CRÊ\n\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\n\nREVELAÇÃO ABRE PRA VOCÊ CONHECIMENTO DE DEUS E SEU PODER;\nO ESPÍRITO SANTO MOSTRA AO QUE CRÊ\n\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.\nCOISAS MARAVILHOSAS QUE O HOMEM SEM DEUS NÃO VÊ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (146, 'A IGREJA QUE ORA É VITORIOSA', 'A IGREJA QUE ORA É VITORIOSA', 'A IGREJA QUE ORA \nÉ VITORIOSA, SEMPRE ESTÁ NA \nDEPENDÊNCIA DO SENHOR;\n\nA IGREJA QUE ORA É VITORIOSA,\nMUITOS MILAGRES ACONTECEM.\nPORQUE É UM CORPO VIVO\nONDE O CABEÇA É JESUS.\nPORQUE É UM CORPO VIVO\nONDE O CABEÇA É JESUS.\n\nSE UMA BÊNÇÃO QUER\nDOBRA OS TEUS JOELHOS,\nCLAMA, ORA, BUSCA SUA FACE;\nORANDO, CANTANDO, VERÁS\nO FRUTO DO ESPÍRITO SANTO.', 'A IGREJA QUE ORA \nÉ VITORIOSA, SEMPRE ESTÁ NA \nDEPENDÊNCIA DO SENHOR;\n\nA IGREJA QUE ORA É VITORIOSA,\nMUITOS MILAGRES ACONTECEM.\nPORQUE É UM CORPO VIVO\nONDE O CABEÇA É JESUS.\nPORQUE É UM CORPO VIVO\nONDE O CABEÇA É JESUS.\n\nSE UMA BÊNÇÃO QUER\nDOBRA OS TEUS JOELHOS,\nCLAMA, ORA, BUSCA SUA FACE;\nORANDO, CANTANDO, VERÁS\nO FRUTO DO ESPÍRITO SANTO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (147, 'EM TUAS PISADAS', 'EM TUAS PISADAS', 'EM TUAS PISADAS \nCOLOCO OS MEUS PÉS, \nASSIM, BEM FIRMADO, \nNÃO VACILAREI;\n\nOS TEUS PRECEITOS, \nSENHOR, OS GUARDEI,\nAS TUAS PALAVRAS \nSÃO MEU ALIMENTO,\nVIVER NA TUA OBRA \nÉ O MEU SUSTENTO. \n\n\nEM TUAS PISADAS \nCOLOCO OS MEUS PÉS, \nASSIM, BEM FIRMADO, \nNÃO VACILAREI;\n\nOS TEUS PRECEITOS, \nSENHOR, OS GUARDEI,\nAS TUAS PALAVRAS \nSÃO MEU ALIMENTO,\nVIVER NA TUA OBRA \nÉ O MEU SUSTENTO.', 'EM TUAS PISADAS \nCOLOCO OS MEUS PÉS, \nASSIM, BEM FIRMADO, \nNÃO VACILAREI;\n\nOS TEUS PRECEITOS, \nSENHOR, OS GUARDEI,\nAS TUAS PALAVRAS \nSÃO MEU ALIMENTO,\nVIVER NA TUA OBRA \nÉ O MEU SUSTENTO. \n\n\nEM TUAS PISADAS \nCOLOCO OS MEUS PÉS, \nASSIM, BEM FIRMADO, \nNÃO VACILAREI;\n\nOS TEUS PRECEITOS, \nSENHOR, OS GUARDEI,\nAS TUAS PALAVRAS \nSÃO MEU ALIMENTO,\nVIVER NA TUA OBRA \nÉ O MEU SUSTENTO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (148, 'ANDANDO EM ESPÍRITO', 'ANDANDO EM ESPÍRITO', 'ANDANDO EM ESPÍRITO \nVENCEREI A TENTAÇÃO, AGRADAREI A DEUS \nEM PERFEITA COMUNHÃO,\n\n''POIS O FRUTO DO ESPÍRITO É: AMOR, GOZO, PAZ, LONGANIMIDADE, BENIGNIDADE, BONDADE, FÉ, MANSIDÃO, TEMPERANÇA''.\n\nVIVENDO EM ESPÍRITO,\nANDANDO EM ESPÍRITO, ASSIM SOMOS SERVOS\nFIÉIS DE CRISTO.', 'ANDANDO EM ESPÍRITO \nVENCEREI A TENTAÇÃO, AGRADAREI A DEUS \nEM PERFEITA COMUNHÃO,\n\n''POIS O FRUTO DO ESPÍRITO É: AMOR, GOZO, PAZ, LONGANIMIDADE, BENIGNIDADE, BONDADE, FÉ, MANSIDÃO, TEMPERANÇA''.\n\nVIVENDO EM ESPÍRITO,<bis>\nANDANDO EM ESPÍRITO, ASSIM SOMOS SERVOS<bis>\nFIÉIS DE CRISTO.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (149, 'NÓS SOMOS UMA VOZ', 'NÓS SOMOS UMA VOZ', 'NÓS SOMOS UMA VOZ\nQUE CLAMA NO DESERTO,\nNESTE MUNDO DE ILUSÕES\nPROCLAMAMOS A MENSAGEM \nDE SALVAÇÃO.\n\nDEUS AMA O QUE SE APRESSA,\nELE AMA O EVANGELISTA,\nAMA AQUELE QUE SE APRESSA\nPRA ANUNCIAR A SALVAÇÃO EM NOME DE JESUS.\n\nNÓS SOMOS UMA VOZ\nQUE CLAMA NO DESERTO,\nNESTE MUNDO DE ILUSÕES\nPROCLAMAMOS A MENSAGEM \nDE SALVAÇÃO.\n\nDEUS AMA O QUE SE APRESSA,\nELE AMA O EVANGELISTA,\nAMA AQUELE QUE SE APRESSA\nPRA ANUNCIAR A SALVAÇÃO EM NOME DE JESUS.', 'NÓS SOMOS UMA VOZ\nQUE CLAMA NO DESERTO,\nNESTE MUNDO DE ILUSÕES\nPROCLAMAMOS A MENSAGEM \nDE SALVAÇÃO.\n\nDEUS AMA O QUE SE APRESSA,\nELE AMA O EVANGELISTA,\nAMA AQUELE QUE SE APRESSA\nPRA ANUNCIAR A SALVAÇÃO EM NOME DE JESUS.\n\nNÓS SOMOS UMA VOZ\nQUE CLAMA NO DESERTO,\nNESTE MUNDO DE ILUSÕES\nPROCLAMAMOS A MENSAGEM \nDE SALVAÇÃO.\n\nDEUS AMA O QUE SE APRESSA,\nELE AMA O EVANGELISTA,\nAMA AQUELE QUE SE APRESSA\nPRA ANUNCIAR A SALVAÇÃO EM NOME DE JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (150, 'CINCO SEIXOS', 'CINCO SEIXOS', 'CINCO SEIXOS DO RIBEIRO \nDAVI COLOCOU\nEM SEU ALFORJE DE PASTOR\nQUANDO GOLIAS \nFOI A ENFRENTAR.\nSEM MEDO DAVI FOI LUTAR.\n\nDAVI OROU, \nCONFIOU EM DEUS,\nPARA ASSIM \nVENCER O FILISTEU.\n\nEM SEU CORAÇÃO HAVIA O LOUVOR,\nA PALAVRA, O JEJUM E A ORAÇÃO\nE NA MADRUGADA, \nSEMPRE A DEUS BUSCAVA\nDEIXANDO O SENHOR \nSUA VIDA DIRIGIR.\n\nE QUANDO GOLIAS FOI ENCONTRAR\nSÓ UMA PEDRA EM SUA FUNDA COLOCOU.\nE MIROU, GIROU, LANÇOU\nNA TESTA DO GIGANTE A PEDRA CRAVOU\n(TRUMMMM)\n\nO GIGANTE CAIU, \nDAVI FOI VENCEDOR.\nNO NOME DO SENHOR, \nNO NOME DO SENHOR.', 'CINCO SEIXOS DO RIBEIRO \nDAVI COLOCOU\nEM SEU ALFORJE DE PASTOR\nQUANDO GOLIAS \nFOI A ENFRENTAR.\nSEM MEDO DAVI FOI LUTAR.\n\nDAVI OROU, \nCONFIOU EM DEUS,\nPARA ASSIM \nVENCER O FILISTEU.\n\nEM SEU CORAÇÃO HAVIA O LOUVOR,\nA PALAVRA, O JEJUM E A ORAÇÃO\nE NA MADRUGADA, \nSEMPRE A DEUS BUSCAVA\nDEIXANDO O SENHOR \nSUA VIDA DIRIGIR.\n\nE QUANDO GOLIAS FOI ENCONTRAR\nSÓ UMA PEDRA EM SUA FUNDA COLOCOU.\nE MIROU, GIROU, LANÇOU\nNA TESTA DO GIGANTE A PEDRA CRAVOU\n(TRUMMMM)\n\nO GIGANTE CAIU, \nDAVI FOI VENCEDOR.\nNO NOME DO SENHOR, \nNO NOME DO SENHOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (151, 'NO PRINCÍPIO ERA O VERBO', 'NO PRINCÍPIO ERA O VERBO', '''NO PRINCÍPIO ERA O VERBO E O VERBO ESTAVA COM DEUS E O VERBO ERA DEUS''.\n\n''TODAS AS COISAS\n FORAM FEITAS POR ELE\n E SEM ELE NADA \n DO QUE FOI FEITO SE FEZ''.\n\nVEIO TOMAR AS NOSSAS DORES,\nCONHECER AS NOSSAS FRAQUEZAS\nE, DIANTE DO PAI, O NOSSO PECADO JUSTIFICAR. \n\nESTE VERBO É A PALAVRA VIVA, \nPROCLAMADA NA ETERNIDADE POR DEUS,\nQUANDO PROMETEU O SEU FILHO PRA MORRER \nEM NOSSO LUGAR.\n\nPOR ISSO TE LOUVAMOS,\nTE ADORAMOS, Ó DEUS!\nPELO SACRIFÍCIO DE JESUS\nTE RENDEMOS GLÓRIA,\n\nTODOS OS DIAS VALORIZAMOS \nESSA IDENTIDADE:\nA MARCA DO SANGUE, \nO ESPÍRITO SANTO, QUE NOS DÁ PLENA COMUNHÃO COM DEUS.\n\nPOR ISSO TE LOUVAMOS,\nTE ADORAMOS, Ó DEUS!\nPELO SACRIFÍCIO DE JESUS\nTE RENDEMOS GLÓRIA,\n\nTODOS OS DIAS VALORIZAMOS \nESSA IDENTIDADE:\nA MARCA DO SANGUE, \nO ESPÍRITO SANTO, QUE NOS DÁ PLENA COMUNHÃO COM DEUS.', '''NO PRINCÍPIO ERA O VERBO E O VERBO ESTAVA COM DEUS E O VERBO ERA DEUS''.\n\n''TODAS AS COISAS\n FORAM FEITAS POR ELE\n E SEM ELE NADA \n DO QUE FOI FEITO SE FEZ''.\n\nVEIO TOMAR AS NOSSAS DORES,\nCONHECER AS NOSSAS FRAQUEZAS\nE, DIANTE DO PAI, O NOSSO PECADO JUSTIFICAR. \n\nESTE VERBO É A PALAVRA VIVA, \nPROCLAMADA NA ETERNIDADE POR DEUS,\nQUANDO PROMETEU O SEU FILHO PRA MORRER \nEM NOSSO LUGAR.\n\nPOR ISSO TE LOUVAMOS,\nTE ADORAMOS, Ó DEUS!\nPELO SACRIFÍCIO DE JESUS\nTE RENDEMOS GLÓRIA,\n\nTODOS OS DIAS VALORIZAMOS \nESSA IDENTIDADE:\nA MARCA DO SANGUE, \nO ESPÍRITO SANTO, QUE NOS DÁ PLENA COMUNHÃO COM DEUS.\n\nPOR ISSO TE LOUVAMOS,\nTE ADORAMOS, Ó DEUS!\nPELO SACRIFÍCIO DE JESUS\nTE RENDEMOS GLÓRIA,\n\nTODOS OS DIAS VALORIZAMOS \nESSA IDENTIDADE:\nA MARCA DO SANGUE, \nO ESPÍRITO SANTO, QUE NOS DÁ PLENA COMUNHÃO COM DEUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (152, 'NAS BATALHAS SOU UM VENCEDOR', 'NAS BATALHAS SOU UM VENCEDOR', 'NAS BATALHAS SOU UM VENCEDOR, \nUSO AS ARMAS ESPIRITUAIS.\nREVESTIDO DE TODA A ARMADURA DE DEUS,\nSEREI FORTALECIDO NO SENHOR.\n\nTENHO CINGIDOS OS LOMBOS \nCOM A VERDADE, E VESTIDA \nA COURAÇA DA JUSTIÇA,\nE CALÇADOS OS PÉS NA PREPARAÇÃO DO EVANGELHO DA PAZ.\n\nTENHO, SOBRETUDO O ESCUDO DA FÉ,\nE TAMBÉM O CAPACETE DA SALVAÇÃO,\nE A ESPADA DO ESPÍRITO, QUE É A PALAVRA DE DEUS.\n\n\nNAS BATALHAS SOU UM VENCEDOR, \nUSO AS ARMAS ESPIRITUAIS. REVESTIDO DE TODA A ARMADURA DE DEUS,\nSEREI FORTALECIDO NO SENHOR, \nE NA FORÇA DO SEU PODER.', 'NAS BATALHAS SOU UM VENCEDOR, \nUSO AS ARMAS ESPIRITUAIS.\nREVESTIDO DE TODA A ARMADURA DE DEUS,\nSEREI FORTALECIDO NO SENHOR.\n\nTENHO CINGIDOS OS LOMBOS \nCOM A VERDADE, E VESTIDA \nA COURAÇA DA JUSTIÇA,\nE CALÇADOS OS PÉS NA PREPARAÇÃO DO EVANGELHO DA PAZ.\n\nTENHO, SOBRETUDO O ESCUDO DA FÉ,\nE TAMBÉM O CAPACETE DA SALVAÇÃO,\nE A ESPADA DO ESPÍRITO, QUE É A PALAVRA DE DEUS.\n\n\nNAS BATALHAS SOU UM VENCEDOR, \nUSO AS ARMAS ESPIRITUAIS. REVESTIDO DE TODA A ARMADURA DE DEUS,\nSEREI FORTALECIDO NO SENHOR, \nE NA FORÇA DO SEU PODER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (153, 'COMO NOÉ', 'COMO NOÉ', 'COMO NOÉ, \nQUERO OBEDECER\nÀ DOCE VOZ DE DEUS,\nA ARCA VOU FAZER;\nCOMO NOÉ NA ARCA VOU ENTRAR\nE SALVAÇÃO VOU ALCANÇAR.\n\nPELA FÉ NOÉ \nEM TUDO OBEDECEU, \nSEGUINDO O PROJETO,\nNADA ELE TEMEU. \nHERDEIRO COM JESUS\nDEUS ASSIM O FEZ, \nPOIS A SALVAÇÃO\nÉ PRA TODO O QUE CRÊ.\n\nHERDEIRO COM JESUS\nDEUS ASSIM O FEZ, \nPOIS A SALVAÇÃO\nÉ PRA TODO O QUE CRÊ.\n\nCOMO NOÉ, \nQUERO OBEDECER\nÀ DOCE VOZ DE DEUS,\nA ARCA VOU FAZER.\nCOMO NOÉ NA ARCA \nVOU ENTRAR E SALVAÇÃO\nVOU ALCANÇAR.', 'COMO NOÉ, \nQUERO OBEDECER\nÀ DOCE VOZ DE DEUS,\nA ARCA VOU FAZER;\nCOMO NOÉ NA ARCA VOU ENTRAR\nE SALVAÇÃO VOU ALCANÇAR.\n\nPELA FÉ NOÉ \nEM TUDO OBEDECEU, \nSEGUINDO O PROJETO,\nNADA ELE TEMEU. \nHERDEIRO COM JESUS\nDEUS ASSIM O FEZ, \nPOIS A SALVAÇÃO\nÉ PRA TODO O QUE CRÊ.\n\nHERDEIRO COM JESUS\nDEUS ASSIM O FEZ, \nPOIS A SALVAÇÃO\nÉ PRA TODO O QUE CRÊ.\n\nCOMO NOÉ, \nQUERO OBEDECER\nÀ DOCE VOZ DE DEUS,\nA ARCA VOU FAZER.\nCOMO NOÉ NA ARCA \nVOU ENTRAR E SALVAÇÃO\nVOU ALCANÇAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (154, 'COM O ESPÍRITO DE DEUS', 'COM O ESPÍRITO DE DEUS', 'CORO\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!\n\nCRISTO PROMETEU \nDEIXAR-NOS O CONSOLADOR\nPARA ESTAR CONOSCO \nSEMPRE ONDE QUER QUE FOR,\n\nO ESPÍRITO DE VERDADE, \nQUE ACONSELHARÁ\nMINHA VIDA, ENSINANDO \nCOMO DEVO ANDAR.\n\nCORO\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!\n\nQUERO SER OBEDIENTE \nAO ESPÍRITO DE DEUS,\nSEGUIR SUA PALAVRA \nE OS ENSINOS SEUS,\nTETEMUNHAR QUE TENHO \nDEUS EM MEU VIVER,\nMINHA VIDA É TRANSFORMADA,\nVOU DIZER PORQUÊ:\n\nCORO\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!', '<coro>\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!\n\nCRISTO PROMETEU \nDEIXAR-NOS O CONSOLADOR\nPARA ESTAR CONOSCO \nSEMPRE ONDE QUER QUE FOR,\n\nO ESPÍRITO DE VERDADE, \nQUE ACONSELHARÁ\nMINHA VIDA, ENSINANDO \nCOMO DEVO ANDAR.\n\n<coro>\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!\n\nQUERO SER OBEDIENTE \nAO ESPÍRITO DE DEUS,\nSEGUIR SUA PALAVRA \nE OS ENSINOS SEUS,\nTETEMUNHAR QUE TENHO \nDEUS EM MEU VIVER,\nMINHA VIDA É TRANSFORMADA,\nVOU DIZER PORQUÊ:\n\n<coro>\nCOM O ESPÍRITO DE DEUS \nEM MINHA VIDA,\nSOU FELIZ, SOU FELIZ!\nTENHO PAZ, CONSOLO, \nGRAÇA E ALEGRIA.\nSOU FELIZ, SIM, SOU FELIZ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (155, 'QUERO ESTAR EM TUA PRESENÇA, Ó DEUS', 'QUERO ESTAR EM TUA PRESENÇA, Ó DEUS', 'QUERO ESTAR EM TUA \nPRESENÇA, Ó DEUS, \nEM TUA OBRA PROSSEGUIR ATÉ O FIM,\nSEM TEMER E SEMPRE CONFIAR QUE JESUS AO MEU LADO ESTÁ.\n\nCORO\nFAZE DE MIM UM VENCEDOR, \nNÃO IMPORTA QUAL SEJA \nA MINHA DOR.\n\nFAZE DE MIM UM ENVIADO TEU,\nPARA A TUA OBRA REALIZAR\nE DO TEU PODER TESTEMUNHAR\nE POR FIM JERUSALÉM ALCANÇAR.\n\nQUERO SER UM SERVO DO SENHOR\nE ANDAR SOB A REVELAÇÃO,\nPARTILHAR DA SUA COMUNHÃO,\nDANDO A ELE SEMPRE \nO MEU CORAÇÃO.\n\nCORO\nFAZE DE MIM UM VENCEDOR, \nNÃO IMPORTA QUAL SEJA \nA MINHA DOR.\n\nFAZE DE MIM UM ENVIADO TEU, \nPARA A TUA OBRA REALIZAR\nE DO TEU PODER TESTEMUNHAR\nE POR FIM JERUSALÉM ALCANÇAR.', 'QUERO ESTAR EM TUA \nPRESENÇA, Ó DEUS, \nEM TUA OBRA PROSSEGUIR ATÉ O FIM,\nSEM TEMER E SEMPRE CONFIAR QUE JESUS AO MEU LADO ESTÁ.\n\n<coro>\nFAZE DE MIM UM VENCEDOR, \nNÃO IMPORTA QUAL SEJA \nA MINHA DOR.\n\nFAZE DE MIM UM ENVIADO TEU,\nPARA A TUA OBRA REALIZAR\nE DO TEU PODER TESTEMUNHAR\nE POR FIM JERUSALÉM ALCANÇAR.\n\nQUERO SER UM SERVO DO SENHOR\nE ANDAR SOB A REVELAÇÃO,\nPARTILHAR DA SUA COMUNHÃO,\nDANDO A ELE SEMPRE \nO MEU CORAÇÃO.\n\n<coro>\nFAZE DE MIM UM VENCEDOR, \nNÃO IMPORTA QUAL SEJA \nA MINHA DOR.\n\nFAZE DE MIM UM ENVIADO TEU, \nPARA A TUA OBRA REALIZAR\nE DO TEU PODER TESTEMUNHAR\nE POR FIM JERUSALÉM ALCANÇAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (156, 'SOMOS CIDADÃOS DO CÉU', 'SOMOS CIDADÃOS DO CÉU', 'SOMOS CIDADÃOS, \nCIDADÃOS DO CÉU.\nSOMOS CIDADÃOS, \nTEMOS SALVAÇÃO.\n\nIDENTIDADE TEMOS, VEIO LÁ DA CRUZ,\nCOM O SACRIFÍCIO DO SENHOR JESUS.\nFALAMOS A VERDADE,\nSEGUIMOS A JUSTIÇA.\nSOMOS CIDADÃOS,\nCIDADÃOS DO CÉU.\n\nTEMOS AS MÃOS LIMPAS,\nUM PURO CORAÇÃO.\nSOMOS CIDADÃOS,\nCIDADÃOS DO CÉU.\nSOMOS CIDADÃOS, \nCIDADÃOS DO CÉU.\nSOMOS CIDADÃOS, \nTEMOS SALVAÇÃO.', 'SOMOS CIDADÃOS, \nCIDADÃOS DO CÉU.\nSOMOS CIDADÃOS, \nTEMOS SALVAÇÃO.\n\nIDENTIDADE TEMOS, VEIO LÁ DA CRUZ,\nCOM O SACRIFÍCIO DO SENHOR JESUS.\nFALAMOS A VERDADE,\nSEGUIMOS A JUSTIÇA.\nSOMOS CIDADÃOS,\nCIDADÃOS DO CÉU.\n\nTEMOS AS MÃOS LIMPAS,\nUM PURO CORAÇÃO.\nSOMOS CIDADÃOS,\nCIDADÃOS DO CÉU.\nSOMOS CIDADÃOS, <bis>\nCIDADÃOS DO CÉU.<bis>\nSOMOS CIDADÃOS, <bis>\nTEMOS SALVAÇÃO.<bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (157, 'ESTE MUNDO NÃO É MEU LUGAR', 'ESTE MUNDO NÃO É MEU LUGAR', 'ESTE MUNDO NÃO \nÉ MEU LUGAR, \nPEREGRINO, ESTOU\nA CAMINHAR.\n\nMAS PARA O CÉU IREI MORAR COM MEU BOM REI,\nJESUS JÁ PREPAROU \nMEU NOVO LAR.\n\nTORNOU-ME CIDADÃO DO CÉU POR SEU AMOR, COM O SEU SANGUE ME COMPROU,\nETERNAMENTE AO SENHOR DAREI LOUVOR, TODA GLÓRIA, HONRA, GRAÇAS E AMOR.\n\nSOU CIDADÃO DO CÉU, A PÁTRIA CELESTIAL, O GRANDE AMOR DE DEUS,\nSUA GRAÇA ETERNAL,\nME CONCEDEU PERDÃO,\nME DEU A SALVAÇÃO,\n\nPOR ISSO SOU CIDADÃO DO CÉU, ALELUIA!\nSOU CIDADÃO DO CÉU, \nALELUIA!\nSOU CIDADÃO DO CÉU!', 'ESTE MUNDO NÃO \nÉ MEU LUGAR, \nPEREGRINO, ESTOU\nA CAMINHAR.\n\nMAS PARA O CÉU IREI MORAR COM MEU BOM REI,\nJESUS JÁ PREPAROU \nMEU NOVO LAR.\n\nTORNOU-ME CIDADÃO DO CÉU POR SEU AMOR, COM O SEU SANGUE ME COMPROU,\nETERNAMENTE AO SENHOR DAREI LOUVOR, TODA GLÓRIA, HONRA, GRAÇAS E AMOR.\n\nSOU CIDADÃO DO CÉU, A PÁTRIA CELESTIAL, O GRANDE AMOR DE DEUS,\nSUA GRAÇA ETERNAL,\nME CONCEDEU PERDÃO,\nME DEU A SALVAÇÃO,\n\nPOR ISSO SOU CIDADÃO DO CÉU, ALELUIA!\nSOU CIDADÃO DO CÉU, \nALELUIA!\nSOU CIDADÃO DO CÉU!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (158, 'NO CAMINHO EU QUERO ESTAR', 'NO CAMINHO EU QUERO ESTAR', 'NO CAMINHO EU QUERO ESTAR, \nAO SENHOR VOU OBEDECER.\nAONDE QUER QUE DEUS \nMANDAR ANUNCIAR O SEU AMOR. ESTOU PRONTO, SENHOR, EU VOU!\n\nTANTAS VIDAS NÃO \nCONHECEM O SENHOR, \nVIVEM TRISTES, TÃO VAZIAS, \nSEM AMOR, PRECISANDO RECEBER \nO SEU PERDÃO, PARA ASSIM ALCANÇAREM A SALVAÇÃO, \n\nQUE JESUS LÁ NO CALVÁRIO REVELOU, \nQUANDO SEU PRECIOSO \nSANGUE DERRAMOU,\nCONCEDENDO VIDA ETERNA AO QUE CRER,\nTRANSFORMANDO SUAS VIDAS, \nQUE PRAZER!\n\nQUE ALEGRIA PODER SERVIR \nA JESUS, NOSSO SALVADOR!\nEM SUA OBRA TRABALHAR, \nATENDENDO AO SEU CHAMAR,\nESTOU PRONTO, \nSENHOR, EU VOU!', 'NO CAMINHO EU QUERO ESTAR, \nAO SENHOR VOU OBEDECER.\nAONDE QUER QUE DEUS \nMANDAR ANUNCIAR O SEU AMOR. ESTOU PRONTO, SENHOR, EU VOU!\n\nTANTAS VIDAS NÃO \nCONHECEM O SENHOR, \nVIVEM TRISTES, TÃO VAZIAS, \nSEM AMOR, PRECISANDO RECEBER \nO SEU PERDÃO, PARA ASSIM ALCANÇAREM A SALVAÇÃO, \n\nQUE JESUS LÁ NO CALVÁRIO REVELOU, \nQUANDO SEU PRECIOSO \nSANGUE DERRAMOU,\nCONCEDENDO VIDA ETERNA AO QUE CRER,\nTRANSFORMANDO SUAS VIDAS, \nQUE PRAZER!\n\nQUE ALEGRIA PODER SERVIR \nA JESUS, NOSSO SALVADOR!\nEM SUA OBRA TRABALHAR, \nATENDENDO AO SEU CHAMAR,\nESTOU PRONTO, \nSENHOR, EU VOU!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (159, 'SERVO DO SENHOR EU SOU', 'SERVO DO SENHOR EU SOU', 'SERVO DO SENHOR EU SOU\nE POSSO OUVIR SUA VOZ.\nSERVO DO SENHOR EU SOU\nE QUERO SERVIR A JESUS.\n\nUMA SÓ VOZ FALA AO MEU CORAÇÃO,\nA VOZ DE JESUS, MEU SENHOR.\nOUÇO A VOZ DO PERFEITO AMOR, \nA VOZ DO MEU BOM SALVADOR. \n\nSE VOCÊ TAMBÉM QUISER,\nPODE OUVIR A JESUS.\nBASTA ABRIR SEU CORAÇÃO\nE DEIXAR ENTRAR SUA LUZ.\n\nE UMA VOZ FALARÁ AO SEU CORAÇÃO,\nA VOZ DE JESUS, O SENHOR.\nSÓ A DOCE VOZ ENCHERÁ SEU CORAÇÃO\nDE PAZ, ALEGRIA E AMOR. \nDE PAZ, ALEGRIA E AMOR.', 'SERVO DO SENHOR EU SOU\nE POSSO OUVIR SUA VOZ.\nSERVO DO SENHOR EU SOU\nE QUERO SERVIR A JESUS.\n\nUMA SÓ VOZ FALA AO MEU CORAÇÃO,\nA VOZ DE JESUS, MEU SENHOR.\nOUÇO A VOZ DO PERFEITO AMOR, \nA VOZ DO MEU BOM SALVADOR. \n\nSE VOCÊ TAMBÉM QUISER,\nPODE OUVIR A JESUS.\nBASTA ABRIR SEU CORAÇÃO\nE DEIXAR ENTRAR SUA LUZ.\n\nE UMA VOZ FALARÁ AO SEU CORAÇÃO,\nA VOZ DE JESUS, O SENHOR.\nSÓ A DOCE VOZ ENCHERÁ SEU CORAÇÃO\nDE PAZ, ALEGRIA E AMOR. \nDE PAZ, ALEGRIA E AMOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (160, 'EXISTEM SEGREDOS NA TUA PALAVRA', 'EXISTEM SEGREDOS NA TUA PALAVRA', 'EXISTEM SEGREDOS \nNA TUA PALAVRA\nQUE SÓ TEU ESPÍRITO \nPODE REVELAR.\n\nENSINOS DE VIDA, \nDE FELICIDADE,\nCAMINHO DE LUZ \nQUE JESUS VEIO NOS DAR.\n\nÉ LIVRO SELADO, \nMISTÉRIO GUARDADO,\nQUE O HOMEM SEM DEUS \nNÃO PODE ALCANÇAR. \n\nÉ LIVRO ABERTO, \nCLARO, DESCOBERTO,\nPARA OS SERVOS FIÉIS \nQUE COM JESUS VÃO REINAR. \nPARA OS SERVOS FIÉIS \nQUE COM JESUS VÃO REINAR.', 'EXISTEM SEGREDOS \nNA TUA PALAVRA\nQUE SÓ TEU ESPÍRITO \nPODE REVELAR.\n\nENSINOS DE VIDA, \nDE FELICIDADE,\nCAMINHO DE LUZ \nQUE JESUS VEIO NOS DAR.\n\nÉ LIVRO SELADO, \nMISTÉRIO GUARDADO,\nQUE O HOMEM SEM DEUS \nNÃO PODE ALCANÇAR. \n\nÉ LIVRO ABERTO, \nCLARO, DESCOBERTO,\nPARA OS SERVOS FIÉIS \nQUE COM JESUS VÃO REINAR. \nPARA OS SERVOS FIÉIS \nQUE COM JESUS VÃO REINAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (161, 'TU ÉS PRA MIM UM VASO ESCOLHIDO', 'TU ÉS PRA MIM UM VASO ESCOLHIDO', 'TU ÉS PRA MIM UM VASO ESCOLHIDO,\nTU ÉS PRA MIM UM VASO DE VALOR.\nEU TE CHAMEI PARA SALVAR TUA VIDA, EU SOU JESUS, O TEU SENHOR.\n\nTU ÉS PRA MIM UM VASO ESCOLHIDO,\nTU ÉS PRA MIM UM VASO DE VALOR.\nPARA LEVAR MEU NOME A TANTAS GENTES\nE TESTEMUNHAR DO MEU AMOR.\n\nCORO\nVAI, FALA E ANUNCIA\nJESUS QUER O HOMEM TRANSFORMAR. \nOS DIAS PASSAM, O TEMPO FINDA,\nJESUS TEM PRESSA E VAI VOLTAR! \n\nCORO\nVAI, FALA E ANUNCIA\nJESUS QUER O HOMEM TRANSFORMAR. \nOS DIAS PASSAM, O TEMPO FINDA,\nJESUS TEM PRESSA E VAI VOLTAR! (2X)', 'TU ÉS PRA MIM UM VASO ESCOLHIDO,\nTU ÉS PRA MIM UM VASO DE VALOR.\nEU TE CHAMEI PARA SALVAR TUA VIDA, EU SOU JESUS, O TEU SENHOR.\n\nTU ÉS PRA MIM UM VASO ESCOLHIDO,\nTU ÉS PRA MIM UM VASO DE VALOR.\nPARA LEVAR MEU NOME A TANTAS GENTES\nE TESTEMUNHAR DO MEU AMOR.\n\n<coro>\nVAI, FALA E ANUNCIA\nJESUS QUER O HOMEM TRANSFORMAR. \nOS DIAS PASSAM, O TEMPO FINDA,\nJESUS TEM PRESSA E VAI VOLTAR! \n\n<coro>\nVAI, FALA E ANUNCIA\nJESUS QUER O HOMEM TRANSFORMAR. \nOS DIAS PASSAM, O TEMPO FINDA,\nJESUS TEM PRESSA E VAI VOLTAR! <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (162, 'ANDAI NA MINHA PRESENÇA', 'ANDAI NA MINHA PRESENÇA', 'CORO (2X)\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.\n\nE VOS LEVAREI A UM LUGAR\nCHEIO DE GOZO E DE PAZ.\nFOME E SEDE JAMAIS TEREIS,\nPOIS COMEREIS DO PÃO DA VIDA.\n\nCORO (2X)\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.\n\nE O MEU ESPÍRITO VOS CONDUZIRÁ \nÀ PÁTRIA CELESTIAL.\nLUTAS E DORES NUNCA MAIS TEREIS, \nPOIS VIVEREIS COM O VOSSO REI.\n\nCORO (2X)\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.', '<coro tipo=''2X''>\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.\n\nE VOS LEVAREI A UM LUGAR\nCHEIO DE GOZO E DE PAZ.\nFOME E SEDE JAMAIS TEREIS,\nPOIS COMEREIS DO PÃO DA VIDA.\n\n<coro tipo=''2X''>\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.\n\nE O MEU ESPÍRITO VOS CONDUZIRÁ \nÀ PÁTRIA CELESTIAL.\nLUTAS E DORES NUNCA MAIS TEREIS, \nPOIS VIVEREIS COM O VOSSO REI.\n\n<coro tipo=''2X''>\nANDAI NA MINHA PRESENÇA, \nANDAI NA MINHA PRESENÇA\nE VOS GUIAREI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (163, 'DÁ-ME UM CORAÇÃO CHEIO DO TEU AMOR', 'DÁ-ME UM CORAÇÃO CHEIO DO TEU AMOR', 'DÁ-ME UM CORAÇÃO\nCHEIO DO TEU AMOR,\nQUE SEMPRE RECONHEÇA\nTUA BONDADE, Ó MEU SENHOR.\n\nUM CORAÇÃO QUE ESTREMEÇA\nAO OUVIR TUA VOZ ASSIM\nE QUE NUNCA SE ESQUEÇA\nO QUE TU FAZES POR MIM.\n\nUM CORAÇÃO OBEDIENTE\nÀ TUA REVELAÇÃO, \nPURO E RENOVADO\nPELA TUA SALVAÇÃO.\n\nÓ SENHOR, AMÉM!', 'DÁ-ME UM CORAÇÃO\nCHEIO DO TEU AMOR,\nQUE SEMPRE RECONHEÇA\nTUA BONDADE, Ó MEU SENHOR.\n\nUM CORAÇÃO QUE ESTREMEÇA\nAO OUVIR TUA VOZ ASSIM\nE QUE NUNCA SE ESQUEÇA\nO QUE TU FAZES POR MIM.\n\nUM CORAÇÃO OBEDIENTE\nÀ TUA REVELAÇÃO, \nPURO E RENOVADO\nPELA TUA SALVAÇÃO.\n\nÓ SENHOR, AMÉM!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (164, 'DÁ-ME UM CORAÇÃO HUMILDE E RETO', 'DÁ-ME UM CORAÇÃO HUMILDE E RETO', 'DÁ-ME UM CORAÇÃO HUMILDE E RETO,\nQUE ATENTE PARA TUA PALAVRA \nE SABEDORIA,PRA QUE EU POSSA \nANDAR EM TUA PRESENÇA.\n\nCORO \nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS.\n\nQUE MINHA CASA ESTEJA FIRMADA EM JESUS,\nROCHA ETERNA, ELE É MEU ABRIGO SEGURO,\nMINHA FORTALEZA, MEU AMIGO FIEL, \nO MEU SALVADOR.\n\nCORO \nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS.\n\nCORO \nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS. (BIS)', 'DÁ-ME UM CORAÇÃO HUMILDE E RETO,\nQUE ATENTE PARA TUA PALAVRA \nE SABEDORIA,PRA QUE EU POSSA \nANDAR EM TUA PRESENÇA.\n\n<coro>\nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS.\n\nQUE MINHA CASA ESTEJA FIRMADA EM JESUS,\nROCHA ETERNA, ELE É MEU ABRIGO SEGURO,\nMINHA FORTALEZA, MEU AMIGO FIEL, \nO MEU SALVADOR.\n\n<coro>\nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS.\n\n<coro>\nQUERO SER OBEDIENTE À TUA VOZ,\nTRABALHAR NA TUA OBRA COM AMOR;\nQUERO IR MORAR PRA SEMPRE NO PALÁCIO \nDO REI DOS REIS, NAS MANSÕES CELESTIAIS. <bis>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (165, 'QUERO SER SANTO PARA O SENHOR', 'QUERO SER SANTO PARA O SENHOR', 'QUERO SER SANTO PARA O SENHOR,\nQUERO SER PURO EM SEU AMOR,\nEM TODO O TEMPO TESTEMUNHAR DE SEU AMOR E GRAÇA SEM PAR.\n\nQUERO LEVAR A MENSAGEM DE SALVAÇÃO\nPARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO \nE QUANDO CRISTO VIER NOS BUSCAR\nPOSSAMOS TODOS NO CÉU IR MORAR.\n\nQUERO SER SANTO PARA O SENHOR,\nQUERO SER PURO EM SEU AMOR,\nEM TODO O TEMPO TESTEMUNHAR DE SEU AMOR E GRAÇA SEM PAR.\n\nQUERO LEVAR A MENSAGEM DE SALVAÇÃO\nPARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO \nE QUANDO CRISTO VIER NOS BUSCAR\nPOSSAMOS TODOS NO CÉU IR MORAR.\n\nQUERO SER SANTO,\nQUERO SER PURO\nPARA O SENHOR!', 'QUERO SER SANTO PARA O SENHOR,\nQUERO SER PURO EM SEU AMOR,\nEM TODO O TEMPO TESTEMUNHAR DE SEU AMOR E GRAÇA SEM PAR.\n\nQUERO LEVAR A MENSAGEM DE SALVAÇÃO\nPARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO \nE QUANDO CRISTO VIER NOS BUSCAR\nPOSSAMOS TODOS NO CÉU IR MORAR.\n\nQUERO SER SANTO PARA O SENHOR,\nQUERO SER PURO EM SEU AMOR,\nEM TODO O TEMPO TESTEMUNHAR DE SEU AMOR E GRAÇA SEM PAR.\n\nQUERO LEVAR A MENSAGEM DE SALVAÇÃO\nPARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO \nE QUANDO CRISTO VIER NOS BUSCAR\nPOSSAMOS TODOS NO CÉU IR MORAR.\n\nQUERO SER SANTO,\nQUERO SER PURO\nPARA O SENHOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (166, 'BRILHANDO, BRILHANDO', 'BRILHANDO, BRILHANDO', 'BRILHANDO, BRILHANDO,\nMINHA CANDEIA SEMPRE \nESTÁ BRILHANDO.\nBRILHANDO, BRILHANDO,\nBRILHANDO ATÉ JESUS VOLTAR.\n\nNÃO FALTARÁ O ÓLEO DO ESPÍRITO,\nMINHA CANDEIA SEMPRE CHEIA FICARÁ,\nPORQUE JESUS NOS DEU SUA PROMESSA\nQUE SEU ESPÍRITO CONOSCO ESTARÁ.\n\nE SE VOCÊ QUISER TAMBÉM BRILHAR,\nÉ SÓ ABRIR SEU CORAÇÃO\nE DEIXAR CRISTO NELE ENTRAR\nE ASSIM VOCÊ SEMPRE ESTARÁ. \n\nBRILHANDO, BRILHANDO,\nMINHA CANDEIA SEMPRE \nESTÁ BRILHANDO.\nBRILHANDO, BRILHANDO,\nBRILHANDO ATÉ JESUS VOLTAR.', 'BRILHANDO, BRILHANDO,\nMINHA CANDEIA SEMPRE \nESTÁ BRILHANDO.\nBRILHANDO, BRILHANDO,\nBRILHANDO ATÉ JESUS VOLTAR.\n\nNÃO FALTARÁ O ÓLEO DO ESPÍRITO,\nMINHA CANDEIA SEMPRE CHEIA FICARÁ,\nPORQUE JESUS NOS DEU SUA PROMESSA\nQUE SEU ESPÍRITO CONOSCO ESTARÁ.\n\nE SE VOCÊ QUISER TAMBÉM BRILHAR,\nÉ SÓ ABRIR SEU CORAÇÃO\nE DEIXAR CRISTO NELE ENTRAR\nE ASSIM VOCÊ SEMPRE ESTARÁ. \n\nBRILHANDO, BRILHANDO,\nMINHA CANDEIA SEMPRE \nESTÁ BRILHANDO.\nBRILHANDO, BRILHANDO,\nBRILHANDO ATÉ JESUS VOLTAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, '167- DANIEL NA COVA DOS LEÕES', '167- DANIEL NA COVA DOS LEÕES', 'DANIEL TRÊS VEZES AO DIA\nBUSCAVA AO SENHOR,\nDE JOELHOS ELE ORAVA\nE GLORIFICAVA A DEUS.\n\nCERTO DIA O ENCONTRARAM ORANDO PROSTRADO AO SEU DEUS, \nSEUS INIMIGOS CONTARAM \nAO REI E PEDIRAM PARA \nQUE CUMPRISSE A LEI.\n\nCORO\nDANIEL NA COVA DOS LEÕES,\nUM ANJO APARECEU.\nDANIEL NA COVA DOS LEÕES,\nO SEU DEUS O PROTEGEU.\n\nINSTRUMENTOS\n\nDANIEL FOI SALVO POR SEU \nDEUS E O REI COMPREENDEU.\nSEUS INIMIGOS FORAM PUNIDOS\nE O REI LOGO DECRETOU\nQUE O DEUS DE DANIEL\nÉ DEUS VIVO E SALVADOR.\n\nCORO\nDANIEL NA COVA DOS LEÕES,\nUM ANJO APARECEU.\nDANIEL NA COVA DOS LEÕES,\nO SEU DEUS O PROTEGEU.', 'DANIEL TRÊS VEZES AO DIA\nBUSCAVA AO SENHOR,\nDE JOELHOS ELE ORAVA\nE GLORIFICAVA A DEUS.\n\nCERTO DIA O ENCONTRARAM ORANDO PROSTRADO AO SEU DEUS, \nSEUS INIMIGOS CONTARAM \nAO REI E PEDIRAM PARA \nQUE CUMPRISSE A LEI.\n\n<coro>\nDANIEL NA COVA DOS LEÕES,\nUM ANJO APARECEU.\nDANIEL NA COVA DOS LEÕES,\nO SEU DEUS O PROTEGEU.\n<instrumentos>\n\n\nDANIEL FOI SALVO POR SEU \nDEUS E O REI COMPREENDEU.\nSEUS INIMIGOS FORAM PUNIDOS\nE O REI LOGO DECRETOU\nQUE O DEUS DE DANIEL\nÉ DEUS VIVO E SALVADOR.\n\n<coro>\nDANIEL NA COVA DOS LEÕES,\nUM ANJO APARECEU.\nDANIEL NA COVA DOS LEÕES,\nO SEU DEUS O PROTEGEU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (168, 'JESUS CHAMA OS SEUS MINISTROS', 'JESUS CHAMA OS SEUS MINISTROS', 'JESUS CHAMA OS SEUS \nMINISTROS PARA UMA \nGRANDE MISSÃO: GUIAR O SEU POVO\nRUMO À BELA SIÃO.\n\nO APÓSTOLO É AQUELE,\nQUE LEVA A PALAVRA DO SENHOR.\nTESTEMUNHA PRA MUITOS POVOS,\nAPRESENTA A OBRA COM AMOR.\n\nO PROFETA APONTA O CAMINHO,\nÉ UM PROCLAMADOR.\nFALA DO QUE ESTÁ POR VIR,\nÉ O INTÉRPRETE DO SENHOR.\n\nPARA O EVANGELISTA\nNÃO HÁ TEMPO RUIM,\nPREGA A PALAVRA \nEM TODOS OS LUGARES\nCOM A AUTORIDADE DE JESUS.\n\nO PASTOR CUIDA DA IGREJA\nGUIANDO O REBANHO À SALVAÇÃO.\nAPASCENTA COM CUIDADO,\nLEVANDO O POVO À ADORAÇÃO!\n\nE O MESTRE É AQUELE,\nO MENOR DOS IRMÃOS,\nENSINA A SÃ DOUTRINA,\nEDUCA COM A REVELAÇÃO.\n\nESTES SÃO OS CINCO MINISTÉRIOS, \nFORMA SIMPLES E PATERNA \nDE JESUS ORIENTAR A SUA IGREJA,\nLEVANDO-A À VIDA ETERNA!\nLEVANDO-A À VIDA ETERNA!', 'JESUS CHAMA OS SEUS \nMINISTROS PARA UMA \nGRANDE MISSÃO: GUIAR O SEU POVO\nRUMO À BELA SIÃO.\n\nO APÓSTOLO É AQUELE,\nQUE LEVA A PALAVRA DO SENHOR.\nTESTEMUNHA PRA MUITOS POVOS,\nAPRESENTA A OBRA COM AMOR.\n\nO PROFETA APONTA O CAMINHO,\nÉ UM PROCLAMADOR.\nFALA DO QUE ESTÁ POR VIR,\nÉ O INTÉRPRETE DO SENHOR.\n\nPARA O EVANGELISTA\nNÃO HÁ TEMPO RUIM,\nPREGA A PALAVRA \nEM TODOS OS LUGARES\nCOM A AUTORIDADE DE JESUS.\n\nO PASTOR CUIDA DA IGREJA\nGUIANDO O REBANHO À SALVAÇÃO.\nAPASCENTA COM CUIDADO,\nLEVANDO O POVO À ADORAÇÃO!\n\nE O MESTRE É AQUELE,\nO MENOR DOS IRMÃOS,\nENSINA A SÃ DOUTRINA,\nEDUCA COM A REVELAÇÃO.\n\nESTES SÃO OS CINCO MINISTÉRIOS, \nFORMA SIMPLES E PATERNA \nDE JESUS ORIENTAR A SUA IGREJA,\nLEVANDO-A À VIDA ETERNA!\nLEVANDO-A À VIDA ETERNA!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (169, 'SETE CARTAS', 'SETE CARTAS', 'SETE CARTAS JOÃO ESCREVEU, AO ANJO DAS IGREJAS DEUS MANDOU,\n''CONHEÇO AS TUAS OBRAS'', \nASSIM DIZ O SENHOR,\n''QUEM TEM OUVIDOS OUÇA \n A VOZ DO MEU ESPÍRITO''.\n\nÉFESO, ESMIRNA,\nPÉRGAMO, TIATIRA,\nSARDES, FILADÉLFIA \nE LAODICÉIA.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.\n\nINSTRUMENTOS\n\nSETE CARTAS JOÃO \nESCREVEU, AO ANJO DAS IGREJAS DEUS MANDOU,\n''CONHEÇO AS TUAS OBRAS'', \nASSIM DIZ O SENHOR,\n''QUEM TEM OUVIDOS OUÇA \n A VOZ DO MEU ESPÍRITO''.\n\nÉFESO, ESMIRNA,\nPÉRGAMO, TIATIRA,\nSARDES, FILADÉLFIA \nE LAODICÉIA.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.', 'SETE CARTAS JOÃO ESCREVEU, AO ANJO DAS IGREJAS DEUS MANDOU,\n''CONHEÇO AS TUAS OBRAS'', \nASSIM DIZ O SENHOR,\n''QUEM TEM OUVIDOS OUÇA \n A VOZ DO MEU ESPÍRITO''.\n\nÉFESO, ESMIRNA,\nPÉRGAMO, TIATIRA,\nSARDES, FILADÉLFIA \nE LAODICÉIA.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.\n<instrumentos>\n\n\nSETE CARTAS JOÃO \nESCREVEU, AO ANJO DAS IGREJAS DEUS MANDOU,\n''CONHEÇO AS TUAS OBRAS'', \nASSIM DIZ O SENHOR,\n''QUEM TEM OUVIDOS OUÇA \n A VOZ DO MEU ESPÍRITO''.\n\nÉFESO, ESMIRNA,\nPÉRGAMO, TIATIRA,\nSARDES, FILADÉLFIA \nE LAODICÉIA.\n\nSÃO SETE CARTAS, SETE IGREJAS,\nSETE ESPÍRITOS DE DEUS \nA FALAR NO MEIO DAS IGREJAS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (170, 'NÓS SOMOS A CARTA DE CRISTO', 'NÓS SOMOS A CARTA DE CRISTO', 'NÓS SOMOS A CARTA DE CRISTO,\nA CARTA VIVA DE DEUS,\nPARA SER LIDA POR TODOS,\nREVELAR OS PROPÓSITOS DE DEUS.\n\nO QUE COMUNICA ESSA CARTA?\nO AMOR, O PERDÃO DE JESUS,\nAS PROMESSAS DE VIDA ETERNA\nNO CAMINHO QUE ELE NOS CONDUZ.\n\nNÃO FOI ESCRITA NA PEDRA, MAS NAS TÁBUAS DO CORAÇÃO. E QUEM ESCREVEU ESSA CARTA FOI O ESPÍRITO SANTO DE DEUS.\n\nNÓS SOMOS A CARTA DE CRISTO,\nA CARTA VIVA DE DEUS\nTESTEMUNHANDO A TODOS\nPRA SALVAR-NOS JESUS MORREU.', 'NÓS SOMOS A CARTA DE CRISTO,\nA CARTA VIVA DE DEUS,\nPARA SER LIDA POR TODOS,\nREVELAR OS PROPÓSITOS DE DEUS.\n\nO QUE COMUNICA ESSA CARTA?\nO AMOR, O PERDÃO DE JESUS,\nAS PROMESSAS DE VIDA ETERNA\nNO CAMINHO QUE ELE NOS CONDUZ.\n\nNÃO FOI ESCRITA NA PEDRA, MAS NAS TÁBUAS DO CORAÇÃO. E QUEM ESCREVEU ESSA CARTA FOI O ESPÍRITO SANTO DE DEUS.\n\nNÓS SOMOS A CARTA DE CRISTO,\nA CARTA VIVA DE DEUS\nTESTEMUNHANDO A TODOS\nPRA SALVAR-NOS JESUS MORREU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (171, 'SOU O SANTO', 'SOU O SANTO', 'SOU O SANTO O VERDADEIRO, \nTENHO A CHAVE DE DAVI; \nA PORTA ABERTA ESTÁ, \nPRA QUE POSSAS ME ADORAR! \n\nGUARDASTE AS MINHAS PALAVRAS,\nNÃO NEGASTE O MEU NOME;\nTAMBÉM EU TE GUARDAREI,\nEIS QUE VENHO SEM DEMORA.\n\nENTÃO, GUARDA O QUE TENS, \nPARA QUE NINGUÉM\nTOME A TUA COROA.', 'SOU O SANTO O VERDADEIRO, \nTENHO A CHAVE DE DAVI; \nA PORTA ABERTA ESTÁ, \nPRA QUE POSSAS ME ADORAR! \n\nGUARDASTE AS MINHAS PALAVRAS,\nNÃO NEGASTE O MEU NOME;\nTAMBÉM EU TE GUARDAREI,\nEIS QUE VENHO SEM DEMORA.\n\nENTÃO, GUARDA O QUE TENS, \nPARA QUE NINGUÉM\nTOME A TUA COROA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (172, 'QUATRO COISAS TÃO PEQUENINAS', 'QUATRO COISAS TÃO PEQUENINAS', 'QUATRO COISAS TÃO PEQUENINAS \nUMA GRANDE LIÇÃO NOS DÃO: \nEMBORA TÃO FRÁGEIS,\nMUITO SÁBIAS SÃO.\n\nAS FORMIGAS SÃO TRABALHADORAS, \nCADA UMA EXERCE A SUA FUNÇÃO;\nÉ COMO A IGREJA DE CRISTO, \nTRABALHANDO PRA \nMANTER A SALVAÇÃO.\n\nEM SEGURANÇA O COELHO CONSTRÓI \nSUA CASA SOBRE A ROCHA;\nE, PARA ESTARMOS BEM SEGUROS,\nCONSTRUÍMOS NA ROCHA QUE É JESUS. \n\nOS GAFANHOTOS TODOS SAEM, \nE EM GRUPOS SE REPARTEM,\nSAÍMOS PROCLAMANDO A PALAVRA, \nSEMPRE UNIDOS, EM UM SÓ CORAÇÃO.\n\nE, NO FINAL DA CAMINHADA,\nHERDEIROS DAS PROMESSAS DE DEUS,\nTAL QUAL A ARANHA MORA NO PALÁCIO, \nMORAREMOS NAS MANSÕES COM JESUS!', 'QUATRO COISAS TÃO PEQUENINAS \nUMA GRANDE LIÇÃO NOS DÃO: \nEMBORA TÃO FRÁGEIS,\nMUITO SÁBIAS SÃO.\n\nAS FORMIGAS SÃO TRABALHADORAS, \nCADA UMA EXERCE A SUA FUNÇÃO;\nÉ COMO A IGREJA DE CRISTO, \nTRABALHANDO PRA \nMANTER A SALVAÇÃO.\n\nEM SEGURANÇA O COELHO CONSTRÓI \nSUA CASA SOBRE A ROCHA;\nE, PARA ESTARMOS BEM SEGUROS,\nCONSTRUÍMOS NA ROCHA QUE É JESUS. \n\nOS GAFANHOTOS TODOS SAEM, \nE EM GRUPOS SE REPARTEM,\nSAÍMOS PROCLAMANDO A PALAVRA, \nSEMPRE UNIDOS, EM UM SÓ CORAÇÃO.\n\nE, NO FINAL DA CAMINHADA,\nHERDEIROS DAS PROMESSAS DE DEUS,\nTAL QUAL A ARANHA MORA NO PALÁCIO, \nMORAREMOS NAS MANSÕES COM JESUS!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (173, 'OUÇO O CLAMOR DO BOM PASTOR', 'OUÇO O CLAMOR DO BOM PASTOR', 'OUÇO O CLAMOR DO BOM PASTOR\nPELO DESERTO ASSOLADOR,\nSEUS CORDEIRINHOS A CHAMAR,\nMUI DESEJOSO DE OS SALVAR.\n\nCORO\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.\n\nQUEM NÃO DESEJA TRABALHAR\nE OS CORDEIRINHOS SEUS BUSCAR\nE ENCAMINHÁ-LOS A JESUS,\nFONTE DE VIDA, AMOR E LUZ?\n\nCORO\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.\n\nPELOS DESERTOS A SOFRER,\nOUVE OS SEUS GRITOS AO MORRER E O MESTRE CLAMA:\n''VAI BUSCAR!'' PRA QUE OS POSSA, ENTÃO, SALVAR.\n\nCORO\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.', 'OUÇO O CLAMOR DO BOM PASTOR\nPELO DESERTO ASSOLADOR,\nSEUS CORDEIRINHOS A CHAMAR,\nMUI DESEJOSO DE OS SALVAR.\n\n<coro>\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.\n\nQUEM NÃO DESEJA TRABALHAR\nE OS CORDEIRINHOS SEUS BUSCAR\nE ENCAMINHÁ-LOS A JESUS,\nFONTE DE VIDA, AMOR E LUZ?\n\n<coro>\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.\n\nPELOS DESERTOS A SOFRER,\nOUVE OS SEUS GRITOS AO MORRER E O MESTRE CLAMA:\n''VAI BUSCAR!'' PRA QUE OS POSSA, ENTÃO, SALVAR.\n\n<coro>\nVAI BUSCAR, VAI BUSCAR!\nVAI BUSCAR MEUS CORDEIRINHOS, VAI! VAI BUSCAR, VAI BUSCAR!\nTRAZE-OS PARA O MEU APRISCO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (174, 'A TUA PALAVRA É SEMENTE', 'A TUA PALAVRA É SEMENTE', 'A TUA PALAVRA É SEMENTE\nE TU ÉS O SEMEADOR,\nO MEU CORAÇÃO É A TERRA\nQUE TU SEMEASTE, SENHOR.\n\nCORO\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA, SENHOR;\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA É AMOR.\n\nMEDITANDO EU CERTO DIA\nNA TUA PALAVRA, SENHOR,\nSENTI QUE DO ALTO DESCIA\nA GRAÇA DO CONSOLADOR.\n\nCORO\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA, SENHOR;\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA É AMOR.', 'A TUA PALAVRA É SEMENTE\nE TU ÉS O SEMEADOR,\nO MEU CORAÇÃO É A TERRA\nQUE TU SEMEASTE, SENHOR.\n\n<coro>\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA, SENHOR;\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA É AMOR.\n\nMEDITANDO EU CERTO DIA\nNA TUA PALAVRA, SENHOR,\nSENTI QUE DO ALTO DESCIA\nA GRAÇA DO CONSOLADOR.\n\n<coro>\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA, SENHOR;\nA TUA PALAVRA, A TUA PALAVRA,\nA TUA PALAVRA É AMOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (175, 'UM CERTO PASTORZINHO', 'UM CERTO PASTORZINHO', 'UM CERTO PASTORZINHO,\nQUE SE CHAMOU DAVI,\nERA MUI PEQUENO, NÃO CONFIAVA EM SI;\nELE, COM OUSADIA, ORANDO SEMPRE A DEUS,\nFOI ENFRENTAR, UM DIA, O HERÓI DOS FILISTEUS.\n\nNA FUNDA UMA PEDRA COLOCOU, \nE GIROU, GIROU, GIROU; \nNA FUNDA UMA PEDRA COLOCOU, \nE GIROU, GIROU, GIROU; \n\nMAIS UMA VEZ, MAIS OUTRA VEZ,\nMAIS UMA VEZ GIROU, \nE A PEDRA ATIROU, \nO ALVO ACERTOU, E O GIGANTE \nAO CHÃO TOMBOU!', 'UM CERTO PASTORZINHO,\nQUE SE CHAMOU DAVI,\nERA MUI PEQUENO, NÃO CONFIAVA EM SI;\nELE, COM OUSADIA, ORANDO SEMPRE A DEUS,\nFOI ENFRENTAR, UM DIA, O HERÓI DOS FILISTEUS.\n\nNA FUNDA UMA PEDRA COLOCOU, \nE GIROU, GIROU, GIROU; \nNA FUNDA UMA PEDRA COLOCOU, \nE GIROU, GIROU, GIROU; \n\nMAIS UMA VEZ, MAIS OUTRA VEZ,\nMAIS UMA VEZ GIROU, \nE A PEDRA ATIROU, \nO ALVO ACERTOU, E O GIGANTE \nAO CHÃO TOMBOU!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (176, 'CRIA EM MIM, Ó DEUS', 'CRIA EM MIM, Ó DEUS', 'CRIA EM MIM, Ó DEUS,\nUM CORAÇÃO PURO \nE RENOVA DENTRO EM MIM \nUM ESPÍRITO RETO.\n\nE RENOVA DENTRO EM MIM\nUM ESPÍRITO RETO.', 'CRIA EM MIM, Ó DEUS,\nUM CORAÇÃO PURO \nE RENOVA DENTRO EM MIM \nUM ESPÍRITO RETO.\n\nE RENOVA DENTRO EM MIM\nUM ESPÍRITO RETO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (177, 'FALA AO MEU CORAÇÃO, JESUS', 'FALA AO MEU CORAÇÃO, JESUS', 'FALA AO MEU\nCORAÇÃO, JESUS! \nFALA AO MEU CORAÇÃO, JESUS!\n\nFALA, FALA, FALA, \nFALA AO MEU CORAÇÃO. \n\nVIVE EM MEU \nCORAÇÃO, JESUS!\nVIVE EM MEU \nCORAÇÃO, JESUS! \n\nVIVE, VIVE, VIVE, \nVIVE EM MEU CORAÇÃO.\n\nREINA EM MEU CORAÇÃO, JESUS!\nREINA EM MEU CORAÇÃO, JESUS!\n\nFALA, VIVE, REINA, \nREINA EM MEU CORAÇÃO.', 'FALA AO MEU\nCORAÇÃO, JESUS! \nFALA AO MEU CORAÇÃO, JESUS!\n\nFALA, FALA, FALA, \nFALA AO MEU CORAÇÃO. \n\nVIVE EM MEU \nCORAÇÃO, JESUS!\nVIVE EM MEU \nCORAÇÃO, JESUS! \n\nVIVE, VIVE, VIVE, \nVIVE EM MEU CORAÇÃO.\n\nREINA EM MEU CORAÇÃO, JESUS!\nREINA EM MEU CORAÇÃO, JESUS!\n\nFALA, VIVE, REINA, \nREINA EM MEU CORAÇÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (178, 'DISSE JESUS AOS JUDEUS (EU TRABALHO TAMBÉM)', 'DISSE JESUS AOS JUDEUS (EU TRABALHO TAMBÉM)', 'DISSE JESUS AOS JUDEUS,\nASSIM JESUS LHES RESPONDEU:\n''O MEU PAI TRABALHA ATÉ AGORA,\nEU TRABALHO TAMBÉM!\n\nEU TRABALHO TAMBÉM,\nEU TRABALHO TAMBÉM,\nO MEU PAI TRABALHA ATÉ AGORA,\nE EU TRABALHO TAMBÉM!''\n\nCONVÉM QUE EU FAÇA AS MESMAS OBRAS\nDAQUELE QUE ME ENVIOU,\nENQUANTO É DIA, A NOITE VEM QUANDO NÃO SE PODE TRABALHAR.\nO MEU PAI TRABALHA ATÉ AGORA, \nEU TRABALHO TAMBÉM!\n\nQUERO TRABALHAR TAMBÉM,\nQUERO TRABALHAR TAMBÉM,\nCOM O ESPÍRITO SANTO EM MINHA VIDA,\nQUERO TRABALHAR TAMBÉM!', 'DISSE JESUS AOS JUDEUS,\nASSIM JESUS LHES RESPONDEU:\n''O MEU PAI TRABALHA ATÉ AGORA,\nEU TRABALHO TAMBÉM!\n\nEU TRABALHO TAMBÉM,\nEU TRABALHO TAMBÉM,\nO MEU PAI TRABALHA ATÉ AGORA,\nE EU TRABALHO TAMBÉM!''\n\nCONVÉM QUE EU FAÇA AS MESMAS OBRAS\nDAQUELE QUE ME ENVIOU,\nENQUANTO É DIA, A NOITE VEM QUANDO NÃO SE PODE TRABALHAR.\nO MEU PAI TRABALHA ATÉ AGORA, \nEU TRABALHO TAMBÉM!\n\nQUERO TRABALHAR TAMBÉM,\nQUERO TRABALHAR TAMBÉM,\nCOM O ESPÍRITO SANTO EM MINHA VIDA,\nQUERO TRABALHAR TAMBÉM!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (179, 'ORAR FAZ BEM', 'ORAR FAZ BEM', 'ORAR FAZ BEM! \nORAR FAZ BEM!\nFAZ BEM À ALMA,\nFAZ BEM AO CORAÇÃO,\nALEGRA A ALMA,\nALEGRA O CORAÇÃO!\n\nORAR FAZ BEM! \nORAR FAZ BEM! \nO NOSSO DEUS RESPONDE,\nRETIRA A AFLIÇÃO!\nO NOSSO DEUS RESPONDE,\nCONFORTA O CORAÇÃO!', 'ORAR FAZ BEM! \nORAR FAZ BEM!\nFAZ BEM À ALMA,\nFAZ BEM AO CORAÇÃO,\nALEGRA A ALMA,\nALEGRA O CORAÇÃO!\n\nORAR FAZ BEM! \nORAR FAZ BEM! \nO NOSSO DEUS RESPONDE,\nRETIRA A AFLIÇÃO!\nO NOSSO DEUS RESPONDE,\nCONFORTA O CORAÇÃO!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (180, 'QUERO SER FIEL (JESUS ESTÁ VIVO)', 'QUERO SER FIEL (JESUS ESTÁ VIVO)', 'QUERO SER FIEL A TI, JESUS.\nFAZER SEMPRE A TUA VONTADE.\nGUARDAR A TUA PALAVRA,\nQUE É LUZ E VIDA \nPARA O MEU CAMINHO. \n\nCORO\nSER FIEL, SER FIEL, \nSER FIEL ATÉ O FIM.\nSER FIEL, SER FIEL \nATÉ MEU JESUS VOLTAR!\n\nQUERO ANDAR \nNA TUA LUZ, SENHOR,\nSÓ ASSIM ESTOU SEGURO;\nQUERO PROCLAMAR EM ALTA VOZ: ''JESUS RESSUSCITOU AO TERCEIRO DIA,\nESTÁ VIVO E REINA EM MEU VIVER''.\n\nCORO\nSER FIEL, SER FIEL, \nSER FIEL ATÉ O FIM.\nSER FIEL, SER FIEL \nATÉ MEU JESUS VOLTAR!\n\nJESUS ESTÁ VIVO, \nREINA EM MEU VIVER,\nE EM BREVE VOLTARÁ!', 'QUERO SER FIEL A TI, JESUS.\nFAZER SEMPRE A TUA VONTADE.\nGUARDAR A TUA PALAVRA,\nQUE É LUZ E VIDA \nPARA O MEU CAMINHO. \n\n<coro>\nSER FIEL, SER FIEL, \nSER FIEL ATÉ O FIM.\nSER FIEL, SER FIEL \nATÉ MEU JESUS VOLTAR!\n\nQUERO ANDAR \nNA TUA LUZ, SENHOR,\nSÓ ASSIM ESTOU SEGURO;\nQUERO PROCLAMAR EM ALTA VOZ: ''JESUS RESSUSCITOU AO TERCEIRO DIA,\nESTÁ VIVO E REINA EM MEU VIVER''.\n\n<coro>\nSER FIEL, SER FIEL, \nSER FIEL ATÉ O FIM.\nSER FIEL, SER FIEL \nATÉ MEU JESUS VOLTAR!\n\nJESUS ESTÁ VIVO, \nREINA EM MEU VIVER,\nE EM BREVE VOLTARÁ!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (181, 'JERUSALÉM, CIDADE DO MEU REI', 'JERUSALÉM, CIDADE DO MEU REI', 'JERUSALÉM, CIDADE DO MEU REI,\nA CADA DIA ANSEIO ESTAR ALI; CONTEMPLAREI A FACE DO SENHOR,\nAQUELE QUE ENTREGOU\nSUA VIDA POR MIM.\n\nJAMAIS A MORTE VEREI\nPOIS VIDA ETERNA ALCANCEI\nQUANDO ENTREGUEI\nMEU CORAÇÃO PARA JESUS.', 'JERUSALÉM, CIDADE DO MEU REI,\nA CADA DIA ANSEIO ESTAR ALI; CONTEMPLAREI A FACE DO SENHOR,\nAQUELE QUE ENTREGOU\nSUA VIDA POR MIM.\n\nJAMAIS A MORTE VEREI\nPOIS VIDA ETERNA ALCANCEI\nQUANDO ENTREGUEI\nMEU CORAÇÃO PARA JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (182, 'QUERO VIVER PARA SEMPRE COM JESUS', 'QUERO VIVER PARA SEMPRE COM JESUS', 'CORO\nQUERO VIVER PARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \n\nQUERO COMER \nDA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER!\n\nVOU VIVER, SIM, VOU VIVER,\nPASSEAR NO JARDIM DO MEU SENHOR; A ÁRVORE DA VIDA NO MEIO DO JARDIM\nÉ CERTEZA QUE JESUS ME PROMETEU.\n\nCORO\nQUERO VIVER \nPARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \nQUERO COMER DA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER! \n\nPARA TRÁS O PECADO FICARÁ, \nSEU DOMÍNIO NÃO ME ATINGIRÁ; \nESCOLHI MUITO BEM: VIVER ETERNAMENTE COM JESUS! \n\nCORO\nQUERO VIVER \nPARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \nQUERO COMER DA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER!', '<coro>\nQUERO VIVER PARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \n\nQUERO COMER \nDA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER!\n\nVOU VIVER, SIM, VOU VIVER,\nPASSEAR NO JARDIM DO MEU SENHOR; A ÁRVORE DA VIDA NO MEIO DO JARDIM\nÉ CERTEZA QUE JESUS ME PROMETEU.\n\n<coro>\nQUERO VIVER \nPARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \nQUERO COMER DA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER! \n\nPARA TRÁS O PECADO FICARÁ, \nSEU DOMÍNIO NÃO ME ATINGIRÁ; \nESCOLHI MUITO BEM: VIVER ETERNAMENTE COM JESUS! \n\n<coro>\nQUERO VIVER \nPARA SEMPRE COM JESUS, QUERO BEBER DA ÁGUA DA VIDA, \nQUERO COMER DA ÁRVORE DA VIDA, \nCOM JESUS ETERNAMENTE \nVOU VIVER!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (183, 'UM NOVO CÉU, UMA NOVA TERRA SE FARÁ', 'UM NOVO CÉU, UMA NOVA TERRA SE FARÁ', 'UM NOVO CÉU, \nUMA NOVA TERRA SE FARÁ,\nNOVO NOME NUMA \nPEDRA BRANCA RECEBEREI,\n\nNA CIDADE DE LUZ ETERNA IREI MORAR PARA SEMPRE COM O SALVADOR;\nRUAS DE OURO ANDAREI,\nRIO DA VIDA CONTEMPLAREI\n\nE MUITO LOUVOR ALI ENTOAREI,\nNÃO HAVERÁ DOR, \nPRANTO OU CLAMOR,\nTODA LÁGRIMA JESUS \nVAI ENXUGAR.\n\nNÓS SEREMOS O SEU \nPOVO ETERNAMENTE\nE DEUS NOSSO TABERNÁCULO \nPARA SEMPRE;\n\nSE VOCÊ QUISER VIR A CRISTO,\nABRA AGORA O SEU CORAÇÃO\nE DEIXA JESUS FAZER DA SUA VIDA\nMORADA ETERNA DE DEUS.', 'UM NOVO CÉU, \nUMA NOVA TERRA SE FARÁ,\nNOVO NOME NUMA \nPEDRA BRANCA RECEBEREI,\n\nNA CIDADE DE LUZ ETERNA IREI MORAR PARA SEMPRE COM O SALVADOR;\nRUAS DE OURO ANDAREI,\nRIO DA VIDA CONTEMPLAREI\n\nE MUITO LOUVOR ALI ENTOAREI,\nNÃO HAVERÁ DOR, \nPRANTO OU CLAMOR,\nTODA LÁGRIMA JESUS \nVAI ENXUGAR.\n\nNÓS SEREMOS O SEU \nPOVO ETERNAMENTE\nE DEUS NOSSO TABERNÁCULO \nPARA SEMPRE;\n\nSE VOCÊ QUISER VIR A CRISTO,\nABRA AGORA O SEU CORAÇÃO\nE DEIXA JESUS FAZER DA SUA VIDA\nMORADA ETERNA DE DEUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (184, 'NO EXPRESSO VIAJAMOS', 'NO EXPRESSO VIAJAMOS', 'NO EXPRESSO VIAJAMOS PARA O BOM PAÍS DA LUZ,\nÉ O NOSSO PASSAPORTE \nO NOME DE JESUS; \n\nÉ HORA DA PARTIDA \nE ENSEJO AINDA TÊM\nAQUELES QUE QUISEREM TER PASSAGEM NESSE TREM. \n\nBEM-VINDOS SEJAM TODOS\nPARA O TREM QUE PARTE JÁ,\nENTRADA PARA A PÁTRIA \nJESUS A TODOS DÁ; \nEIS O SINAL DE MARCHA, \nSE QUERES IR TAMBÉM,\nRECEBE O TEU BILHETE \nDE PASSAGEM NESSE TREM.', 'NO EXPRESSO VIAJAMOS PARA O BOM PAÍS DA LUZ,\nÉ O NOSSO PASSAPORTE \nO NOME DE JESUS; \n\nÉ HORA DA PARTIDA \nE ENSEJO AINDA TÊM\nAQUELES QUE QUISEREM TER PASSAGEM NESSE TREM. \n\nBEM-VINDOS SEJAM TODOS\nPARA O TREM QUE PARTE JÁ,\nENTRADA PARA A PÁTRIA \nJESUS A TODOS DÁ; \nEIS O SINAL DE MARCHA, \nSE QUERES IR TAMBÉM,\nRECEBE O TEU BILHETE \nDE PASSAGEM NESSE TREM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (185, 'HÁ UMA LINDA MORADA', 'HÁ UMA LINDA MORADA', 'HÁ UMA LINDA MORADA \nPRA MIM NO CÉU\nQUE JESUS FOI ALI PREPARAR;\nUM LUGAR DE DELÍCIAS \nE AMOR SEM FIM,\nCOM JESUS VOU \nPRA SEMPRE MORAR.\n\nNA CIDADE DE DEUS, \nNOVA JERUSALÉM,\nONDE O SOL \nNÃO PRECISA BRILHAR;\nO CORDEIRO É A LUZ \nQUE ILUMINA A CIDADE\nONDE VOU PARA \nSEMPRE MORAR.', 'HÁ UMA LINDA MORADA \nPRA MIM NO CÉU\nQUE JESUS FOI ALI PREPARAR;\nUM LUGAR DE DELÍCIAS \nE AMOR SEM FIM,\nCOM JESUS VOU \nPRA SEMPRE MORAR.\n\nNA CIDADE DE DEUS, \nNOVA JERUSALÉM,\nONDE O SOL \nNÃO PRECISA BRILHAR;\nO CORDEIRO É A LUZ \nQUE ILUMINA A CIDADE\nONDE VOU PARA \nSEMPRE MORAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (186, 'NOSSAS VIDAS SÃO MUDADAS', 'NOSSAS VIDAS SÃO MUDADAS', 'NOSSAS VIDAS SÃO MUDADAS\nPARA ANDARMOS MUI FELIZES,\nQUANDO OUVIMOS A PALAVRA,\nDO NOSSO AMIGO E JUIZ.\n\nELE JULGA A NOSSA CAUSA\nE APAGA A TRANSGRESSÃO,\nDE TODO MAL SOMOS GUARDADOS, \nCAMINHAMOS EM SUA LUZ.\n\nLUZ QUE BRILHA A CADA INSTANTE \nPARA SERMOS IDENTIFICADOS,\nNAQUELE GRANDE DIA,\nE POR JESUS ARREBATADOS.\n\nMARANATA! É O NOSSO GRITO,\nMARANATA! VEM, JESUS!\nEM BREVE A TROMBETA SOARÁ, \nNO CÉU COM ELE QUERO ESTAR.\n\nMARANATA! É O NOSSO GRITO,\nMARANATA! VEM, JESUS!\nEM BREVE A TROMBETA SOARÁ, \nNO CÉU COM ELE QUERO ESTAR.\nNO CÉU COM ELE QUERO ESTAR.', 'NOSSAS VIDAS SÃO MUDADAS\nPARA ANDARMOS MUI FELIZES,\nQUANDO OUVIMOS A PALAVRA,\nDO NOSSO AMIGO E JUIZ.\n\nELE JULGA A NOSSA CAUSA\nE APAGA A TRANSGRESSÃO,\nDE TODO MAL SOMOS GUARDADOS, \nCAMINHAMOS EM SUA LUZ.\n\nLUZ QUE BRILHA A CADA INSTANTE \nPARA SERMOS IDENTIFICADOS,\nNAQUELE GRANDE DIA,\nE POR JESUS ARREBATADOS.\n\nMARANATA! É O NOSSO GRITO,\nMARANATA! VEM, JESUS!\nEM BREVE A TROMBETA SOARÁ, \nNO CÉU COM ELE QUERO ESTAR.\n\nMARANATA! É O NOSSO GRITO,\nMARANATA! VEM, JESUS!\nEM BREVE A TROMBETA SOARÁ, \nNO CÉU COM ELE QUERO ESTAR.\nNO CÉU COM ELE QUERO ESTAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (187, 'VARÕES GALILEUS', 'VARÕES GALILEUS', 'VARÕES GALILEUS\nNÃO VOS MARAVILHEIS,\nESTE MESMO JESUS\nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.\n\nVARÕES GALILEUS\nNÃO VOS MARAVILHEIS,\nESTE MESMO JESUS\nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.\n\nE VOS LEVARÁ\n(E VOS LEVARÁ)\nPARA UM LAR DE PAZ \n(UM LAR DE PAZ),\nA CIDADE DE LUZ \nONDE A DOR CESSARÁ;\n\nPRANTO NÃO TEREIS \n(PRANTO NÃO TEREIS),\nQUAIS OS ANJOS SEREIS \n(ANJOS SEREIS).\nESTE MESMO JESUS \nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.', 'VARÕES GALILEUS\nNÃO VOS MARAVILHEIS,\nESTE MESMO JESUS\nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.\n\nVARÕES GALILEUS\nNÃO VOS MARAVILHEIS,\nESTE MESMO JESUS\nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.\n\nE VOS LEVARÁ\n(E VOS LEVARÁ)\nPARA UM LAR DE PAZ \n(UM LAR DE PAZ),\nA CIDADE DE LUZ \nONDE A DOR CESSARÁ;\n\nPRANTO NÃO TEREIS \n(PRANTO NÃO TEREIS),\nQUAIS OS ANJOS SEREIS \n(ANJOS SEREIS).\nESTE MESMO JESUS \nQUE HOJE VISTES SUBIR\nVOLTARÁ OUTRA VEZ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (188, 'JERUSALÉM ANSEIO VER', 'JERUSALÉM ANSEIO VER', 'JERUSALÉM ANSEIO VER,\nCIDADE SANTA CHEIA DE AMOR,\nOH! COMO É LINDO \nSEU ESPLENDOR;\nA LUZ QUE BRILHA,\nLUZ DO MEU SENHOR;\n\nRUAS DE OURO ANDAREI,\nJUNTO COM OS ANJOS TRILHAREI,\nVEREI A FACE DE JESUS \nE VIVEREI NA SUA LUZ.\n\nIREI MORAR, COM JESUS VOU HABITAR \nEM GRANDE GLÓRIA E ESPLENDOR \nCOM MEU SENHOR;\n\nLÁ NÃO HAVERÁ DOR, \nTRISTEZAS NEM DESILUSÕES,\nSEMPRE ESTAREI BEM PERTINHO \nDO MEU REI.\n\nINSTRUMENTOS\n\nJERUSALÉM ANSEIO VER,\nCIDADE SANTA CHEIA DE AMOR,\nOH! COMO É LINDO\nSEU ESPLENDOR; \nA LUZ QUE BRILHA, \nLUZ DO MEU SENHOR;\n\nRUAS DE OURO ANDAREI,\nJUNTO COM OS ANJOS TRILHAREI,\nVEREI A FACE DE JESUS \nE VIVEREI NA SUA LUZ.\n\nIREI MORAR, COM JESUS VOU HABITAR \nEM GRANDE GLÓRIA E ESPLENDOR \nCOM MEU SENHOR;\n\nLÁ NÃO HAVERÁ DOR, \nTRISTEZAS NEM DESILUSÕES,\nSEMPRE ESTAREI BEM PERTINHO \nDO MEU REI.\n\nFINAL: SEMPRE ESTAREI BEM \n PERTINHO DO MEU REI.', 'JERUSALÉM ANSEIO VER,\nCIDADE SANTA CHEIA DE AMOR,\nOH! COMO É LINDO \nSEU ESPLENDOR;\nA LUZ QUE BRILHA,\nLUZ DO MEU SENHOR;\n\nRUAS DE OURO ANDAREI,\nJUNTO COM OS ANJOS TRILHAREI,\nVEREI A FACE DE JESUS \nE VIVEREI NA SUA LUZ.\n\nIREI MORAR, COM JESUS VOU HABITAR \nEM GRANDE GLÓRIA E ESPLENDOR \nCOM MEU SENHOR;\n\nLÁ NÃO HAVERÁ DOR, \nTRISTEZAS NEM DESILUSÕES,\nSEMPRE ESTAREI BEM PERTINHO \nDO MEU REI.\n<instrumentos>\n\n\nJERUSALÉM ANSEIO VER,\nCIDADE SANTA CHEIA DE AMOR,\nOH! COMO É LINDO\nSEU ESPLENDOR; \nA LUZ QUE BRILHA, \nLUZ DO MEU SENHOR;\n\nRUAS DE OURO ANDAREI,\nJUNTO COM OS ANJOS TRILHAREI,\nVEREI A FACE DE JESUS \nE VIVEREI NA SUA LUZ.\n\nIREI MORAR, COM JESUS VOU HABITAR \nEM GRANDE GLÓRIA E ESPLENDOR \nCOM MEU SENHOR;\n\nLÁ NÃO HAVERÁ DOR, \nTRISTEZAS NEM DESILUSÕES,\nSEMPRE ESTAREI BEM PERTINHO \nDO MEU REI.\n<final>SEMPRE ESTAREI BEM \n\nPERTINHO DO MEU REI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (189, 'UM DIA A IGREJA SUBIRÁ', 'UM DIA A IGREJA SUBIRÁ', 'UM DIA A IGREJA SUBIRÁ,\nBEM MAIS PERTINHO \nDE JESUS VAMOS FICAR;\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nVAMOS JUNTOS CELEBRAR, \n\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nDE JESUS VAMOS FICAR.\n\nUM DIA A IGREJA SUBIRÁ,\nBEM MAIS PERTINHO \nDE JESUS VAMOS FICAR;\nBEM MAIS PERTINHO (3X)\nVAMOS JUNTOS CELEBRAR,\nBEM MAIS PERTINHO (3X)\nDE JESUS VAMOS FICAR.', 'UM DIA A IGREJA SUBIRÁ,\nBEM MAIS PERTINHO \nDE JESUS VAMOS FICAR;\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nVAMOS JUNTOS CELEBRAR, \n\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nBEM MAIS PERTINHO\nDE JESUS VAMOS FICAR.\n\nUM DIA A IGREJA SUBIRÁ,\nBEM MAIS PERTINHO \nDE JESUS VAMOS FICAR;\nBEM MAIS PERTINHO <bis tipo=''3x''>\nVAMOS JUNTOS CELEBRAR,\nBEM MAIS PERTINHO <bis tipo=''3x''>\nDE JESUS VAMOS FICAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (190, 'IGREJA, CORPO DE CRISTO', 'IGREJA, CORPO DE CRISTO', 'IGREJA, CORPO DE CRISTO, \nFOSTE COMPRADA\nCOM O SEU SANGUE,\nA TI EU PERTENÇO,\nJESUS JÁ ME SALVOU.\n\nCORO\nMINHA IGREJA É GLORIOSA, \nÉ A NOIVA DO SENHOR,\nJESUS VEM, SIM, BUSCÁ-LA, \nEU VOU COM O SENHOR.\n\nQUERES TU SUBIR TAMBÉM? VEM DEPRESSA PARA JESUS, \nELE TE ESPERA COM AMOR, \nVEM, VEM, DEPRESSA VEM.\n\nCORO\nMINHA IGREJA É GLORIOSA, \nÉ A NOIVA DO SENHOR,\nJESUS VEM, SIM, BUSCÁ-LA, \nEU VOU COM O SENHOR.\nJESUS VEM, SIM, BUSCÁ-LA, \nORA VEM, SENHOR JESUS.', 'IGREJA, CORPO DE CRISTO, \nFOSTE COMPRADA\nCOM O SEU SANGUE,\nA TI EU PERTENÇO,\nJESUS JÁ ME SALVOU.\n\n<coro>\nMINHA IGREJA É GLORIOSA, \nÉ A NOIVA DO SENHOR,\nJESUS VEM, SIM, BUSCÁ-LA, \nEU VOU COM O SENHOR.\n\nQUERES TU SUBIR TAMBÉM? VEM DEPRESSA PARA JESUS, \nELE TE ESPERA COM AMOR, \nVEM, VEM, DEPRESSA VEM.\n\n<coro>\nMINHA IGREJA É GLORIOSA, \nÉ A NOIVA DO SENHOR,\nJESUS VEM, SIM, BUSCÁ-LA, \nEU VOU COM O SENHOR.\nJESUS VEM, SIM, BUSCÁ-LA, \nORA VEM, SENHOR JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (191, 'A NOIVA AMADA DO CORDEIRO', 'A NOIVA AMADA DO CORDEIRO', 'A NOIVA AMADA DO CORDEIRO\nESTÁ SENDO PREPARADA\nPARA O ENCONTRO COM SEU NOIVO\nNA LINDA FESTA NO CÉU. \n\n\nCORO\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!\n \n\nSEGUE O CORDEIRO\nPARA ONDE ELE VAI,\nLÁ ESTÁ ELA, TÃO FORMOSA!\nPREPARADA JÁ ESTÁ.\n\n\nCORO\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!\n \n\nCANTARÁ UM CANTO NOVO\nE SÓ ELA SABERÁ \nPOIS SOMENTE OS REMIDOS\nESTE CANTO ENTOARÃO.\n\n\nCORO\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!', 'A NOIVA AMADA DO CORDEIRO\nESTÁ SENDO PREPARADA\nPARA O ENCONTRO COM SEU NOIVO\nNA LINDA FESTA NO CÉU. \n\n<coro>\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!\n \n\nSEGUE O CORDEIRO\nPARA ONDE ELE VAI,\nLÁ ESTÁ ELA, TÃO FORMOSA!\nPREPARADA JÁ ESTÁ.\n\n<coro>\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!\n \n\nCANTARÁ UM CANTO NOVO\nE SÓ ELA SABERÁ \nPOIS SOMENTE OS REMIDOS\nESTE CANTO ENTOARÃO.\n\n<coro>\nDIANTE DO TRONO DO CORDEIRO\nEXPRESSARÁ TODO AMOR; \nALELUIA! HONRA E GLÓRIA\nAO NOSSO SALVADOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (192, 'VOU PRA JERUSALÉM', 'VOU PRA JERUSALÉM', 'VOU PRA JERUSALÉM, \nA CIDADE DO MEU REI. \nALI VEREI JESUS,\nMEU SALVADOR, \nO FILHO DE DEUS.\n\nVOU PRA JERUSALÉM.\nEM RUAS DE OURO SEI \nQUE ANDAREI,\nDA FONTE CRISTALINA,\nLÁ DESFRUTAREI\nE A GLÓRIA ETERNA \nDE DEUS ME ILUMINARÁ.\n\nPRA SEMPRE ESTAREI\nNA ETERNA MANSÃO,\nCOM OS ANJOS, \nADORANDO O SALVADOR\nQUE EM MEU LUGAR MORREU,\nMAS VIVO ELE É,\n\nSENTADO ESTÁ NO TRONO \nCOM PODER E GLÓRIA, \nHONRA E LOUVOR, POR ISSO \nVOU PRA JERUSALÉM.\nVOU PRA JERUSALÉM.\nVOU PRA JERUSALÉM.', 'VOU PRA JERUSALÉM, \nA CIDADE DO MEU REI. \nALI VEREI JESUS,\nMEU SALVADOR, \nO FILHO DE DEUS.\n\nVOU PRA JERUSALÉM.\nEM RUAS DE OURO SEI \nQUE ANDAREI,\nDA FONTE CRISTALINA,\nLÁ DESFRUTAREI\nE A GLÓRIA ETERNA \nDE DEUS ME ILUMINARÁ.\n\nPRA SEMPRE ESTAREI\nNA ETERNA MANSÃO,\nCOM OS ANJOS, \nADORANDO O SALVADOR\nQUE EM MEU LUGAR MORREU,\nMAS VIVO ELE É,\n\nSENTADO ESTÁ NO TRONO \nCOM PODER E GLÓRIA, \nHONRA E LOUVOR, POR ISSO \nVOU PRA JERUSALÉM.\nVOU PRA JERUSALÉM.\nVOU PRA JERUSALÉM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (193, 'HÁ UMA IGREJA', 'HÁ UMA IGREJA', 'HÁ UMA IGREJA QUE AGUARDA O SENHOR,\nPOIS CONFIA NO SEU GRANDE AMOR \nQUE JESUS POR NÓS DEMONSTROU: \nPOR NOSSA VIDA UM PREÇO PAGOU!\n\n\nCORO\nVEM, SENHOR, TUA IGREJA TE ESPERA. VEM, SENHOR, TUA IGREJA TE ESPERA.\nAGUARDAMOS A TUA PROMESSA. \nVEM, SENHOR, TUA IGREJA TE ESPERA.\n\nQUANDO CRISTO NAS NUVENS \nVOLTAR E AOS CÉUS SUA IGREJA LEVAR, \nQUE ALEGRIA ENTÃO SENTIREMOS POIS COM ELE PRA SEMPRE ESTAREMOS.\n\nCORO\nVEM, SENHOR, TUA IGREJA TE ESPERA. VEM, SENHOR, TUA IGREJA TE ESPERA.\nAGUARDAMOS A TUA PROMESSA. \nVEM, SENHOR, TUA IGREJA TE ESPERA.', 'HÁ UMA IGREJA QUE AGUARDA O SENHOR,\nPOIS CONFIA NO SEU GRANDE AMOR \nQUE JESUS POR NÓS DEMONSTROU: \nPOR NOSSA VIDA UM PREÇO PAGOU!\n\n\n<coro>\nVEM, SENHOR, TUA IGREJA TE ESPERA. VEM, SENHOR, TUA IGREJA TE ESPERA.\nAGUARDAMOS A TUA PROMESSA. \nVEM, SENHOR, TUA IGREJA TE ESPERA.\n\nQUANDO CRISTO NAS NUVENS \nVOLTAR E AOS CÉUS SUA IGREJA LEVAR, \nQUE ALEGRIA ENTÃO SENTIREMOS POIS COM ELE PRA SEMPRE ESTAREMOS.\n\n<coro>\nVEM, SENHOR, TUA IGREJA TE ESPERA. VEM, SENHOR, TUA IGREJA TE ESPERA.\nAGUARDAMOS A TUA PROMESSA. \nVEM, SENHOR, TUA IGREJA TE ESPERA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (194, 'NA NOVA JERUSALÉM', 'NA NOVA JERUSALÉM', 'NA NOVA JERUSALÉM COM CRISTO IREI MORAR,\nPOIS ELE PROMETEU QUE UM DIA VIRÁ ME BUSCAR.\n\nCORO\nNA NOVA JERUSALÉM NA NOVA JERUSALÉM NA NOVA JERUSALÉM\nCOM CRISTO QUERO ESTAR.\n\nSE VOCÊ QUISER MORAR NA NOVA JERUSALÉM,\nÉ SÓ A CRISTO ACEITAR E CANTAR COMIGO TAMBÉM.\n\nNA NOVA JERUSALÉM COM CRISTO IREI MORAR,\nPOIS ELE PROMETEU QUE UM DIA VIRÁ ME BUSCAR.\n\nCORO\nNA NOVA JERUSALÉM NA NOVA JERUSALÉM NA NOVA JERUSALÉM\nCOM CRISTO QUERO ESTAR.', 'NA NOVA JERUSALÉM COM CRISTO IREI MORAR,\nPOIS ELE PROMETEU QUE UM DIA VIRÁ ME BUSCAR.\n\n<coro>\nNA NOVA JERUSALÉM NA NOVA JERUSALÉM NA NOVA JERUSALÉM\nCOM CRISTO QUERO ESTAR.\n\nSE VOCÊ QUISER MORAR NA NOVA JERUSALÉM,\nÉ SÓ A CRISTO ACEITAR E CANTAR COMIGO TAMBÉM.\n\nNA NOVA JERUSALÉM COM CRISTO IREI MORAR,\nPOIS ELE PROMETEU QUE UM DIA VIRÁ ME BUSCAR.\n\n<coro>\nNA NOVA JERUSALÉM NA NOVA JERUSALÉM NA NOVA JERUSALÉM\nCOM CRISTO QUERO ESTAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (195, 'EM BREVE ESTAREMOS NA GLÓRIA', 'EM BREVE ESTAREMOS NA GLÓRIA', 'EM BREVE ESTAREMOS NA GLÓRIA, \nA CANTAR ALELUIA AO CORDEIRO,\nAGUARDAMOS DIA E NOITE\nOUVIR O TOQUE \nDA TROMBETA DE DEUS ECOAR.\n\nVAMOS TER UMA GRANDE REUNIÃO\nNO CÉU COM O SALVADOR.\nO MOMENTO SE APROXIMA\nE A NOIVA SE APRONTA, \nAGUARDA O CHAMADO DO SENHOR. \n\nFELIZES SERVOS CHAMADOS\nPARA A GRANDE FESTA \nQUE ACONTECERÁ BREVEMENTE: \nSERÃO AS BODAS DO CORDEIRO.\n\nFELIZES SERVOS CHAMADOS\nPARA A GRANDE FESTA \nQUE ACONTECERÁ BREVEMENTE: \nSERÃO AS BODAS DO CORDEIRO. (2X)', 'EM BREVE ESTAREMOS NA GLÓRIA, \nA CANTAR ALELUIA AO CORDEIRO,\nAGUARDAMOS DIA E NOITE\nOUVIR O TOQUE \nDA TROMBETA DE DEUS ECOAR.\n\nVAMOS TER UMA GRANDE REUNIÃO\nNO CÉU COM O SALVADOR.\nO MOMENTO SE APROXIMA\nE A NOIVA SE APRONTA, \nAGUARDA O CHAMADO DO SENHOR. \n\nFELIZES SERVOS CHAMADOS\nPARA A GRANDE FESTA \nQUE ACONTECERÁ BREVEMENTE: \nSERÃO AS BODAS DO CORDEIRO.\n\nFELIZES SERVOS CHAMADOS\nPARA A GRANDE FESTA \nQUE ACONTECERÁ BREVEMENTE: \nSERÃO AS BODAS DO CORDEIRO. <bis tipo=''2x''>', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (196, 'JESUS NOS PROMETEU', 'JESUS NOS PROMETEU', 'JESUS NOS PROMETEU\nQUE VIRÁ NOS BUSCAR.\nESTE MUNDO PASSARÁ,\nTODO MAL FINDARÁ.\n\nCORO\nO TOQUE DA TROMBETA OUVIREMOS,\nO ANJO DO SENHOR A TOCARÁ.\nNAS NUVENS CELESTIAIS\nIREMOS ENCONTRAR JESUS.\n\nQUE GOZO E ALEGRIA HAVERÁ.\nA NOIVA DO SENHOR \nARREBATADA IRÁ. \nCOM JESUS PARA SEMPRE ESTARÁ.\n\nCORO\nO TOQUE DA TROMBETA OUVIREMOS,\nO ANJO DO SENHOR A TOCARÁ.\nNAS NUVENS CELESTIAIS\nIREMOS ENCONTRAR JESUS.', 'JESUS NOS PROMETEU\nQUE VIRÁ NOS BUSCAR.\nESTE MUNDO PASSARÁ,\nTODO MAL FINDARÁ.\n\n<coro>\nO TOQUE DA TROMBETA OUVIREMOS,\nO ANJO DO SENHOR A TOCARÁ.\nNAS NUVENS CELESTIAIS\nIREMOS ENCONTRAR JESUS.\n\nQUE GOZO E ALEGRIA HAVERÁ.\nA NOIVA DO SENHOR \nARREBATADA IRÁ. \nCOM JESUS PARA SEMPRE ESTARÁ.\n\n<coro>\nO TOQUE DA TROMBETA OUVIREMOS,\nO ANJO DO SENHOR A TOCARÁ.\nNAS NUVENS CELESTIAIS\nIREMOS ENCONTRAR JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (197, 'MARANATA! VEM SENHOR JESUS', 'MARANATA! VEM SENHOR JESUS', 'MARANATA! VEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA FIEL.\n\nPOR TEU SANGUE ELA FOI COMPRADA,\nRESGATADA POR TEU GRANDE AMOR\nE PELO ESPÍRITO ESTÁ SENDO ATAVIADA,\nSE PREPARANDO PARA AS BODAS \nCOM O SENHOR.\n\nMARANATA! VEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA FIEL.\n\nPOR TEU SANGUE ELA FOI COMPRADA,\nRESGATADA POR TEU GRANDE AMOR\nE PELO ESPÍRITO ESTÁ SENDO ATAVIADA,\nSE PREPARANDO PARA AS BODAS \nCOM O SENHOR.\n\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA!\nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nVEM BUSCAR TUA IGREJA FIEL.', 'MARANATA! VEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA FIEL.\n\nPOR TEU SANGUE ELA FOI COMPRADA,\nRESGATADA POR TEU GRANDE AMOR\nE PELO ESPÍRITO ESTÁ SENDO ATAVIADA,\nSE PREPARANDO PARA AS BODAS \nCOM O SENHOR.\n\nMARANATA! VEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA FIEL.\n\nPOR TEU SANGUE ELA FOI COMPRADA,\nRESGATADA POR TEU GRANDE AMOR\nE PELO ESPÍRITO ESTÁ SENDO ATAVIADA,\nSE PREPARANDO PARA AS BODAS \nCOM O SENHOR.\n\nMARANATA! \nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nMARANATA!\nVEM, SENHOR JESUS,\nVEM BUSCAR TUA IGREJA.\nVEM BUSCAR TUA IGREJA FIEL.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (198, 'O DIA ESTÁ CHEGANDO', 'O DIA ESTÁ CHEGANDO', 'O DIA ESTÁ CHEGANDO, \nAS HORAS ESTÃO PASSANDO,\nO DIA JÁ VAI CHEGAR\nE JESUS VAI VOLTAR!\n\n\nO TEMPO SE APRESSA, \nO AMOR SE ESFRIANDO, \nPESSOAS NÃO SE FALANDO. \nMAS JESUS VAI VOLTAR!\n\n\n\n\nPOIS ASSIM SERÁ QUANDO JESUS VOLTAR.\nASSIM SERÁ QUANDO JESUS VOLTAR.\nVAI VOLTAR, VAI VOLTAR!\n\nINSTRUMENTOS\n\n\nMENSAGENS REVELADAS, \nESCRITAS POR JESUS,\nPARA NOS PREPARAR,\nPORQUE JESUS VAI VOLTAR.\nPREPARANDO OS CORAÇÕES \nPARA JESUS ENCONTRAR,\nJESUS, MEU BOM PASTOR, \nQUE ME FAZ VENCEDOR.\n\n\n\n\n\nESTAMOS PREPARANDO, \nESTAMOS PREPARANDO \nOS CORAÇÕES, \nESTAMOS PREPARANDO, \nPREPARANDO OS CORAÇÕES.\nPORQUE JESUS VAI VOLTAR, \nVAI VOLTAR, VAI VOLTAR!\nVAI VOLTAR!', 'O DIA ESTÁ CHEGANDO, \nAS HORAS ESTÃO PASSANDO,\nO DIA JÁ VAI CHEGAR\nE JESUS VAI VOLTAR!\n\n\nO TEMPO SE APRESSA, \nO AMOR SE ESFRIANDO, \nPESSOAS NÃO SE FALANDO. \nMAS JESUS VAI VOLTAR!\n\n\n\n\nPOIS ASSIM SERÁ QUANDO JESUS VOLTAR.\nASSIM SERÁ QUANDO JESUS VOLTAR.\nVAI VOLTAR, VAI VOLTAR!\n<instrumentos>\n\n\nMENSAGENS REVELADAS, \nESCRITAS POR JESUS,\nPARA NOS PREPARAR,\nPORQUE JESUS VAI VOLTAR.\nPREPARANDO OS CORAÇÕES \nPARA JESUS ENCONTRAR,\nJESUS, MEU BOM PASTOR, \nQUE ME FAZ VENCEDOR.\n\n\n\n\n\nESTAMOS PREPARANDO, \nESTAMOS PREPARANDO \nOS CORAÇÕES, \nESTAMOS PREPARANDO, \nPREPARANDO OS CORAÇÕES.\nPORQUE JESUS VAI VOLTAR, \nVAI VOLTAR, VAI VOLTAR!\nVAI VOLTAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (199, 'AGUARDANDO A ORIENTAÇÃO DO SALVADOR', 'AGUARDANDO A ORIENTAÇÃO DO SALVADOR', 'AGUARDANDO A ORIENTAÇÃO \nDO SALVADOR,\nCOM JESUS MARCHAMOS, \nSEGUINDO SEM PARAR.\n\nA BANDEIRA DA VITÓRIA \nCONOSCO ESTÁ.\nOH! GLÓRIA, HOSANA AO REI!\nJESUS VENCENDO VEM!\n\nPELA FÉ AVISTAMOS NOSSO LAR,\nANSIOSOS PARA O ENCONTRO \nCOM JESUS.\nTODA LÁGRIMA ELE ENXUGARÁ.\nOH! GLÓRIA, HOSANA AO REI!\nJESUS VENCENDO VEM!\n\nINSTRUMENTOS\n\nCOM OS ANJOS \nCANTAREMOS LÁ NO CÉU\nLOUVORES AO CORDEIRO \nQUE VENCEU.\nA COROA ELE NOS DARÁ.\n\n\n\nOH! GLÓRIA! \n(GLÓRIA, GLÓRIA, GLÓRIA)\nJESUS VENCENDO VEM! \nGLÓRIA, JESUS VENCENDO VEM!', 'AGUARDANDO A ORIENTAÇÃO \nDO SALVADOR,\nCOM JESUS MARCHAMOS, \nSEGUINDO SEM PARAR.\n\nA BANDEIRA DA VITÓRIA \nCONOSCO ESTÁ.\nOH! GLÓRIA, HOSANA AO REI!\nJESUS VENCENDO VEM!\n\nPELA FÉ AVISTAMOS NOSSO LAR,\nANSIOSOS PARA O ENCONTRO \nCOM JESUS.\nTODA LÁGRIMA ELE ENXUGARÁ.\nOH! GLÓRIA, HOSANA AO REI!\nJESUS VENCENDO VEM!\n<instrumentos>\n\n\nCOM OS ANJOS \nCANTAREMOS LÁ NO CÉU\nLOUVORES AO CORDEIRO \nQUE VENCEU.\nA COROA ELE NOS DARÁ.\n\n\n\nOH! GLÓRIA! \n(GLÓRIA, GLÓRIA, GLÓRIA)\nJESUS VENCENDO VEM! \nGLÓRIA, JESUS VENCENDO VEM!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (200, 'VOU PARA O MEU LAR', 'VOU PARA O MEU LAR', 'CORO\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\n\nESTÁ CHEGANDO \nA HORA DA PARTIDA,\nJESUS JÁ VEM ME BUSCAR.\nA TROMBETA VAI ECOAR\nE VOU PARA O MEU LAR.\n \n\nCORO\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\n\nMINHA CANDEIA ESTÁ BEM ACESA\nE ÓLEO NA BOTIJA TAMBÉM HÁ.\nA TROMBETA VAI ECOAR\nE VOU PARA O MEU LAR.\n\nCORO\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.', '<coro>\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\n\nESTÁ CHEGANDO \nA HORA DA PARTIDA,\nJESUS JÁ VEM ME BUSCAR.\nA TROMBETA VAI ECOAR\nE VOU PARA O MEU LAR.\n \n\n<coro>\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\n\nMINHA CANDEIA ESTÁ BEM ACESA\nE ÓLEO NA BOTIJA TAMBÉM HÁ.\nA TROMBETA VAI ECOAR\nE VOU PARA O MEU LAR.\n\n<coro>\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.\nVOU PARA O MEU LAR, \nJESUS JÁ PREPAROU \nO MEU LUGAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (201, 'SOBRE AS NUVENS JESUS VEM', 'SOBRE AS NUVENS JESUS VEM', 'SOBRE AS NUVENS JESUS VEM \nCOMO REI E VENCEDOR,\nSUA IGREJA VEM BUSCAR\nCUMPRINDO SUA PROMESSA \nAO SEU POVO.\n \n \n\nQUE ALEGRIA VER NOSSO REI.\nMARANATA, CANTAREMOS COM FERVOR,\nPOIS SEU BRADO É DE VITÓRIA, \nALELUIA, HONRA E GLÓRIA\nLHE DAREMOS COM AMOR.\n\nCOMO IGREJA FIEL,\nTODOS UNIDOS A UMA VOZ,\nCANTAREMOS JESUS \nVEM VENCEDOR!\nJESUS VEM VENCEDOR!\nJESUS VEM VENCEDOR!', 'SOBRE AS NUVENS JESUS VEM \nCOMO REI E VENCEDOR,\nSUA IGREJA VEM BUSCAR\nCUMPRINDO SUA PROMESSA \nAO SEU POVO.\n \n \n\nQUE ALEGRIA VER NOSSO REI.\nMARANATA, CANTAREMOS COM FERVOR,\nPOIS SEU BRADO É DE VITÓRIA, \nALELUIA, HONRA E GLÓRIA\nLHE DAREMOS COM AMOR.\n\nCOMO IGREJA FIEL,\nTODOS UNIDOS A UMA VOZ,\nCANTAREMOS JESUS \nVEM VENCEDOR!\nJESUS VEM VENCEDOR!\nJESUS VEM VENCEDOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (202, 'A RAABE VEIO A ORDEM', 'A RAABE VEIO A ORDEM', 'A RAABE VEIO A ORDEM:\nNA JANELA DE SUA CASA \nCOLOCAR, UM CORDÃO \nDE FIO DE ESCARLATA \nPRA DA MORTE SE LIVRAR. \n\nELA CREU E OBEDECEU. VIU MUROS, CASAS ROLAREM, MAS SUA CASA NÃO CAIU FIO DE ESCARLATA A DEFENDEU.\n\nESTE MUNDO UM DIA PASSARÁ,\nA TERRA TREMERÁ,\nCASAS, PEDRAS VÃO ROLAR,\nMAS COM JESUS FIRME ESTAREI.\n\nSEU SANGUE É ESTE FIO \nE NELE VOU CONFIAR.\nESTAMOS PRONTOS, \nMARANATA! ORA VEM, SENHOR JESUS!\nORA VEM, SENHOR JESUS!\n\nESTAMOS PRONTOS, \nMARANATA! ORA VEM, SENHOR JESUS!', 'A RAABE VEIO A ORDEM:\nNA JANELA DE SUA CASA \nCOLOCAR, UM CORDÃO \nDE FIO DE ESCARLATA \nPRA DA MORTE SE LIVRAR. \n\nELA CREU E OBEDECEU. VIU MUROS, CASAS ROLAREM, MAS SUA CASA NÃO CAIU FIO DE ESCARLATA A DEFENDEU.\n\nESTE MUNDO UM DIA PASSARÁ,\nA TERRA TREMERÁ,\nCASAS, PEDRAS VÃO ROLAR,\nMAS COM JESUS FIRME ESTAREI.\n\nSEU SANGUE É ESTE FIO \nE NELE VOU CONFIAR.\nESTAMOS PRONTOS, \nMARANATA! ORA VEM, SENHOR JESUS!\nORA VEM, SENHOR JESUS!\n\nESTAMOS PRONTOS, \nMARANATA! ORA VEM, SENHOR JESUS!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (203, 'O FIO DE ESCARLATA O MISTÉRIO', 'O FIO DE ESCARLATA O MISTÉRIO', 'O FIO DE ESCARLATA É O MISTÉRIO, DA FÉ E DA GRAÇA DO SENHOR.\nFOI REVELADO A NÓS E NOS LIGA \nÀ PRESENÇA DE DEUS, O SENHOR.\n\nCORO\nSEGUINDO O FIO DE ESCARLATA \nVEREMOS MARANATA.\nORA VEM, SENHOR JESUS!\n\nA IGREJA TRIUNFANTE, \nENTOANDO UM NOVO CANTO, \nSUBIRÁ PRA MORAR COM JESUS. \n\nESTE FIO DE ESCARLATA REPRESENTA\nO SANGUE DE JESUS: \nNOVA ALIANÇA, VÉU RASGADO, \nNOVO CAMINHO PARA O CÉU.\n\nCORO\nSEGUINDO O FIO DE ESCARLATA \nVEREMOS MARANATA.\nORA VEM, SENHOR JESUS!\n\nFINAL:\nA IGREJA TRIUNFANTE, \nENTOANDO UM NOVO CANTO, \nSUBIRÁ PRA MORAR COM JESUS.', 'O FIO DE ESCARLATA É O MISTÉRIO, DA FÉ E DA GRAÇA DO SENHOR.\nFOI REVELADO A NÓS E NOS LIGA \nÀ PRESENÇA DE DEUS, O SENHOR.\n\n<coro>\nSEGUINDO O FIO DE ESCARLATA \nVEREMOS MARANATA.\nORA VEM, SENHOR JESUS!\n\nA IGREJA TRIUNFANTE, \nENTOANDO UM NOVO CANTO, \nSUBIRÁ PRA MORAR COM JESUS. \n\nESTE FIO DE ESCARLATA REPRESENTA\nO SANGUE DE JESUS: \nNOVA ALIANÇA, VÉU RASGADO, \nNOVO CAMINHO PARA O CÉU.\n\n<coro>\nSEGUINDO O FIO DE ESCARLATA \nVEREMOS MARANATA.\nORA VEM, SENHOR JESUS!\n\n\n<final>A IGREJA TRIUNFANTE, \nENTOANDO UM NOVO CANTO, \nSUBIRÁ PRA MORAR COM JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (204, '"MARCHAI! MARCHAI!"', '"MARCHAI! MARCHAI!"', 'CORO\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.\n\nEIS O MOMENTO! ESTAMOS ATENTOS!\nVIGILANTES, EM CONSTANTE ADORAÇÃO.\nJESUS NAS NUVENS DESCERÁ, \nSUA IGREJA LEVARÁ\nPARA A NOVA JERUSALÉM, ETERNO LAR.\n\nCORO\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.\n\nO FIO DE ESCARLATA NOS GARANTE\nAS MORADAS PREPARADAS POR JESUS.\nTUDO ESTÁ PRONTO! CANDEIA ACESA! \nSOMOS O POVO QUE O ESPÍRITO CONDUZ.\n\nINSTRUMENTOS\n\nCORO\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.', '<coro>\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.\n\nEIS O MOMENTO! ESTAMOS ATENTOS!\nVIGILANTES, EM CONSTANTE ADORAÇÃO.\nJESUS NAS NUVENS DESCERÁ, \nSUA IGREJA LEVARÁ\nPARA A NOVA JERUSALÉM, ETERNO LAR.\n\n<coro>\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.\n\nO FIO DE ESCARLATA NOS GARANTE\nAS MORADAS PREPARADAS POR JESUS.\nTUDO ESTÁ PRONTO! CANDEIA ACESA! \nSOMOS O POVO QUE O ESPÍRITO CONDUZ.\n<instrumentos>\n\n\n<coro>\n''MARCHAI! MARCHAI!''\nFIRME, SEGURA, \nCONFIANTE VAI,\nA IGREJA ADORNADA, \nPREPARADA, AO ENCONTRO \nDE SEU NOIVO VAI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (205, 'A MINHA ALMA ESPERA', 'A MINHA ALMA ESPERA', 'A MINHA ALMA ESPERA,\nNO SENHOR ESPERA \nE JUNTOS VAMOS ADORAR,\nO GRANDE REI SENHOR,\nO NOSSO EMANUEL.\nE JUNTOS VAMOS ADORAR.\n\nVEM SENHOR! A TUA IGREJA \nESPERA E NÃO VAI TARDAR.\nA NOIVA PREPARADA ESTÁ \nE A IGREJA SUBIRÁ.\n\nA NOIVA PREPARADA ESTÁ\nE A IGREJA SUBIRÁ.\n\nINSTRUMENTOS\n\nA MINHA ALMA ESPERA,\nNO SENHOR ESPERA \nE JUNTOS VAMOS ADORAR,\nO GRANDE REI SENHOR,\nO NOSSO EMANUEL.\nE JUNTOS VAMOS ADORAR.\n\nVEM SENHOR! A TUA IGREJA \nESPERA E NÃO VAI TARDAR.\nA NOIVA PREPARADA ESTÁ \nE A IGREJA SUBIRÁ.\n\nA NOIVA PREPARADA ESTÁ\nE A IGREJA SUBIRÁ.', 'A MINHA ALMA ESPERA,\nNO SENHOR ESPERA \nE JUNTOS VAMOS ADORAR,\nO GRANDE REI SENHOR,\nO NOSSO EMANUEL.\nE JUNTOS VAMOS ADORAR.\n\nVEM SENHOR! A TUA IGREJA \nESPERA E NÃO VAI TARDAR.\nA NOIVA PREPARADA ESTÁ \nE A IGREJA SUBIRÁ.\n\nA NOIVA PREPARADA ESTÁ\nE A IGREJA SUBIRÁ.\n<instrumentos>\n\n\nA MINHA ALMA ESPERA,\nNO SENHOR ESPERA \nE JUNTOS VAMOS ADORAR,\nO GRANDE REI SENHOR,\nO NOSSO EMANUEL.\nE JUNTOS VAMOS ADORAR.\n\nVEM SENHOR! A TUA IGREJA \nESPERA E NÃO VAI TARDAR.\nA NOIVA PREPARADA ESTÁ \nE A IGREJA SUBIRÁ.\n\nA NOIVA PREPARADA ESTÁ\nE A IGREJA SUBIRÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (206, 'NO CÉU UM DIA NÓS VAMOS MORAR', 'NO CÉU UM DIA NÓS VAMOS MORAR', 'NO CÉU UM DIA NÓS VAMOS MORAR\nCOM JESUS, O BOM PASTOR, \nFELIZES SEREMOS.\n\nQUANTA ALEGRIA, \nMUITOS LOUVORES.\nCANTAREMOS AO SENHOR,\nCANTAREMOS AO SENHOR, \nCANTAREMOS AO SENHOR, \nNOSSO SALVADOR!\n\nNO CÉU UM DIA NÓS VAMOS MORAR\nCOM JESUS, O BOM PASTOR, \nFELIZES SEREMOS.\n\nQUANTA ALEGRIA, \nMUITOS LOUVORES.\nCANTAREMOS AO SENHOR,\nCANTAREMOS AO SENHOR, \nCANTAREMOS AO SENHOR, \nNOSSO SALVADOR!\nNOSSO SALVADOR!', 'NO CÉU UM DIA NÓS VAMOS MORAR\nCOM JESUS, O BOM PASTOR, \nFELIZES SEREMOS.\n\nQUANTA ALEGRIA, \nMUITOS LOUVORES.\nCANTAREMOS AO SENHOR,\nCANTAREMOS AO SENHOR, \nCANTAREMOS AO SENHOR, \nNOSSO SALVADOR!\n\nNO CÉU UM DIA NÓS VAMOS MORAR\nCOM JESUS, O BOM PASTOR, \nFELIZES SEREMOS.\n\nQUANTA ALEGRIA, \nMUITOS LOUVORES.\nCANTAREMOS AO SENHOR,\nCANTAREMOS AO SENHOR, \nCANTAREMOS AO SENHOR, \nNOSSO SALVADOR!\nNOSSO SALVADOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (207, 'JESUS PROMETEU NOS BUSCAR', 'JESUS PROMETEU NOS BUSCAR', 'JESUS PROMETEU NOS BUSCAR\nARREBATAR SUA IGREJA FIEL\nCOM ELE IREMOS MORAR\nHABITAR LÁ NO CÉU\nNAS RUAS DE OURO \nIREMOS ANDAR.\n\nCORO\nOH! QUANTO ANSEIO ESTAR ALI\nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS. \n\nNÃO HÁ ALI TRISTEZA OU DOR, NEM MORTE, NEM PRANTO OU CLAMOR \nSÓ HAVERÁ SEU AMOR\nPOIS CONOSCO ESTARÁ \nCOM O CORDEIRO IREMOS AO LAR. \n\nCORO\nOH! QUANTO ANSEIO ESTAR ALI\nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS. \n\nESSE DIA ESTÁ PRA CHEGAR \nA TROMBETA ESTÁ PRA SOAR \nQUEM VENCER TUDO HERDARÁ \nCOM JESUS REINARÁ AO CORDEIRO\nIREMOS LOUVAR. \n\nCORO\nOH! QUANTO ANSEIO ESTAR ALI \nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS.\nENFIM, VOU CONTEMPLAR JESUS. \nENFIM, VOU ABRAÇAR JESUS.', 'JESUS PROMETEU NOS BUSCAR\nARREBATAR SUA IGREJA FIEL\nCOM ELE IREMOS MORAR\nHABITAR LÁ NO CÉU\nNAS RUAS DE OURO \nIREMOS ANDAR.\n\n<coro>\nOH! QUANTO ANSEIO ESTAR ALI\nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS. \n\nNÃO HÁ ALI TRISTEZA OU DOR, NEM MORTE, NEM PRANTO OU CLAMOR \nSÓ HAVERÁ SEU AMOR\nPOIS CONOSCO ESTARÁ \nCOM O CORDEIRO IREMOS AO LAR. \n\n<coro>\nOH! QUANTO ANSEIO ESTAR ALI\nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS. \n\nESSE DIA ESTÁ PRA CHEGAR \nA TROMBETA ESTÁ PRA SOAR \nQUEM VENCER TUDO HERDARÁ \nCOM JESUS REINARÁ AO CORDEIRO\nIREMOS LOUVAR. \n\n<coro>\nOH! QUANTO ANSEIO ESTAR ALI \nVER FACE A FACE O MEU REI\nENFIM, VOU ADORAR JESUS.\nENFIM, VOU CONTEMPLAR JESUS. \nENFIM, VOU ABRAÇAR JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (208, 'EU QUERO IR PARA O CÉU', 'EU QUERO IR PARA O CÉU', 'EU QUERO IR PARA O CÉU\nVER O MEU SALVADOR.\nQUE ME RESGATOU, \nSEU SANGUE ME COMPROU \n\nEU QUERO IR PARA O CÉU\nVIVER COM MEU JESUS \nANDAR NA SUA LUZ, \nPASSEAR NO SEU JARDIM. \n\nEU QUERO IR PARA O CÉU\nNAS RUAS DE OURO ANDAR\nVER AS BELAS MANSÕES,\nSUA GLÓRIA CONTEMPLAR\n\nINSTRUMENTOS\n\nEU QUERO IR PARA O CÉU\nMORAR COM MEU SENHOR \nDA ÁRVORE DA VIDA\nEU QUERO DESFRUTAR, \n\nADORAR O MEU JESUS, \nCOM OS ANJOS VOU CANTAR \nADORAR O MEU JESUS, \nCOM OS ANJOS VOU CANTAR', 'EU QUERO IR PARA O CÉU\nVER O MEU SALVADOR.\nQUE ME RESGATOU, \nSEU SANGUE ME COMPROU \n\nEU QUERO IR PARA O CÉU\nVIVER COM MEU JESUS \nANDAR NA SUA LUZ, \nPASSEAR NO SEU JARDIM. \n\nEU QUERO IR PARA O CÉU\nNAS RUAS DE OURO ANDAR\nVER AS BELAS MANSÕES,\nSUA GLÓRIA CONTEMPLAR\n<instrumentos>\n\n\nEU QUERO IR PARA O CÉU\nMORAR COM MEU SENHOR \nDA ÁRVORE DA VIDA\nEU QUERO DESFRUTAR, \n\nADORAR O MEU JESUS, \nCOM OS ANJOS VOU CANTAR \nADORAR O MEU JESUS, \nCOM OS ANJOS VOU CANTAR', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (209, 'SE EU FALO', 'SE EU FALO', 'SE EU FALO DO GRANDE\nAMOR DO PAI\nGRANDES BÊNÇÃOS \nPODEREI CONTAR.\nSE EU CANTO AS \nMARAVILHAS QUE ELE FAZ,\nO LOUVAREI ETERNAMENTE.\n\n\nGRANDE É O AMOR DO PAI, MARAVILHAS ELE FAZ\nQUANDO A IGREJA CANTA \nE ORA SEM CESSAR.\nSANTO, JUSTO E FIEL, \nSUA PROMESSA CUMPRIRÁ\nBREVE VEM NOS BUSCAR!\n\nMARANATA, JESUS VEM! \nMARANATA, JESUS VEM! \nBREVE VEM NOS BUSCAR! \nMARANATA, JESUS VEM! \nMARANATA, JESUS VEM! \nBREVE VEM NOS BUSCAR!\nBREVE VEM NOS BUSCAR!\nBREVE VEM NOS BUSCAR!', 'SE EU FALO DO GRANDE\nAMOR DO PAI\nGRANDES BÊNÇÃOS \nPODEREI CONTAR.\nSE EU CANTO AS \nMARAVILHAS QUE ELE FAZ,\nO LOUVAREI ETERNAMENTE.\n\n\nGRANDE É O AMOR DO PAI, MARAVILHAS ELE FAZ\nQUANDO A IGREJA CANTA \nE ORA SEM CESSAR.\nSANTO, JUSTO E FIEL, \nSUA PROMESSA CUMPRIRÁ\nBREVE VEM NOS BUSCAR!\n\nMARANATA, JESUS VEM! \nMARANATA, JESUS VEM! \nBREVE VEM NOS BUSCAR! \nMARANATA, JESUS VEM! \nMARANATA, JESUS VEM! \nBREVE VEM NOS BUSCAR!\nBREVE VEM NOS BUSCAR!\nBREVE VEM NOS BUSCAR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (210, 'JESUS VOLTARÁ PRA ME BUSCAR! (MARANATA)', 'JESUS VOLTARÁ PRA ME BUSCAR! (MARANATA)', 'JESUS VOLTARÁ PRA ME BUSCAR!\nO MEU CORAÇÃO ANSEIA\nPOR ESSSE ENCONTRO TÃO ESPECIAL, \nONDE TODA LÁGRIMA\nELE VAI ENXUGAR.\n\nA MINHA CANDEIA ESTÁ ACESA\nE O ÓLEO NA BOTIJA TAMBÉM HÁ.\nPOR ISSO EU CLAMO.\nPOR ISSO EU CLAMO.\n\nMARANATA! VEM, SENHOR JESUS! \nMARANATA! VEM, SENHOR JESUS! \nA TUA IGREJA TE ESPERA, \nA TUA IGREJA PROCLAMA:\nVEM, SIM, VEM JESUS.\n\nCORO \nMARANATA É O GRITO DA IGREJA,\nMARANATA É UMA FORMA DE VIDA,\nMARANATA É O DESPERTAR DO SONO,\nÉ A ESPERANÇA DA ALMA REMIDA.\n\nINSTRUMENTOS\n\nPOR ISSO EU CLAMO.\nPOR ISSO EU CLAMO.\n\nCORO \nMARANATA É O GRITO DA IGREJA,\nMARANATA É UMA FORMA DE VIDA,\nMARANATA É O DESPERTAR DO SONO,\nÉ A ESPERANÇA DA ALMA REMIDA.\n\nELE VEM! MARANATA! \nJESUS VEM! MARANATA!\nELE VEM! MARANATA! \nJESUS VEM! MARANATA!', 'JESUS VOLTARÁ PRA ME BUSCAR!\nO MEU CORAÇÃO ANSEIA\nPOR ESSSE ENCONTRO TÃO ESPECIAL, \nONDE TODA LÁGRIMA\nELE VAI ENXUGAR.\n\nA MINHA CANDEIA ESTÁ ACESA\nE O ÓLEO NA BOTIJA TAMBÉM HÁ.\nPOR ISSO EU CLAMO.\nPOR ISSO EU CLAMO.\n\nMARANATA! VEM, SENHOR JESUS! \nMARANATA! VEM, SENHOR JESUS! \nA TUA IGREJA TE ESPERA, \nA TUA IGREJA PROCLAMA:\nVEM, SIM, VEM JESUS.\n\n<coro>\nMARANATA É O GRITO DA IGREJA,<bis>\nMARANATA É UMA FORMA DE VIDA,<bis>\nMARANATA É O DESPERTAR DO SONO,<bis>\nÉ A ESPERANÇA DA ALMA REMIDA.<bis>\n<instrumentos>\nPOR ISSO EU CLAMO.\nPOR ISSO EU CLAMO.\n\n<coro>\nMARANATA É O GRITO DA IGREJA,\nMARANATA É UMA FORMA DE VIDA,\nMARANATA É O DESPERTAR DO SONO,\nÉ A ESPERANÇA DA ALMA REMIDA.\n\nELE VEM! MARANATA! \nJESUS VEM! MARANATA!\nELE VEM! MARANATA! \nJESUS VEM! MARANATA!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (211, 'OS DIAS ESTÃO PASSANDO', 'OS DIAS ESTÃO PASSANDO', 'OS DIAS ESTÃO PASSANDO,\nO MOMENTO SE APROXIMA\nDO ENCONTRO TRIUNFAL.\nA TROMBETA VAI TOCAR.\n\nA PALAVRA ME DIRIGE,\nAPONTA O CAMINHO,\nOLHO PARA O ALTO \nE VEJO A REDENÇÃO.\n\nCORO \nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).\n\nINSTRUMENTOS\n\nQUERO ESTAR CONTIGO, MEU SENHOR, (VEM, MEU SENHOR)\nVEM ME BUSCAR!\nTIRA TODA DOR E O MEU SOFRER,\nTRANSFORMA O MEU \nCHORO EM ALEGRIA.\n\nCORO \nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).\n\nCORO \nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).', 'OS DIAS ESTÃO PASSANDO,\nO MOMENTO SE APROXIMA\nDO ENCONTRO TRIUNFAL.\nA TROMBETA VAI TOCAR.\n\nA PALAVRA ME DIRIGE,\nAPONTA O CAMINHO,\nOLHO PARA O ALTO \nE VEJO A REDENÇÃO.\n\n<coro>\nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).\n<instrumentos>\n\n\nQUERO ESTAR CONTIGO, MEU SENHOR, (VEM, MEU SENHOR)\nVEM ME BUSCAR!\nTIRA TODA DOR E O MEU SOFRER,\nTRANSFORMA O MEU \nCHORO EM ALEGRIA.\n\n<coro>\nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).\n\n<coro>\nEU IREI CONTEMPLAR \nOS CÉUS ABERTOS,\nOUVIREI JESUS CHAMAR \nPELO MEU NOME,\nEU TEREI O MEU CORPO TRANSFORMADO, \nPARA ENCONTRAR O SALVADOR.\n\nEU IREI ANDAR NAS RUAS DE OURO,\nEU IREI CANTAR NO LINDO CORAL,\nEU IREI VER A ÁRVORE DA VIDA,\nESTAREI EM MEU NOVO LAR \n(ESTAREI EM JERUSALÉM).', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (212, 'SEI QUE CRISTO VOLTARÁ', 'SEI QUE CRISTO VOLTARÁ', 'SEI QUE CRISTO VOLTARÁ,\nPOIS NA BÍBLIA ESCRITO ESTÁ,\nJOÃO CATORZE, UM, DOIS, TRÊS,\nLEDE, POIS, E SABEREIS.\n\nSEI QUE ELE VOLTA, \nSEI QUE ELE VOLTA, \nSEI QUE ELE VOLTA, \nNA BÍBLIA ESCRITO ESTÁ.', 'SEI QUE CRISTO VOLTARÁ,\nPOIS NA BÍBLIA ESCRITO ESTÁ,\nJOÃO CATORZE, UM, DOIS, TRÊS,\nLEDE, POIS, E SABEREIS.\n\nSEI QUE ELE VOLTA, \nSEI QUE ELE VOLTA, \nSEI QUE ELE VOLTA, \nNA BÍBLIA ESCRITO ESTÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (213, 'LÁ NO DOCE PORVIR', 'LÁ NO DOCE PORVIR', 'LÁ NO DOCE PORVIR, \nLÁ NO DOCE PORVIR, \nLÁ NO DOCE PORVIR, \nMANSÃO DE LUZ IREI TER COM JESUS,\nAH! QUE PRAZER ME ENCONTRAR ALI!\n\nSIM, NO DOCE PORVIR,\nSIM, NO DOCE PORVIR, \nQUANDO A LUTA FINDAR\nE A VITÓRIA ALCANÇAR,\nSIM, NO DOCE PORVIR.', 'LÁ NO DOCE PORVIR, \nLÁ NO DOCE PORVIR, \nLÁ NO DOCE PORVIR, \nMANSÃO DE LUZ IREI TER COM JESUS,\nAH! QUE PRAZER ME ENCONTRAR ALI!\n\nSIM, NO DOCE PORVIR,\nSIM, NO DOCE PORVIR, \nQUANDO A LUTA FINDAR\nE A VITÓRIA ALCANÇAR,\nSIM, NO DOCE PORVIR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (214, 'NÓS RECEBEREMOS LÁ NO CÉU', 'NÓS RECEBEREMOS LÁ NO CÉU', 'NÓS RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU,\nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nUM NOME NOVO, \nUM NOME NOVO,\nNÓS TEREMOS JÁ;\nUM NOME NOVO,\nUM NOME NOVO,\nQUANDO ENTRARMOS LÁ.\n\nCORO\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nNA PEDRINHA BRANCA, EU SÓ LEREI\nESSE NOME NOVO DE JESUS;\nBRANCA MAIS QUE A NEVE\nA GUARDAREI NO REINO DE LUZ.\n\nPEDRINHA BRANCA,\nPEDRINHA BRANCA\nNÓS TEREMOS JÁ;\nPEDRINHA BRANCA,\nPEDRINHA BRANCA\nQUANDO ENTRARMOS LÁ.\n\nCORO\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nLARGA O MUNDO, \nCRÊ EM CRISTO E VEM!\nO MANÁ ESCONDIDO É PARA TI;\nSERVE, POIS, A DEUS,\nTENS TODO O BEM!\nCRISTO É TUDO ALI.\n\nMANÁ ESCONDIDO,\nMANÁ ESCONDIDO\nNÓS TEREMOS JÁ;\nMANÁ ESCONDIDO, \nMANÁ ESCONDIDO,\nQUANDO ENTRARMOS LÁ.\n\nCORO\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.', 'NÓS RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU,\nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nUM NOME NOVO, \nUM NOME NOVO,\nNÓS TEREMOS JÁ;\nUM NOME NOVO,\nUM NOME NOVO,\nQUANDO ENTRARMOS LÁ.\n\n<coro>\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nNA PEDRINHA BRANCA, EU SÓ LEREI\nESSE NOME NOVO DE JESUS;\nBRANCA MAIS QUE A NEVE\nA GUARDAREI NO REINO DE LUZ.\n\nPEDRINHA BRANCA,\nPEDRINHA BRANCA\nNÓS TEREMOS JÁ;\nPEDRINHA BRANCA,\nPEDRINHA BRANCA\nQUANDO ENTRARMOS LÁ.\n\n<coro>\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.\n\nLARGA O MUNDO, \nCRÊ EM CRISTO E VEM!\nO MANÁ ESCONDIDO É PARA TI;\nSERVE, POIS, A DEUS,\nTENS TODO O BEM!\nCRISTO É TUDO ALI.\n\nMANÁ ESCONDIDO,\nMANÁ ESCONDIDO\nNÓS TEREMOS JÁ;\nMANÁ ESCONDIDO, \nMANÁ ESCONDIDO,\nQUANDO ENTRARMOS LÁ.\n\n<coro>\nSIM, RECEBEREMOS \nLÁ NO CÉU, LÁ NO CÉU, \nO LINDO, LINDO CÉU,\nOUTRO NOME NOVO\nALÉM DO VÉU, NESSE LINDO CÉU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (215, 'EIS QUE JESUS VEM NAS NUVENS', 'EIS QUE JESUS VEM NAS NUVENS', 'EIS QUE JESUS VEM NAS NUVENS\nBUSCAR SUAS JOIAS,\nSUAS JOIAS PRECIOSAS\nDE MUITO VALOR.\n\nCORO\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.\n\nVEM BUSCÁ-LAS, VAI LEVÁ-LAS\nAO REINO CELESTE, \nSUAS JOIAS RESPLENDENTES \nDE MUITO VALOR.\n\nCORO\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.\n\nOS MENINOS E AS MENINAS\nQUE SERVEM A JESUS,\nSÃO-LHES JOIAS, RICAS\nJOIAS DE MUITO VALOR.\n\nCORO\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.', 'EIS QUE JESUS VEM NAS NUVENS\nBUSCAR SUAS JOIAS,\nSUAS JOIAS PRECIOSAS\nDE MUITO VALOR.\n\n<coro>\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.\n\nVEM BUSCÁ-LAS, VAI LEVÁ-LAS\nAO REINO CELESTE, \nSUAS JOIAS RESPLENDENTES \nDE MUITO VALOR.\n\n<coro>\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.\n\nOS MENINOS E AS MENINAS\nQUE SERVEM A JESUS,\nSÃO-LHES JOIAS, RICAS\nJOIAS DE MUITO VALOR.\n\n<coro>\nCOMO ESTRELAS DA AURORA\nBRILHANDO NA FRONTE\nDE JESUS, LÁ NA GLÓRIA,\nADORNO SERÃO.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (216, 'SOBRE AS NUVENS DESCERÁ (ELE VIRÁ)', 'SOBRE AS NUVENS DESCERÁ (ELE VIRÁ)', 'SOBRE AS NUVENS DESCERÁ\nNOSSO REI E SALVADOR;\nCOM PODER E GRANDE GLÓRIA\nAO SOAR DA TROMBETA ELE VIRÁ.\n\nCORO \nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\nTUDO AQUI HÁ DE FINDAR,\nTUDO NOVO ELE FARÁ!\nQUEM VENCER TUDO HERDARÁ\nE NO CÉU COM JESUS \nVAMOS MORAR.\n\nCORO \nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\nA NOVA JERUSALÉM\nO CORDEIRO ILUMINARÁ,\nRIO PURO HAVERÁ\nE A ÁRVORE DA VIDA\nALI ESTARÁ.\n\nCORO \nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\nCORO \nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.', 'SOBRE AS NUVENS DESCERÁ\nNOSSO REI E SALVADOR;\nCOM PODER E GRANDE GLÓRIA\nAO SOAR DA TROMBETA ELE VIRÁ.\n\n<coro>\nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\nTUDO AQUI HÁ DE FINDAR,\nTUDO NOVO ELE FARÁ!\nQUEM VENCER TUDO HERDARÁ\nE NO CÉU COM JESUS \nVAMOS MORAR.\n\n<coro>\nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\nA NOVA JERUSALÉM\nO CORDEIRO ILUMINARÁ,\nRIO PURO HAVERÁ\nE A ÁRVORE DA VIDA\nALI ESTARÁ.\n\n<coro>\nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\n\n<coro>\nELE VIRÁ (ARREBATAR)\nELE VIRÁ (NÃO TARDARÁ)\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.\nELE VIRÁ PARA BUSCAR \nA IGREJA FIEL.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (217, 'VEREI MEU GRANDE REI', 'VEREI MEU GRANDE REI', 'VEREI MEU GRANDE REI,\nUM VENCEDOR SEREI,\nVEREI O MEU JESUS!\nNOVA JERUSALÉM,\nCIDADE DO MEU REI,\nESTAREI COM MEU JESUS!\n\nCORO\nOH! QUE GLÓRIA!\nSERÁ O ENCONTRO TRIUNFAL!\nALELUIA! VEREI OS CÉUS SE ABRIREM.\nE COM OS ANJOS A CANTAR,\nNA CIDADE VOU ENTRAR.\n''ORA VEM, VEM SENHOR JESUS!''\n\nELE MORREU NA CRUZ,\nPORÉM RESSUSCITOU \nE VIVO HOJE ESTÁ.\nQUANDO ENCONTRAR JESUS, \nVEREI A SUA LUZ,\nOH! QUE GLÓRIA ETERNAL!\n\nCORO\nOH! QUE GLÓRIA!\nSERÁ O ENCONTRO TRIUNFAL!\nALELUIA! VEREI OS CÉUS SE ABRIREM.\nE COM OS ANJOS A CANTAR,\nNA CIDADE VOU ENTRAR.\n''ORA VEM, VEM SENHOR JESUS!'' VEM SENHOR JESUS.', 'VEREI MEU GRANDE REI,\nUM VENCEDOR SEREI,\nVEREI O MEU JESUS!\nNOVA JERUSALÉM,\nCIDADE DO MEU REI,\nESTAREI COM MEU JESUS!\n\n<coro>\nOH! QUE GLÓRIA!\nSERÁ O ENCONTRO TRIUNFAL!\nALELUIA! VEREI OS CÉUS SE ABRIREM.\nE COM OS ANJOS A CANTAR,\nNA CIDADE VOU ENTRAR.\n''ORA VEM, VEM SENHOR JESUS!''\n\nELE MORREU NA CRUZ,\nPORÉM RESSUSCITOU \nE VIVO HOJE ESTÁ.\nQUANDO ENCONTRAR JESUS, \nVEREI A SUA LUZ,\nOH! QUE GLÓRIA ETERNAL!\n\n<coro>\nOH! QUE GLÓRIA!\nSERÁ O ENCONTRO TRIUNFAL!\nALELUIA! VEREI OS CÉUS SE ABRIREM.\nE COM OS ANJOS A CANTAR,\nNA CIDADE VOU ENTRAR.\n''ORA VEM, VEM SENHOR JESUS!'' VEM SENHOR JESUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (218, 'MARANATA', 'MARANATA', 'CORO\nMARANATA, \nMARANATA, \nJESUS BREVE VIRÁ!\n\nEU VOU SUBIR, POIS A TROMBETA ESCUTAREI;\nE LÁ NAS NUVENS COM \nJESUS ME ENCONTRAREI.\nDESPERTA IGREJA, VAMOS SUBIR! \nO TEU LUGAR NÃO É AQUI, \nPORQUE EM BREVE JESUS VIRÁ.\n\nCORO\nMARANATA, \nMARANATA, \nJESUS BREVE VIRÁ!\n\nEU VOU SUBIR, POIS A TROMBETA ESCUTAREI;\nE LÁ NAS NUVENS COM \nJESUS ME ENCONTRAREI.\nDESPERTA IGREJA, VAMOS SUBIR! \nO TEU LUGAR NÃO É AQUI, \nPORQUE EM BREVE JESUS VIRÁ.', '<coro>\nMARANATA, \nMARANATA, \nJESUS BREVE VIRÁ!\n\nEU VOU SUBIR, POIS A TROMBETA ESCUTAREI;\nE LÁ NAS NUVENS COM \nJESUS ME ENCONTRAREI.\nDESPERTA IGREJA, VAMOS SUBIR! \nO TEU LUGAR NÃO É AQUI, \nPORQUE EM BREVE JESUS VIRÁ.\n\n<coro>\nMARANATA, \nMARANATA, \nJESUS BREVE VIRÁ!\n\nEU VOU SUBIR, POIS A TROMBETA ESCUTAREI;\nE LÁ NAS NUVENS COM \nJESUS ME ENCONTRAREI.\nDESPERTA IGREJA, VAMOS SUBIR! \nO TEU LUGAR NÃO É AQUI, \nPORQUE EM BREVE JESUS VIRÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (219, 'ELE VIRÁ NO MEIO DA NOITE', 'ELE VIRÁ NO MEIO DA NOITE', 'ELE VIRÁ NO MEIO DA NOITE,\nO NOIVO VEM BUSCAR \nA NOIVA AMADA, ELE VEM!\nPRA IR À NOVA JERUSALÉM,\nRESGATARÁ O POVO \nQUE ANDA NA LUZ.\n\nOS DIAS SÃO DE TREVAS, \nEU SEI, MAS PARA A IGREJA \nBRILHA A GLÓRIA DE CRISTO JESUS!\nENCHE TUA CANDEIA, DEIXA BRILHAR, DEIXA O ESPÍRITO SANTO BRILHAR!\n\nCORO\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA SUBIRÁ QUEM ESTIVER \nNA LUZ, ENCHE A CANDEIA\nE BRILHA O FOGO DO SENHOR! \n\nINSTRUMENTOS\n\nELE VIRÁ NO MEIO DA NOITE,\nO NOIVO VEM BUSCAR \nA NOIVA AMADA, ELE VEM!\nPRA IR À NOVA JERUSALÉM,\nRESGATARÁ O POVO \nQUE ANDA NA LUZ.\n\nOS DIAS SÃO DE TREVAS, \nEU SEI, MAS PARA A IGREJA \nBRILHA A GLÓRIA DE CRISTO JESUS!\nENCHE TUA CANDEIA, DEIXA BRILHAR, DEIXA O ESPÍRITO SANTO BRILHAR!\n\nCORO\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA\nSUBIRÁ QUEM ESTIVER \nNA LUZ, ENCHE A CANDEIA\nE BRILHA O FOGO DO SENHOR! \n\nCORO\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA \nSUBIRÁ QUEM ESTIVER NA LUZ, ENCHE A CANDEIA E BRILHA \nO FOGO DO SENHOR! \n\nENCHE A CANDEIA E BRILHA \nO FOGO DO SENHOR!', 'ELE VIRÁ NO MEIO DA NOITE,\nO NOIVO VEM BUSCAR \nA NOIVA AMADA, ELE VEM!\nPRA IR À NOVA JERUSALÉM,\nRESGATARÁ O POVO \nQUE ANDA NA LUZ.\n\nOS DIAS SÃO DE TREVAS, \nEU SEI, MAS PARA A IGREJA \nBRILHA A GLÓRIA DE CRISTO JESUS!\nENCHE TUA CANDEIA, DEIXA BRILHAR, DEIXA O ESPÍRITO SANTO BRILHAR!\n\n<coro>\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA SUBIRÁ QUEM ESTIVER \nNA LUZ, ENCHE A CANDEIA\nE BRILHA O FOGO DO SENHOR! \n<instrumentos>\n\n\nELE VIRÁ NO MEIO DA NOITE,\nO NOIVO VEM BUSCAR \nA NOIVA AMADA, ELE VEM!\nPRA IR À NOVA JERUSALÉM,\nRESGATARÁ O POVO \nQUE ANDA NA LUZ.\n\nOS DIAS SÃO DE TREVAS, \nEU SEI, MAS PARA A IGREJA \nBRILHA A GLÓRIA DE CRISTO JESUS!\nENCHE TUA CANDEIA, DEIXA BRILHAR, DEIXA O ESPÍRITO SANTO BRILHAR!\n\n<coro>\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA\nSUBIRÁ QUEM ESTIVER \nNA LUZ, ENCHE A CANDEIA\nE BRILHA O FOGO DO SENHOR! \n\n<coro>\nBRILHA EM NÓS \nO ESPÍRITO SANTO DE DEUS,\nNOS LEVANDO \nA ENCONTRAR COM JESUS!\n\nNAQUELE GRANDE DIA \nSUBIRÁ QUEM ESTIVER NA LUZ, ENCHE A CANDEIA E BRILHA \nO FOGO DO SENHOR! \n\nENCHE A CANDEIA E BRILHA \nO FOGO DO SENHOR!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (220, 'ONDE VIVE O REI DA GLÓRIA?', 'ONDE VIVE O REI DA GLÓRIA?', 'ONDE VIVE O REI DA GLÓRIA?\nVIVE EM MEU CORAÇÃO.\nONDE REINA O REI DA GLÓRIA?\nREINA EM MEU CORAÇÃO. \n\nELE FALA, ELE GUIA \nNOSSOS PASSOS A JERUSALÉM, \nPARA JUNTOS HABITARMOS\nCOM JESUS, NOSSO REI.\n\nO NOSSO REI DA GLÓRIA\nOPERA MARAVILHAS\nNO MEIO DA IGREJA,\nLIBERTA CORAÇÕES;\n\nE HOJE QUER TRANSFORMAR \nA SUA VIDA, VENHA AGORA E SINTA \nO PODER DO SALVADOR,\nALELUIA! OH, GLÓRIA!\nLOUVEMOS AO SENHOR.\n\nONDE VIVE E REINA O REI DA GLÓRIA?\nVIVE, REINA EM NOSSOS CORAÇÕES.', 'ONDE VIVE O REI DA GLÓRIA?\nVIVE EM MEU CORAÇÃO.\nONDE REINA O REI DA GLÓRIA?\nREINA EM MEU CORAÇÃO. \n\nELE FALA, ELE GUIA \nNOSSOS PASSOS A JERUSALÉM, \nPARA JUNTOS HABITARMOS\nCOM JESUS, NOSSO REI.\n\nO NOSSO REI DA GLÓRIA\nOPERA MARAVILHAS\nNO MEIO DA IGREJA,\nLIBERTA CORAÇÕES;\n\nE HOJE QUER TRANSFORMAR \nA SUA VIDA, VENHA AGORA E SINTA \nO PODER DO SALVADOR,\nALELUIA! OH, GLÓRIA!\nLOUVEMOS AO SENHOR.\n\nONDE VIVE E REINA O REI DA GLÓRIA?\nVIVE, REINA EM NOSSOS CORAÇÕES.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (221, 'VAI RAIAR O DIA', 'VAI RAIAR O DIA', 'CORO (2X)\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nGLÓRIA E MAJESTADE ESTÃO \nANTE A FACE DO SENHOR\nE FORMOSURA NO SEU SANTO LUGAR; \nANUNCIAI ENTRE AS NAÇÕES\nA SUA GLÓRIA, ENTRE OS POVOS AS SUAS MARAVILHAS.\n\nCORO\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nDAI AO SENHOR DEVIDA GLÓRIA,\nTRAZEI OFERTAS E ENTRAI \nNOS SEUS ÁTRIOS; ADORAI AO SENHOR \nEM SANTIDADE, COM LOUVOR \nADORAI A SUA FACE.\n\nCORO\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nDAI AO SENHOR GLÓRIA \nE FORÇA, BRAME O MAR \nE A SUA PLENITUDE;\nANUNCIAI A SALVAÇÃO \nDE DIA EM DIA PORQUE EM BREVE \nA VITÓRIA ALCANÇAREMOS.\n\nCORO (2X)\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.', '<coro tipo=''2X''>\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nGLÓRIA E MAJESTADE ESTÃO \nANTE A FACE DO SENHOR\nE FORMOSURA NO SEU SANTO LUGAR; \nANUNCIAI ENTRE AS NAÇÕES\nA SUA GLÓRIA, ENTRE OS POVOS AS SUAS MARAVILHAS.\n\n<coro>\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nDAI AO SENHOR DEVIDA GLÓRIA,\nTRAZEI OFERTAS E ENTRAI \nNOS SEUS ÁTRIOS; ADORAI AO SENHOR \nEM SANTIDADE, COM LOUVOR \nADORAI A SUA FACE.\n\n<coro>\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.\n\nDAI AO SENHOR GLÓRIA \nE FORÇA, BRAME O MAR \nE A SUA PLENITUDE;\nANUNCIAI A SALVAÇÃO \nDE DIA EM DIA PORQUE EM BREVE \nA VITÓRIA ALCANÇAREMOS.\n\n<coro tipo=''2X''>\nVAI RAIAR O DIA, \nDIA DA VITÓRIA,\nVAI RAIAR O DIA, DIA EM QUE \nA VITÓRIA ALCANÇAREMOS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (222, 'DEUS HABITA NO MEIO DOS LOUVORES', 'DEUS HABITA NO MEIO DOS LOUVORES', 'DEUS HABITA \nNO MEIO DOS LOUVORES, \nÓ CANTAI, IGREJA, CANTAI,\nÓ CANTAI, DEUS HABITA \nNO LOUVOR.\n\nÓ CANTAI, \nCANTAI, CANTAI, \nÓ CANTAI LOUVORES AO SENHOR;\nDEUS HABITA NO MEIO DOS LOUVORES,\nÓ CANTAI AO SENHOR.\n\nDEUS HABITA \nNO MEIO DOS LOUVORES, \nÓ CANTAI, IGREJA, CANTAI,\nÓ CANTAI, DEUS HABITA \nNO LOUVOR.\n\nÓ CANTAI, \nCANTAI, CANTAI, \nÓ CANTAI LOUVORES AO SENHOR;\nDEUS HABITA NO MEIO DOS LOUVORES,\nÓ CANTAI AO SENHOR.', 'DEUS HABITA \nNO MEIO DOS LOUVORES, \nÓ CANTAI, IGREJA, CANTAI,\nÓ CANTAI, DEUS HABITA \nNO LOUVOR.\n\nÓ CANTAI, \nCANTAI, CANTAI, \nÓ CANTAI LOUVORES AO SENHOR;\nDEUS HABITA NO MEIO DOS LOUVORES,\nÓ CANTAI AO SENHOR.\n\nDEUS HABITA \nNO MEIO DOS LOUVORES, \nÓ CANTAI, IGREJA, CANTAI,\nÓ CANTAI, DEUS HABITA \nNO LOUVOR.\n\nÓ CANTAI, \nCANTAI, CANTAI, \nÓ CANTAI LOUVORES AO SENHOR;\nDEUS HABITA NO MEIO DOS LOUVORES,\nÓ CANTAI AO SENHOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (223, 'PAI, TUA BELEZA ME ADMIRA', 'PAI, TUA BELEZA ME ADMIRA', 'PAI, TUA BELEZA ME ADMIRA,\nNO UNIVERSO QUE CRIASTE\nEU POSSO VER COMO TU ÉS\nCOMO TU ÉS; \n\nPAI, ATÉ NAS MAIS \nPEQUENAS COISAS \nEXISTE TANTA HARMONIA,\nPERFEITA É A OBRA \nDAS TUAS MÃOS.\n\nCORO\nCOM TEU PODER FUNDASTE A TERRA, \nLEVANTASTE MONTES, SEPARASTE MARES;\nNO CÉU PUSESTE O SOL E A LUA,\nSOMENTE AO TEU MANDAR \nA VIDA SE FORMOU.\n\nE DO BARRO TU FIZESTE O HOMEM\nÀ TUA IMAGEM E SEMELHANÇA\nPARA ESTAR PERANTE TI E TE LOUVAR;\n\nPAI, OUVE ESTA MINHA ADORAÇÃO,\nÉ A MAIS SINCERA EXPRESSÃO\nDO AMOR QUE HÁ DENTRO DE MIM.\n\nINSTRUMENTOS\n\nCORO\nCOM TEU PODER FUNDASTE A TERRA, \nLEVANTASTE MONTES, SEPARASTE MARES;\nNO CÉU PUSESTE O SOL E A LUA,\nSOMENTE AO TEU MANDAR \nA VIDA SE FORMOU.\n\nE DO BARRO TU FIZESTE O HOMEM\nÀ TUA IMAGEM E SEMELHANÇA\nPARA ESTAR PERANTE TI E TE LOUVAR;\n\nPAI, OUVE ESTA MINHA ADORAÇÃO,\nÉ A MAIS SINCERA EXPRESSÃO\nDO AMOR QUE HÁ DENTRO DE MIM.', 'PAI, TUA BELEZA ME ADMIRA,\nNO UNIVERSO QUE CRIASTE\nEU POSSO VER COMO TU ÉS\nCOMO TU ÉS; \n\nPAI, ATÉ NAS MAIS \nPEQUENAS COISAS \nEXISTE TANTA HARMONIA,\nPERFEITA É A OBRA \nDAS TUAS MÃOS.\n\n<coro>\nCOM TEU PODER FUNDASTE A TERRA, \nLEVANTASTE MONTES, SEPARASTE MARES;\nNO CÉU PUSESTE O SOL E A LUA,\nSOMENTE AO TEU MANDAR \nA VIDA SE FORMOU.\n\nE DO BARRO TU FIZESTE O HOMEM\nÀ TUA IMAGEM E SEMELHANÇA\nPARA ESTAR PERANTE TI E TE LOUVAR;\n\nPAI, OUVE ESTA MINHA ADORAÇÃO,\nÉ A MAIS SINCERA EXPRESSÃO\nDO AMOR QUE HÁ DENTRO DE MIM.\n<instrumentos>\n\n\n<coro>\nCOM TEU PODER FUNDASTE A TERRA, \nLEVANTASTE MONTES, SEPARASTE MARES;\nNO CÉU PUSESTE O SOL E A LUA,\nSOMENTE AO TEU MANDAR \nA VIDA SE FORMOU.\n\nE DO BARRO TU FIZESTE O HOMEM\nÀ TUA IMAGEM E SEMELHANÇA\nPARA ESTAR PERANTE TI E TE LOUVAR;\n\nPAI, OUVE ESTA MINHA ADORAÇÃO,\nÉ A MAIS SINCERA EXPRESSÃO\nDO AMOR QUE HÁ DENTRO DE MIM.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (224, 'DEUS CRIOU OS CÉUS E A TERRA', 'DEUS CRIOU OS CÉUS E A TERRA', 'DEUS CRIOU OS CÉUS E A TERRA, \nO UNIVERSO, TUDO ELE FEZ; A TERRA ERA VAZIA, COBERTA DE TREVAS, SEMELHANTE AO CORAÇÃO DO HOMEM SEM DEUS. \n\nELE TROUXE A LUZ, SEPAROU AS ÁGUAS, \nCRIOU A TERRA FIRME, AS ERVAS FEZ BROTAR,\nILUMINOU OS CÉUS COM O BRILHO DO SOL, \nLUA E ESTRELAS, \n\nENCHEU O MAR DE VIDA, \nCRIOU OS ANIMAIS,\nPREPAROU TUDO TÃO BELO PARA DEPOIS O HOMEM CRIAR. \n\nCORO\nDO NADA ELE FEZ TUDO,\nCOM SUA PALAVRA OS CRIOU, \nELE É O DEUS DA VIDA\nE TUDO ESTÁ EM SUAS MÃOS;\n\nÉ ELE QUEM MOVE OS CORAÇÕES \nPARA CONHECERMOS O SEU AMOR, \nNOS REVELANDO JESUS, \nNOSSO SALVADOR.\n\nESTA TERRA UM DIA PASSARÁ, \nNÃO MAIS EXISTIRÁ, O NOVO CÉU \nE A NOVA TERRA JESUS NOS DARÁ.\n\nCORO\nDO NADA ELE FEZ TUDO, \nCOM SUA PALAVRA OS CRIOU, \nELE É O DEUS DA VIDA\nE TUDO ESTÁ EM SUAS MÃOS;\n\nÉ ELE QUEM MOVE OS CORAÇÕES \nPARA CONHECERMOS O SEU AMOR, \nNOS REVELANDO JESUS, NOSSO SALVADOR.', 'DEUS CRIOU OS CÉUS E A TERRA, \nO UNIVERSO, TUDO ELE FEZ; A TERRA ERA VAZIA, COBERTA DE TREVAS, SEMELHANTE AO CORAÇÃO DO HOMEM SEM DEUS. \n\nELE TROUXE A LUZ, SEPAROU AS ÁGUAS, \nCRIOU A TERRA FIRME, AS ERVAS FEZ BROTAR,\nILUMINOU OS CÉUS COM O BRILHO DO SOL, \nLUA E ESTRELAS, \n\nENCHEU O MAR DE VIDA, \nCRIOU OS ANIMAIS,\nPREPAROU TUDO TÃO BELO PARA DEPOIS O HOMEM CRIAR. \n\n<coro>\nDO NADA ELE FEZ TUDO,\nCOM SUA PALAVRA OS CRIOU, \nELE É O DEUS DA VIDA\nE TUDO ESTÁ EM SUAS MÃOS;\n\nÉ ELE QUEM MOVE OS CORAÇÕES \nPARA CONHECERMOS O SEU AMOR, \nNOS REVELANDO JESUS, \nNOSSO SALVADOR.\n\nESTA TERRA UM DIA PASSARÁ, \nNÃO MAIS EXISTIRÁ, O NOVO CÉU \nE A NOVA TERRA JESUS NOS DARÁ.\n\n<coro>\nDO NADA ELE FEZ TUDO, \nCOM SUA PALAVRA OS CRIOU, \nELE É O DEUS DA VIDA\nE TUDO ESTÁ EM SUAS MÃOS;\n\nÉ ELE QUEM MOVE OS CORAÇÕES \nPARA CONHECERMOS O SEU AMOR, \nNOS REVELANDO JESUS, NOSSO SALVADOR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (225, 'EU VIM AQUI SENHOR', 'EU VIM AQUI SENHOR', 'EU VIM AQUI SENHOR, PARA AGRADECER \nPOR TUDO QUE TENS FEITO POR MIM; \nALEGRE ESTOU POR MAIS UM DIA\nNA TUA PRESENÇA, Ó DEUS. \n\nCORO\nGLÓRIA A JESUS, \nMARAVILHOSO ÉS PRA MIM,\nÉS FORTE E PODEROSO\nE CUMPRE SUAS PROMESSAS.\n\nO MEU PRAZER É TE LOUVAR\nPORQUE O SENHOR É FIEL;\nEU SEI QUE APENAS PEQUENO SOU,\nMAS SIRVO A TI POR AMOR.\n\nCORO\nGLÓRIA A JESUS, \nMARAVILHOSO ÉS PRA MIM,\nÉS FORTE E PODEROSO\nE CUMPRE SUAS PROMESSAS.', 'EU VIM AQUI SENHOR, PARA AGRADECER \nPOR TUDO QUE TENS FEITO POR MIM; \nALEGRE ESTOU POR MAIS UM DIA\nNA TUA PRESENÇA, Ó DEUS. \n\n<coro>\nGLÓRIA A JESUS, \nMARAVILHOSO ÉS PRA MIM,\nÉS FORTE E PODEROSO\nE CUMPRE SUAS PROMESSAS.\n\nO MEU PRAZER É TE LOUVAR\nPORQUE O SENHOR É FIEL;\nEU SEI QUE APENAS PEQUENO SOU,\nMAS SIRVO A TI POR AMOR.\n\n<coro>\nGLÓRIA A JESUS, \nMARAVILHOSO ÉS PRA MIM,\nÉS FORTE E PODEROSO\nE CUMPRE SUAS PROMESSAS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (226, 'IREI CANTAR E ADORAR O REI JESUS', 'IREI CANTAR E ADORAR O REI JESUS', 'IREI CANTAR E ADORAR AO REI JESUS\nQUE POR AMOR MORREU \nNA CRUZ PRA ME SALVAR;\n\nALEGRE SOU POIS SALVO ESTOU\nE ETERNAMENTE COM O SENHOR\nNAS MANSÕES CELESTIAIS IREI MORAR.\n\nOH! ALELUIA, HONRA E GLÓRIA \nAO REI JESUS! LÁ NO CÉU \nETERNAMENTE IREI CANTAR!\n\nADORAREI AO MEU SENHOR,\nPROSTRADO AOS PÉS DO SALVADOR\nQUE ENTRONIZADO ESTÁ\nPOIS ELE É O REI DOS REIS.\n\nOH! ALELUIA, HONRA E GLÓRIA \nAO REI JESUS! LÁ NO CÉU \nETERNAMENTE IREI CANTAR!\n\nADORAREI AO MEU SENHOR,\nPROSTRADO AOS PÉS DO SALVADOR\nQUE ENTRONIZADO ESTÁ\nPOIS ELE É O REI DOS REIS.', 'IREI CANTAR E ADORAR AO REI JESUS\nQUE POR AMOR MORREU \nNA CRUZ PRA ME SALVAR;\n\nALEGRE SOU POIS SALVO ESTOU\nE ETERNAMENTE COM O SENHOR\nNAS MANSÕES CELESTIAIS IREI MORAR.\n\nOH! ALELUIA, HONRA E GLÓRIA \nAO REI JESUS! LÁ NO CÉU \nETERNAMENTE IREI CANTAR!\n\nADORAREI AO MEU SENHOR,\nPROSTRADO AOS PÉS DO SALVADOR\nQUE ENTRONIZADO ESTÁ\nPOIS ELE É O REI DOS REIS.\n\nOH! ALELUIA, HONRA E GLÓRIA \nAO REI JESUS! LÁ NO CÉU \nETERNAMENTE IREI CANTAR!\n\nADORAREI AO MEU SENHOR,\nPROSTRADO AOS PÉS DO SALVADOR\nQUE ENTRONIZADO ESTÁ\nPOIS ELE É O REI DOS REIS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (227, 'A JESUS IREI LOUVAR', 'A JESUS IREI LOUVAR', 'A JESUS IREI LOUVAR,\nPOIS NA CRUZ SE DEU POR MIM.\nO SEU SANGUE DERRAMOU,\nMEU PECADO CARREGOU;\nTODA DOR ELE LEVOU,\nFOI QUEM PRIMEIRO ME AMOU.\n\nCOM QUERUBINS E SERAFINS\nA JESUS IREI LOUVAR,\nALELUIA! GLÓRIA A DEUS!\nLÁ NO CÉU EU VOU MORAR.\n\nCOM QUERUBINS E SERAFINS\nA JESUS IREI LOUVAR,\nALELUIA! GLÓRIA A DEUS!\nLÁ NO CÉU EU VOU MORAR.', 'A JESUS IREI LOUVAR,\nPOIS NA CRUZ SE DEU POR MIM.\nO SEU SANGUE DERRAMOU,\nMEU PECADO CARREGOU;\nTODA DOR ELE LEVOU,\nFOI QUEM PRIMEIRO ME AMOU.\n\nCOM QUERUBINS E SERAFINS\nA JESUS IREI LOUVAR,\nALELUIA! GLÓRIA A DEUS!\nLÁ NO CÉU EU VOU MORAR.\n\nCOM QUERUBINS E SERAFINS\nA JESUS IREI LOUVAR,\nALELUIA! GLÓRIA A DEUS!\nLÁ NO CÉU EU VOU MORAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (228, 'HOSANA AO FILHO DE DAVI', 'HOSANA AO FILHO DE DAVI', 'HOSANA AO FILHO DE DAVI,\nHOSANA AO REI DE ISRAEL;\nBENDITO O QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA.\n\nHOSANA AO QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA; \nHOSANA NAS MAIORES ALTURAS.', 'HOSANA AO FILHO DE DAVI,\nHOSANA AO REI DE ISRAEL;\nBENDITO O QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA.\n\nHOSANA AO QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA; \nHOSANA NAS MAIORES ALTURAS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (229, 'CANTAI ALEGREMENTE A DEUS', 'CANTAI ALEGREMENTE A DEUS', 'CANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS, CANTAI, CANTAI ALEGREMENTE A DEUS.\n\nTOMAI O SALTÉRIO, O ADUFE,\nA HARPA E O ALAÚDE,\nTOCAI A TROMBETA,\nÉ HORA DE SOLENIDADE.\n\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS, CANTAI,\nCANTAI ALEGREMENTE A DEUS.', 'CANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS, CANTAI, CANTAI ALEGREMENTE A DEUS.\n\nTOMAI O SALTÉRIO, O ADUFE,\nA HARPA E O ALAÚDE,\nTOCAI A TROMBETA,\nÉ HORA DE SOLENIDADE.\n\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS,\nCANTAI ALEGREMENTE A DEUS, CANTAI,\nCANTAI ALEGREMENTE A DEUS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (230, 'ESTA CANÇÃO', 'ESTA CANÇÃO', 'ESTA CANÇÃO É PARA TI, \nJESUS, DO MEU CORAÇÃO\nTIREI ESTE LOUVOR.\nMEU DEUS BENDITO, GLÓRIA, GLÓRIA;\nMEU DEUS BENDITO, GLÓRIA, GLÓRIA.\n\nO MEU LOUVOR PERTENCE SÓ A TI,\nTEUS ANJOS SEMPRE LOUVAM,\nA ELES VOU ME UNIR. \nPRA SEMPRE GLÓRIA, GLÓRIA, GLÓRIA.\nPRA SEMPRE GLÓRIA, GLÓRIA, GLÓRIA.', 'ESTA CANÇÃO É PARA TI, \nJESUS, DO MEU CORAÇÃO\nTIREI ESTE LOUVOR.\nMEU DEUS BENDITO, GLÓRIA, GLÓRIA;\nMEU DEUS BENDITO, GLÓRIA, GLÓRIA.\n\nO MEU LOUVOR PERTENCE SÓ A TI,\nTEUS ANJOS SEMPRE LOUVAM,\nA ELES VOU ME UNIR. \nPRA SEMPRE GLÓRIA, GLÓRIA, GLÓRIA.\nPRA SEMPRE GLÓRIA, GLÓRIA, GLÓRIA.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (231, 'TODO SER QUE TEM FÔLEGO', 'TODO SER QUE TEM FÔLEGO', 'TODO SER QUE TEM FÔLEGO \nLOUVE, LOUVE AO PAI, \nO SENHOR DOS SENHORES;\nTODO SER QUE TEM FÔLEGO LOUVE, LOUVE A JESUS, NOSSO REDENTOR.\n\nTODO SER QUE TEM FÔLEGO \nLOUVE, LOUVE AO \nESPÍRITO SANTO DE DEUS;\nLOUVE, LOUVE, LOUVE \nCOM CÂNTICO NOVO\nE TODO SEU SER.', 'TODO SER QUE TEM FÔLEGO \nLOUVE, LOUVE AO PAI, \nO SENHOR DOS SENHORES;\nTODO SER QUE TEM FÔLEGO LOUVE, LOUVE A JESUS, NOSSO REDENTOR.\n\nTODO SER QUE TEM FÔLEGO \nLOUVE, LOUVE AO \nESPÍRITO SANTO DE DEUS;\nLOUVE, LOUVE, LOUVE \nCOM CÂNTICO NOVO\nE TODO SEU SER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (232, 'HOJE EU NÃO QUERO PEDIR', 'HOJE EU NÃO QUERO PEDIR', 'HOJE EU NÃO QUERO PEDIR NADA A TI,\nEU SÓ QUERO LOUVAR, MEU SENHOR,\nPOIS GRANDES COISAS FIZESTES POR MIM, \nPOR ISSO ALEGRE ESTOU.\n\n\nA NOITE JÁ ACABOU, FOI-SE A DOR,\nA ALEGRIA VOLTOU EM LOUVOR;\nTUA PALAVRA É FIEL, CREIO ASSIM,\nPOR ISSO ALEGRE ESTOU.\n\nHOJE EU NÃO QUERO PEDIR NADA A TI,\nEU SÓ QUERO LOUVAR, MEU SENHOR,\nPOIS GRANDES COISAS FIZESTES POR MIM, \nPOR ISSO ALEGRE ESTOU.\n\n\nA NOITE JÁ ACABOU, FOI-SE A DOR,\nA ALEGRIA VOLTOU EM LOUVOR;\nTUA PALAVRA É FIEL, CREIO ASSIM,\nPOR ISSO ALEGRE ESTOU.', 'HOJE EU NÃO QUERO PEDIR NADA A TI,\nEU SÓ QUERO LOUVAR, MEU SENHOR,\nPOIS GRANDES COISAS FIZESTES POR MIM, \nPOR ISSO ALEGRE ESTOU.\n\n\nA NOITE JÁ ACABOU, FOI-SE A DOR,\nA ALEGRIA VOLTOU EM LOUVOR;\nTUA PALAVRA É FIEL, CREIO ASSIM,\nPOR ISSO ALEGRE ESTOU.\n\nHOJE EU NÃO QUERO PEDIR NADA A TI,\nEU SÓ QUERO LOUVAR, MEU SENHOR,\nPOIS GRANDES COISAS FIZESTES POR MIM, \nPOR ISSO ALEGRE ESTOU.\n\n\nA NOITE JÁ ACABOU, FOI-SE A DOR,\nA ALEGRIA VOLTOU EM LOUVOR;\nTUA PALAVRA É FIEL, CREIO ASSIM,\nPOR ISSO ALEGRE ESTOU.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (233, 'NA CIDADE DE DAVI NASCEU O SALVADOR', 'NA CIDADE DE DAVI NASCEU O SALVADOR', 'NA CIDADE DE DAVI \nNASCEU O SALVADOR,\nCRISTO, O SENHOR;\nMULTIDÕES DE ANJOS\nLOUVARAM A DEUS DIZENDO:\n\nCORO (2X)\nGLÓRIA A DEUS NAS ALTURAS, \nPAZ NA TERRA, BOA VONTADE \nPARA COM OS HOMENS.\n\nJESUS NASCEU\nNUM LUGAR TÃO SIMPLES,\nFOI NO MEU CORAÇÃO;\nACHOU LUGAR PRA NASCER EM MIM \nPOIS ABRI MEU CORAÇÃO \nE AGORA O SIRVO, SIRVO, SIM.\n\nCORO (2X)\nGLÓRIA A DEUS NAS ALTURAS, \nPAZ NA TERRA, BOA VONTADE \nPARA COM OS HOMENS.', 'NA CIDADE DE DAVI \nNASCEU O SALVADOR,\nCRISTO, O SENHOR;\nMULTIDÕES DE ANJOS\nLOUVARAM A DEUS DIZENDO:\n\n<coro tipo=''2X''>\nGLÓRIA A DEUS NAS ALTURAS, \nPAZ NA TERRA, BOA VONTADE \nPARA COM OS HOMENS.\n\nJESUS NASCEU\nNUM LUGAR TÃO SIMPLES,\nFOI NO MEU CORAÇÃO;\nACHOU LUGAR PRA NASCER EM MIM \nPOIS ABRI MEU CORAÇÃO \nE AGORA O SIRVO, SIRVO, SIM.\n\n<coro tipo=''2X''>\nGLÓRIA A DEUS NAS ALTURAS, \nPAZ NA TERRA, BOA VONTADE \nPARA COM OS HOMENS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (234, 'SEI QUE SOU AMADO DO MEU SALVADOR', 'SEI QUE SOU AMADO DO MEU SALVADOR', 'SEI QUE SOU AMADO \nDO MEU SALVADOR,\nSEI QUE ESTOU GUARDADO \nPELO SEU AMOR;\n\nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.\n\nCORO\nSOU FELIZ COM MEU SENHOR, (2X) \nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.\n\nNAS MANSÕES CELESTIAIS \nIREI MORAR, COM OS ANJOS DO SENHOR \nIREI CANTAR; SEU AMOR JESUS MOSTRU \nPOR MIM, UM POBRE PECADOR,\nEM MEU LUGAR MORREU \nNA CRUZ, AGORA SALVO ESTOU.\n\nCORO\nSOU FELIZ COM MEU SENHOR, (2X) \nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.', 'SEI QUE SOU AMADO \nDO MEU SALVADOR,\nSEI QUE ESTOU GUARDADO \nPELO SEU AMOR;\n\nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.\n\n<coro>\nSOU FELIZ COM MEU SENHOR, <bis tipo=''2x''> \nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.\n\nNAS MANSÕES CELESTIAIS \nIREI MORAR, COM OS ANJOS DO SENHOR \nIREI CANTAR; SEU AMOR JESUS MOSTRU \nPOR MIM, UM POBRE PECADOR,\nEM MEU LUGAR MORREU \nNA CRUZ, AGORA SALVO ESTOU.\n\n<coro>\nSOU FELIZ COM MEU SENHOR, <bis tipo=''2x''> \nDIA A DIA CAMINHANDO ESTOU INDO A JERUSALÉM,\nSEGUINDO MEU JESUS,\nEU SEI QUE EM BREVE CHEGAREI.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (235, 'SENHOR, EU TE LOUVAREI', 'SENHOR, EU TE LOUVAREI', 'SENHOR, EU TE LOUVAREI\nEM TI ME ALEGRAREI,\nDE TODO O MEU CORAÇÃO \nLOUVORES A TI DAREI.\n\nPOIS TU NOS TENS SUSTENTADO\nCOM TUA MÃO DE PODER,\nGOZO E ALEGRIA TENS DADO\nA TODO QUE EM TI CRER.', 'SENHOR, EU TE LOUVAREI\nEM TI ME ALEGRAREI,\nDE TODO O MEU CORAÇÃO \nLOUVORES A TI DAREI.\n\nPOIS TU NOS TENS SUSTENTADO\nCOM TUA MÃO DE PODER,\nGOZO E ALEGRIA TENS DADO\nA TODO QUE EM TI CRER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (236, 'SENHOR, DEUS TU ÉS VARÃO DE GUERRA', 'SENHOR, DEUS TU ÉS VARÃO DE GUERRA', 'SENHOR DEUS, TU ÉS VARÃO DE GUERRA \nE VENCE AS BATALHAS POR NÓS.\nO SOL DETÉNS SE NECESSIDADE IMPERA\nE TUDO OUVE A TUA VOZ.\n\nNÃO HÁ INIMIGO PODEROSO.\nMAJESTOSO TU ÉS,\nDEUS FORTE, VITORIOSO,\nE TUDO ESTÁ AOS TEUS PÉS.\n\nSENHOR DEUS, TU ÉS VARÃO DE GUERRA \nE VENCE AS BATALHAS POR NÓS.\nO SOL DETÉNS SE NECESSIDADE IMPERA\nE TUDO OUVE A TUA VOZ.\n\nNÃO HÁ INIMIGO PODEROSO.\nMAJESTOSO TU ÉS,\nDEUS FORTE, VITORIOSO,\nE TUDO ESTÁ AOS TEUS PÉS.', 'SENHOR DEUS, TU ÉS VARÃO DE GUERRA \nE VENCE AS BATALHAS POR NÓS.\nO SOL DETÉNS SE NECESSIDADE IMPERA\nE TUDO OUVE A TUA VOZ.\n\nNÃO HÁ INIMIGO PODEROSO.\nMAJESTOSO TU ÉS,\nDEUS FORTE, VITORIOSO,\nE TUDO ESTÁ AOS TEUS PÉS.\n\nSENHOR DEUS, TU ÉS VARÃO DE GUERRA \nE VENCE AS BATALHAS POR NÓS.\nO SOL DETÉNS SE NECESSIDADE IMPERA\nE TUDO OUVE A TUA VOZ.\n\nNÃO HÁ INIMIGO PODEROSO.\nMAJESTOSO TU ÉS,\nDEUS FORTE, VITORIOSO,\nE TUDO ESTÁ AOS TEUS PÉS.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (237, 'MUITOS MOTIVOS TENHO', 'MUITOS MOTIVOS TENHO', 'MUITOS MOTIVOS TENHO\nPARA TE ADORAR, OH, DEUS!\nTU ÉS PARA MIM O MARAVILHOSO, \nO PRÍNCIPE DA PAZ.\n\nCORO\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO\nO SENHOR NÃO HÁ.\n\nINSTRUMENTOS\n\nHOJE AQUI ESTOU A TE GLORIFICAR\nPELAS BÊNÇÃOS RECEBIDAS,\nPOR TUDO O QUE ME FAZ.\n\nCORO\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO\nO SENHOR NÃO HÁ.\n\nCORO\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO O SENHOR NÃO HÁ.\nOUTRO DEUS COMO O SENHOR NÃO HÁ.', 'MUITOS MOTIVOS TENHO\nPARA TE ADORAR, OH, DEUS!\nTU ÉS PARA MIM O MARAVILHOSO, \nO PRÍNCIPE DA PAZ.\n\n<coro>\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO\nO SENHOR NÃO HÁ.\n<instrumentos>\n\n\nHOJE AQUI ESTOU A TE GLORIFICAR\nPELAS BÊNÇÃOS RECEBIDAS,\nPOR TUDO O QUE ME FAZ.\n\n<coro>\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO\nO SENHOR NÃO HÁ.\n\n<coro>\nJESUS, TU ÉS PARA MIM \nO DEUS FIEL, MARAVILHOSO,\nOUTRO DEUS COMO O SENHOR NÃO HÁ.\nOUTRO DEUS COMO O SENHOR NÃO HÁ.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (238, 'EU VOU CANTAR', 'EU VOU CANTAR', 'EU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR. JESUS COM SEU SANGUE ME COMPROU, POR SUA GRAÇA SALVO ESTOU. \n\nEU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR.\nPERTO ESTÁ O SENHOR DE VOLTAR \nE ASSIM VOU PARA O MEU LAR.\n\nINSTRUMENTOS\n\nEU VOU CANTAR, CANTAR, CANTAR. EU VOU LOUVAR, LOUVAR, LOUVAR. JESUS COM SEU SANGUE ME COMPROU, POR SUA GRAÇA SALVO ESTOU. \n \n \n\nEU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR.\nPERTO ESTÁ O SENHOR DE VOLTAR \nE ASSIM VOU PARA O MEU LAR.', 'EU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR. JESUS COM SEU SANGUE ME COMPROU, POR SUA GRAÇA SALVO ESTOU. \n\nEU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR.\nPERTO ESTÁ O SENHOR DE VOLTAR \nE ASSIM VOU PARA O MEU LAR.\n<instrumentos>\n\n\nEU VOU CANTAR, CANTAR, CANTAR. EU VOU LOUVAR, LOUVAR, LOUVAR. JESUS COM SEU SANGUE ME COMPROU, POR SUA GRAÇA SALVO ESTOU. \n \n \n\nEU VOU CANTAR, CANTAR, CANTAR. \nEU VOU LOUVAR, LOUVAR, LOUVAR.\nPERTO ESTÁ O SENHOR DE VOLTAR \nE ASSIM VOU PARA O MEU LAR.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (239, 'JESUS É A NOSSA VITÓRIA', 'JESUS É A NOSSA VITÓRIA', 'JESUS É A NOSSA VITÓRIA\nELE NOS LEVA PARA A SUA GLÓRIA\nNOS GUARDA DE TODO O PERIGO\nJESUS É NOSSO GRANDE AMIGO.\n\nEU SOU FELIZ, POIS CONHECI A JESUS\nE HOJE EU CAMINHO EM SUA LUZ\nNA ETERNIDADE COM JESUS VOU MORAR\nE COM OS ANJOS PARA SEMPRE O ADORAR:\n\nVIVA O REI, VIVA O REI\nVIVA O REI, VIVA O REI\nVIVA O REI, \nVIVA O REI JESUS!\nVIVA O REI JESUS!', 'JESUS É A NOSSA VITÓRIA\nELE NOS LEVA PARA A SUA GLÓRIA\nNOS GUARDA DE TODO O PERIGO\nJESUS É NOSSO GRANDE AMIGO.\n\nEU SOU FELIZ, POIS CONHECI A JESUS\nE HOJE EU CAMINHO EM SUA LUZ\nNA ETERNIDADE COM JESUS VOU MORAR\nE COM OS ANJOS PARA SEMPRE O ADORAR:\n\nVIVA O REI, VIVA O REI\nVIVA O REI, VIVA O REI\nVIVA O REI, \nVIVA O REI JESUS!\nVIVA O REI JESUS!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (240, 'O SENHOR DOS EXÉRCITOS ESTÁ AQUI', 'O SENHOR DOS EXÉRCITOS ESTÁ AQUI', 'O SENHOR DOS EXÉRCITOS ESTÁ AQUI, (BIS)\nELE É O REI DA GLÓRIA,\nDEUS FORTE E PODEROSO\nNAS BATALHAS.\n\nCORO (2X)\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER. \n\nGLÓRIA E MAJESTADE AO SENHOR\nPOIS ÉS DIGNO DE LOUVOR. \nGLÓRIA E MAJESTADE AO SENHOR \nPOIS ÉS DIGNO DE LOUVOR. \n\nCORO (2X)\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER. \n\nO SENHOR DOS EXÉRCITOS ESTÁ AQUI \nO SENHOR DOS EXÉRCITOS ESTÁ AQUI \nELE É MARAVILHOSO, CONSELHEIRO,\nPRÍNCIPE DA PAZ. \n\nCORO (2X)\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER.', 'O SENHOR DOS EXÉRCITOS ESTÁ AQUI, <bis>\nELE É O REI DA GLÓRIA,\nDEUS FORTE E PODEROSO\nNAS BATALHAS.\n\n<coro tipo=''2X''>\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER. \n\nGLÓRIA E MAJESTADE AO SENHOR\nPOIS ÉS DIGNO DE LOUVOR. \nGLÓRIA E MAJESTADE AO SENHOR \nPOIS ÉS DIGNO DE LOUVOR. \n\n<coro tipo=''2X''>\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER. \n\nO SENHOR DOS EXÉRCITOS ESTÁ AQUI \nO SENHOR DOS EXÉRCITOS ESTÁ AQUI \nELE É MARAVILHOSO, CONSELHEIRO,\nPRÍNCIPE DA PAZ. \n\n<coro tipo=''2X''>\nA ELE SEJA O LOUVOR,\nTODA A GLÓRIA,\nHONRA E PODER.', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (241, 'EXALTAI, EXALTAI', 'EXALTAI, EXALTAI', 'EXALTAI, EXALTAI, \nAQUELE QUE MORREU \nNA CRUZ PARA NOS SALVAR \nE HOJE VIVO ESTÁ \nPARA A VITÓRIA NOS DAR. \n\n\nEXALTAI, EXALTAI, \nAQUELE QUE MORREU \nNA CRUZ PARA NOS SALVAR \nE HOJE VIVO ESTÁ \nPARA A VITÓRIA NOS DAR. \n\nINSTRUMENTOS\n\n\nACLAMAI, ACLAMAI, \nPOIS DIGNO DE ABRIR \nO LIVRO O CORDEIRO É; \nBREVE JESUS VIRÁ, \nSUA IGREJA FIEL LEVARÁ, \nBREVE JESUS VIRÁ. \n\nACLAMAI, ACLAMAI, \nPOIS DIGNO DE ABRIR \nO LIVRO O CORDEIRO É; \nBREVE JESUS VIRÁ, \nSUA IGREJA FIEL LEVARÁ, \nBREVE JESUS VIRÁ. \nMARANATA! ALELUIA!', 'EXALTAI, EXALTAI, \nAQUELE QUE MORREU \nNA CRUZ PARA NOS SALVAR \nE HOJE VIVO ESTÁ \nPARA A VITÓRIA NOS DAR. \n\n\nEXALTAI, EXALTAI, \nAQUELE QUE MORREU \nNA CRUZ PARA NOS SALVAR \nE HOJE VIVO ESTÁ \nPARA A VITÓRIA NOS DAR. \n<instrumentos>\n\n\nACLAMAI, ACLAMAI, \nPOIS DIGNO DE ABRIR \nO LIVRO O CORDEIRO É; \nBREVE JESUS VIRÁ, \nSUA IGREJA FIEL LEVARÁ, \nBREVE JESUS VIRÁ. \n\nACLAMAI, ACLAMAI, \nPOIS DIGNO DE ABRIR \nO LIVRO O CORDEIRO É; \nBREVE JESUS VIRÁ, \nSUA IGREJA FIEL LEVARÁ, \nBREVE JESUS VIRÁ. \nMARANATA! ALELUIA!', 2, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
